window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"조선 명종 때의 문신인 희중 민제인(1493∼1549) 선생의 시문집을 새긴 목판이다. 민제인은 중종 15년(1520) 문과에 급제하여 승정원주서, 사간원정언, 사헌부대사헌, 형조참판 등의 벼슬을 지냈다. 을사사화를 주도하여 윤임 등을 제거하는데 앞장섰으며, 1547년 좌찬성에 오른 후에는 민심을 안정시키는데 노력하였다. 1548년 윤원형 등이 을사사화를 감추고자 당시 관련 기록을 쓰고 있던 안명세를 죽이고 기록을 고치려 하자 이의 불가함을 고했고, 결국 그들의 미움을 사 공주로 귀양을 갔다.","a":"민입암집판각","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661499.jpg"},{"q":"화암사 뒷편에 자리한 2개의 바위에 각각 ‘시경(詩境)’, ‘천축고선생택(天竺古先生宅)’이라 새겨 놓은 것으로, 모두 추사 ○○○ 선생의 글씨이다. 이 곳에서 500여m 떨어진 곳에 ‘소봉래(小蓬來)’라는 글귀가 있으며, 이 글귀 밑으로 ‘추사제(秋史題)’라 쓴 작은 글씨도 보인다.","a":"김정희선생필적암각문","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653077.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 지방의 교육기관이다. 고려 공민왕 6년(1357)에 반월산 아래에 처음 지었고 조선 태종(재위 1400∼1418)대에 송릉동으로 옮겼다가 광해군 4년(1612)에 지금 있는 자리로 다시 옮겨 세운 것이다. ○○○은 성종 원년(1470)과 1976년에 보수하였다. 지금 남아 있는 건물로는 ○○○과 동무·서무, 교육 공간인 명륜당, 휴식공간인 태화루 등이 있다. ○○○은 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 제사를 지내는 곳이다.","a":"평해향교 대성전","c":"문화유산자료","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662715.jpg"},{"q":"○○○○전 아미타삼존상 후면을 가득 채우고 있는 불상으로 본존인 아미타불상과 유사한 형태로 만들어졌다. 전체높이가 약 17.9cm 정도인 아주 작은 불상들인데 그 수가 1,500구(軀)에 이른다. 이 ○○○○○은 신중도상의 화기와 『○○○지(安養庵誌)』의 기록을 종합적으로 볼 때 1933년 조성하기 시작하여 1937년 그 불사(佛事)가 끝난 것으로 보인다. ○○○의 ○○○○○은 우리나라에서 거의 유일한 예이고 석고불(石膏佛)로서는 초기에 속하는 희귀한 불상이기도 하며 20세기 전반의 다불신앙(多佛信仰)을 보여주는 좋은 예이다.","a":"안양암 천오백불상","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314110900.jpg"},{"q":"두륜산 중턱에 위치한 ○○○는 신라 진흥왕 5년(544)에 아도화상이 지은 유서 깊은 사찰이다. 현재 ○○○는 절의 북쪽에서 흘러내리는 금당천을 중심으로 남·북이 나뉘었는데, 남·북원의 법당들은 나름대로의 특색을 지니고 있다. 비로자나불을 모시고 있는 ○○○○은 표충사 동쪽에 위치하였으며, 초의선사가 조선 헌종 7년(1841)에 다시 지은 것이다. 앞면 3칸·옆면 3칸의 규모이며, 지붕의 옆선이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 내부는 불단이 있는 중앙부 위에만 우물 정(井)자 모양의 천장을 높게 달고, 연꽃무늬와 구름·학 등을 그렸다.","a":"대흥사대광명전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639934.jpg"},{"q":"○○○터에 남아있는 것으로, 석등 받침돌의 일부이다. 모두 2기가 남아있어 1기는 동쪽의 새로 복원해 놓은 석탑과 법당터 사이에 있고, 다른 1기는 중앙의 목탑터와 법당터 사이에 있다. 보통 석등은 불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 3단의 받침돌을 두고 위로는 지붕돌과 머리장식을 얹어두는데, 이들은 3단의 받침돌 중 아래받침돌까지만 남아있다. 사각의 바닥돌 위에 놓인 아래받침돌은 윗면에 8잎의 연꽃을 두르고 그 사이에도 작은 잎을 조각해두었다.","a":"미륵사지석등하대석","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661796.jpg"},{"q":"조선 중기의 문신인 ○○○을 그린 초상화이다. 평안도 관찰사를 지낸 ○○○의 업적을 기리기 위해 평양의 서리와 백성들이 세운 생사당(生祠堂)에 걸렸던 초상화이다. 그런데 전반적인 초상화의 형식이 ○○○이 살았던 시대의 초상화와 맞지 않다. 가슴에 흉배가 지나치게 크고, 양 손도 나와 있으며, 관복의 형태도 특이하다. 문집에서 ○○○은 평양의 서리들이 몰래 화원을 시켜 자신을 그렸다고 했다. 즉 이 화가는 ○○○을 뒤따라 다니면서 몰래 그린 밑그림들을 모아서 이 초상화를 완성시킨 것이다. 그렇지만 초상화의 세부묘사는 치밀하고 완성도가 높다.","a":"이원익선생영정","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637469.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 경상남도 사천시 와룡산에서 뻗어내린 해발 310m의 봉우리 정상에 있는 이 ○○○는 봉수터와 둘레 100m의 성터가 남아 있었는데, 1994년도에 ○○○ 5개소, 성지 100m를 원형대로 복원하였다. 『경상도속찬지리지』에 따르면 남쪽으로 각산 ○○○, 북쪽으로 진주의 망진산 ○○○와 연결되었으며, 조선 세종 때 설치한 것으로 추정한다.","a":"사천안점산봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656167.jpg"},{"q":"이 책판은 조선 명종과 선조 때의 문신인 동강 ○○○ 선생이 선조 18년(1585)에 펴낸 역사책이다. ○○○은 남명 조식의 문인으로, 명종 22년(1567)에 문과에 급제하여 홍문정자, 병조참판, 대사성을 거쳐 대사헌의 벼슬을 지냈다. 학문에 능하였으며, 『동강집』을 남겼다. ○○○이 책을 만든 후 110여 년이 지나는 도안 판이 썩고 벌레가 먹어 다시 찍어내는 것이 불가능해지자 1924년 그의 후손인 김성림이 경상도 유학자들의 뜻을 모아 다시 간행하였고, 이것이 이 속강목책판이다.","a":"김우옹 동강문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641759.jpg"},{"q":"경상남도 함양군 서상면 들판에 있는 ○○○의 9부능선을 따라 서쪽 방향으로 쌓은 산성이다. 이 성은 삼국시대에 백제가 신라를 침범하여 약탈을 일삼자 이를 막기 위하여 성을 쌓고 쌀을 비축했다고 해서 ‘합미성’이라고 하며, 일명 ‘금당성’이라고도 한다. 또한 마을 앞산 봉우리가 연못에 떠 있는 연꽃같다고 하여 꽃다운 못, 즉 ‘방지’라 이름하였다 한다. 현재 성벽은 윗부분이 무너져 성의 윤곽을 확인하기 어려우나, 가로 45㎝, 세로 30㎝ 크기의 자연석과 깬돌 이용하여 높이 3∼4m 정도로 쌓았는데, 지금은 약 500m 정도만 남아 있다.","a":"함양방지산성","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656143.jpg"},{"q":"충남 아산시에 있는 어의정은 세종대왕이 온양에 와서 눈병을 치료했다는 우물로, ‘어의정’, ‘어천’, ‘어정수’라 불리운다. 우물의 기본적인 시설은 모습이 바뀌었는데, 본래 우물의 윗부분에 흩어져 있던 화강석을 모아, 길이 약 120m, 높이 0.5m의 사각형 구조로 복원하였다. 이 시설은 일반 우물에 비해 특별히 크고 독특한 편이다. 주민들의 전하는 말에 의하면 우물을 만든 돌에 ‘어천’이라는 글이 있었다고 한다.","a":"온양어의정","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661408.jpg"},{"q":"한말의 위정척사론자이며 의병장인 의암(毅菴) ○○○의 묘역이다. 헌종 8년(1842) 춘천시 남면에서 태어나 14세 때에는 친척인 중선에게 입양되었다. 이를 계기로 이항로의 문하에 들어가 학문을 배웠으며 그곳에서 김평묵과 유중교로부터 오랑캐를 배척하는 존화양이(尊華攘夷)사상을 익혔다. 고종 32년(1895) 을미사변과 단발령을 계기로 의병운동을 시작하여 크게 활약하였으나, 관군의 공격으로 모두 흩어지게 되었다. 이후 1908년 해외로 망명한 후 1910년 6월 연해주 의병세력의 통합체인 13도의군(十三道義軍)을 결성하였고 여기에서 도총재로 추대되었다.","a":"춘천의암유인석묘역","c":"시도기념물","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648481.jpg"},{"q":"유하마을 뒷산 일원에 분포되어 있는 선사시대의 유적으로써 일부 하손부락 뒷산의 동남단에 형성되어 있는 이 ○○○○은 우리나라 역사상 기원 전 후기에 해당되는 초기철기시대에 살던 사람들이 조개를 먹고 버림으로써 이루어진 조개무지이다. 정식으로 발굴 조사가 되지 않아 정확한 유적의 성격은 알 수 없으나 넓은 범위에 걸쳐 있음을 알 수 있고 지표면에 흩어져 있는 조개껍질로 볼때 주로 굴껍질이 대부분을 이루고 있을 것으로 보고 있다. 이는 ○○일대에 분포하고 있는 다른 패총 유적과 거의 같은 시기에 형성되었을 것으로 추정된다.","a":"김해 유하패총","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654951.jpg"},{"q":"○○○는 재약산 남쪽 기슭에 있는 절로 원래 이곳에는 신라 무열왕 1년(654)에 원효대사가 지은 죽림사가 있었는데, 통일신라 흥덕왕 4년(829)에 왕의 셋째 아들이 병으로 고생할 때 이곳의 영정약수를 먹고 병이 나았다고 해서 영정사라 이름을 바꾸었다고 한다. 그 후 조선 숙종 41년(1715)에 다시 지었고, 헌종 5년(1839)에 임진왜란 때 승병을 일으켜 나라에 공을 세운 사명대사를 추모하기 위해 사당을 짓고 ○○○라 하였다. ○○○은 ○○○ 경내에 있는 절로 대적광전이라고도 하며, 비로자나불을 모시는 법당이다.","a":"밀양 표충사 대광전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641679.jpg"},{"q":"이 불상은 1930년대까지 야산의 산 속에 묻혀 머리부분만 노출되어 있던 것을 그 후 ○○○의 법당 안에 모셔 봉안하고 있다. 거대한 자연석을 다듬어 앞부분에는 불상을 조각하고 뒷면은 조각없이 그대로 처리하였는데, 높이 280㎝, 어깨폭 148㎝, 앉은 높이가 3m에 달하는 거불(巨佛)이다. 워낙 거대한 자연석을 이용하여 조각하여서인지 전체적으로 둔중한 느낌을 주는 한편 얼굴과 옷자락의 조각은 사실적인 수법을 보여준다. 머리에는 상투 모양의 육계가 큼직하게 솟아 있고, 소라 모양의 머리칼인 나발이 표현된 흔적이 있으나 현재는 많이 마멸되었다.","a":"미륵사석불좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639729.jpg"},{"q":"송계별업은 인조의 셋째 왕자인 인평대군(麟坪大君) 이요(李㴭, 1622~1658)의 유적지이다. 인평대군은 이곳에 머물기도 하면서 호를 송계(松溪)라 하였고, 자신의 문객(門客) 이신(李伸)에게 ‘구천은폭’을 써서 폭포 옆에 새기게 하는 등 이곳에 많은 애착을 가지고 있었다. 그러나 1658년 인평대군이 30대의 젊은 나이에 죽은 뒤 송계별업은 그의 아들들에게 넘겨져 가끔 이용하였을 것이다. 인평대군의 아들인 복창군 이정(李楨), 복선군 이남(李枏)과 복평군 이연(李㮒)은 종친으로서 너무 정치에 깊숙이 관련되었는데 특히 남인들과 친밀하였다.","a":"사릉 석물 채석장 터","c":"시도기념물","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020010713345300.JPG"},{"q":"조선시대 무신인 하경복(1377∼1438) 선생의 위패를 모신 사당이다. 하경복은 태종 2년(1402) 무과에 급제하고 여러 관직을 거쳐 병마사, 병마절제사가 되어 국방을 수비하였다. 15년 동안 국경지대에서 여진족과 대치하며 경비에 철저했으며 특히 세종 15년(1433) 정흠지, 황보인 등과 함께 『계축진설』을 펴내 군사 교육의 교재로 삼았다. 성품이 너그럽고 활을 잘 쏘았으며 개국 초기 철저히 국방을 지켜 국가의 기틀을 마련하는데 큰 공을 세웠다.","a":"하동 경현사","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664244.jpg"},{"q":"○○○ 마을의 한 민가 안에 서 있는 한쌍의 돌장승이다. 장승은 마을이나 사찰입구에 세워 잡귀나 액운의 출입을 막고 사찰내의 재산과 경계를 표시하는 민간 신앙물로, 마을의 수호신이 되기도 한다. 이 장승은 각각 환웅과 단군 두분을 상징하는 것으로, 단군상은 크기 182㎝, 두상 55㎝, 밑둘레 158㎝이며 환웅상은 크기 172㎝, 두상 56㎝, 밑둘레 140㎝이다. 단군상은 앞면 가슴에 ‘왕검(王儉)’, 뒷면에는 ‘장백산(長白山)’이라 새기고, 환웅상은 앞면 가슴에 ‘환웅(桓䧺)’, 뒷면에는 ‘구룡연(九龍淵)’이라 새겨 놓았다.","a":"월천리석장승","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658325.jpg"},{"q":"○○○ 삼성각에 보존하고 있는 그림으로, 크기가 가로 211.5㎝, 세로 97.2㎝이며 비단 바탕에 채색하였다. 칠성신을 의인화하여 묘사한 것으로, 화폭의 좌우대칭으로 무리들을 배치하고 상하 2단으로 나눈 수평구조이다. 근엄함이나 신격이 사라진 각 상들의 모습, 경직된 형태와 선, 그리고 탁한 색채 등은 20세기 초 당시의 불화기법을 잘 반영하고 있다.","a":"지장사 칠성도","c":"문화유산자료","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102513340600.jpg"},{"q":"금정중학교 법당에 봉안되어 있는 ○○○○○은 전체 크기가 48㎝인 소형 석불이다. 머리 부분과 불상 바닥을 제외한 전면에 개금이 되어 있으며, 파손된 곳이 거의 없는 등 보존상태는 양호한 편이다. 전체적인 형태는 신체보다 다소 큰 머리 부분을 지닌 형태에 목이 짧고 등을 곧추 세운 후 고개를 앞으로 약간 숙인 모습이다. 수평적으로 반쯤 뜬 눈, 콧날이 곧고 바른 코, 양 꼬리를 살짝 올려 미소를 머금은 입, 이마에서 어깨에 닿을 정도로 큼직하게 처리한 귀 등이 새겨져 있는 등 조선후기 불상에서 보여주던 근엄함이 다소 풀어진 원만한 상호를 보여주고 있다.","a":"석조여래좌상","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659412.jpg"},{"q":"조선 초기의 문신이며 학자인 괴애(乖崖) ○○○ 선생의 ○○이다. 세종 23년(1441)에 문과에 급제하여 세종의 특명으로 집현전 학사가 되어『치평요람』을 편찬하였으며, 그 후『의방유취』편찬에도 참여하였다. 세조 15년(1466)에는 판중추부사에 올랐으며, 성종 2년(1471)에는 좌리공신 4등으로 영산부원군에 봉해졌다. 선생은 학문과 문장에 뛰어나 서거정, 성삼문 등 당대의 학자들과 함께 이름을 떨쳤으며,『사서오경』의 토를 만들고,『명황계감』을 번역하는 등 번역과 간행사업에 많은 업적을 이루었다.","a":"영동 김수온 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650038.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모시는 곳이다. ○○○ 경내에는 동북쪽 4기와 계곡에 6기 등 총 10기의 부도가 있는데, 이 ○○○○는 동북쪽에 있는 4기 중 3번째에 자리하고 있는 것이다. 형태는 연꽃을 새긴 바닥돌 위에 배부른 원통모양의 탑신(塔身)을 올린 모습이다. 탑신은 맨 위에 구름을, 가운데에는 두 마리의 큰 용이 서로 휘어감으면서 여의주를 빼앗으려는 모습을, 맨 밑에는 연꽃을 새겨 장식하였다. 꼭대기에는 머리장식이 놓여 있는데 원래의 것이 아니다. 탑신 전체에 가득히 새긴 생동감 있는 조각수법으로 보아 고려시대의 작품으로 추정된다.","a":"대원사용각부도","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639470.jpg"},{"q":"○○○에 있는 석탑으로, 1층 기단(基壇) 위로 3층의 탑신(塔身)을 올린 모습이다. 기단에는 아무런 장식을 하지 않았고, 2·3층 몸돌이 없어진 탑신은 남아 있는 1층 몸돌 모서리마다 기둥 모양을 얕게 새겨 놓았다. 지붕돌은 네 귀퉁이가 뾰족하게 치켜 올려갔고, 밑면에 1 ·2층은 3단, 3층은 2단의 받침을 각각 두었다. 고려 후기에 세운 것으로 추측되고 있으며, 전체적으로 각 층의 지붕돌 너비가 거의 줄지 않고 있어 원래는 높고 날렵한 큰 규모의 탑이었을 것으로 보인다.","a":"수타사삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2304311.jpg"},{"q":"속리산 ○○○ 내에 있는 자정국존의 비이다. 자정국존(1240∼1327)은 국령사·장의사·○○○ 등 여러 사찰의 주지를 지냈으며, 도승통이 되기도 하였고, 호는 ‘보명’이다. 비는 길쭉한 직사각형의 모습으로 자연암반을 파내어 비몸을 세운 특이한 형태이다. 비몸 앞면에는 자정국사에 관한 비문을 새겼는데, 아랫부분이 일부 파손되어 있다. 고려 충혜왕 복위 3년(1342)에 세운 것으로, 왕의 명을 받은 이숙기가 비문을 짓고, 전원발이 글씨를 썼다.","a":"보은 법주사 자정국존비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638506.jpg"},{"q":"조선 숙종 때 ○○○의 무덤에서 나온 관 뚜껑이다.영의정 최석정이 임금님께서 경서를 강의하던 자리에서, 제운리(현재 학익동)에 서당을 열어 많은 인재들을 양성하고 있던 ○○○ 선생에 대해 말하였다. 그러자 숙종은 그에게 벼슬을 주고 직접 만나보기도 하였다. 처음에 이선생의 무덤은 연수구 동춘동에 있었으나, 개발사업으로 이장해 옮겨 두었다. 출토 당시에 관을 덮었던 선생의 이름과 관직이 쓰여진 명정(銘旌)이 관 뚜껑에 붙어 있었다고 한다.","a":"이세주 묘 관 덮개","c":"문화유산자료","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659539.jpg"},{"q":"장도 청해진으로부터 서북쪽으로 약 2㎞ 떨어진 상왕산 아래에 있는 ○○○터이다. ○○○는 주민들에 의해 전해진 구전내용과 문헌기록으로 미루어 보아 통일신라 말 장보고(?∼846)가 지은 절로 그의 해상활동과 긴밀한 관련이 있었던 것으로 추정된다. 당시 이 절은 신라 문화의 해외진출과 함께 입당한 구법승들의 중간휴식처 구실을 했으며, 중국 당나라에서 일본에 파견된 사절단들의 영빈관 구실도 겸했다고 한다. 또 중국의 산동성 적산촌에 있는 법화원과도 서로 교류가 되었던 곳이다.","a":"완도법화사지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102217303400.jpg"},{"q":"○○○는 점찰산 서쪽 기슭에 있는 절로 문성왕 19년(857)에 도선국사가 지었으며, 인조 26년(1648)에 의웅이 다시 지어서 오늘에 이르고 있다. ○○○○○은 석가모니를 모시는 법당이다. 지어진 연대는 1982년 수리할 때 발견된 기록에 숙종 23년이라 쓰여져 있어 정확히 1697년에 세워졌음을 알 수 있다. 앞면 3칸·옆면 2칸으로 지붕은 옆면이 사람 인(人)자 모양으로 가장 단순한 맞배지붕이다. 문의 가운데 칸은 4짝으로 빗살문이며, 양쪽 끝칸은 3짝으로 띠살문이다.","a":"쌍계사대웅전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639983.jpg"},{"q":"○○○○○은 마을 앞에 흐르고 있는 개울 양편에 있으며, 농지를 해풍으로부터 보호하기 위해 심은 방풍림으로 생각된다. 전하는 말에 의하면, 이 마을이 풍수지리적으로 호랑이 형태인데 꼬리가 없어서 그 보완책으로 마을 사람들이 호랑이 꼬리 모양으로 길다랗게 나무를 심었다고 한다. ○○○의 길이는 약 450m에 이르며, 숲을 이루고 있는 나무들의 나이는 대부분 100∼200년 정도이고 가장 오래된 것이라도 300년 정도로 추정된다. 이 숲을 이루고 있는 나무는 푸조나무, 팽나무, 느티나무 등 우리나라 향토수종으로 구성되어 있으며, 그 중 푸조나무가 가장 많다.","a":"여수 호명동 방재림","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654318.jpg"},{"q":"대구 최초의 선교사인 ○○○가 미국 선교부로부터 건축비를 지원받아 1908년에 건립한 영남 최초의 양옥(洋屋) 교사(校舍)이다. 건축의 설계는 ○○○ 선교사가 직접하고 건축공사는 그의 감독하에 중국인 벽돌공과 일본인 목수들이 담당하였다 한다. 이 건물에 사용된 창호 재료, 유리, 위생, 난방시설 등은 미국에서 가져왔고, 붉은 벽돌과 함께 쌓은 석재는 대구 읍성을 철거한 성돌이다. 외관은 정면 중앙에 돌출된 종탑을 중심으로 좌우 대칭을 이루고 있으며 지붕은 박공지붕에 동기와를 이었다.","a":"계성학교아담스관","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636927.jpg"},{"q":"○○○○는 항재 이익구(恒齋 李翊九:1838~1912)가 고종 27년(庚寅:1890년)에 두명의 동 생 능구(能九), 명구(命九)와 함께 단장면 무릉에서 퇴로로 입거(入居)하여 8년째 되던 광무2년(戊戌:1898 년)에 주위의 경관도 즐기면서 교육과 독서, 저술에 전념하기 위해 지은 별업(別業)이다. ○○○○는 4칸의 홋처마 팔작지붕 와가(瓦家) 정당(正堂)인 ○○○○와 팔작지붕 와가 3칸의 별채인 한서암(寒棲菴), 그리고 관리사와 문사(門舍)로 구성되어 있는데, 퇴로마을의 서쪽 산기슭(본가에서 200보 떨어진곳)에 위치하고 있어서 별업의 이름을 ○○○○라 하였다.","a":"밀양 서고정사","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666600.jpg"},{"q":"서울 관악산 북쪽 중턱의 거대한 절벽 바위면에 돋을새김으로 조각한 불상으로, 미래세계에 나타나 중생을 구제한다는 ○○○을 형상화한 것이다. 민머리에 상투 모양의 둥근 머리묶음이 낮게 표현되었으며 얼굴은 갸름한 편이다. 늘씬하게 표현된 신체와 둥글게 깎인 어깨 등으로 보아 상당히 우수한 조각가의 작품으로 보인다. 이 불상은 1630년이라는 절대연대를 가지고 있어서 조선시대 조각사 편년 연구에 귀중한 자료가 되며, ‘미륵존불(彌勒尊佛)’이라는 글을 통해 17세기 조선사회에도 미륵신앙이 유행하고 있었음을 알려준다.","a":"봉천동 마애미륵불좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636186.jpg"},{"q":"살림집 부분과 재실, 가묘의 2부분이 서로 담장으로 구분되고 있다. 살림집은 안채와 사랑채, 방앗간채, 광채 그리고 대문채로 구성되어 있다. 가로, 세로의 비가 거의 같은 정방형의 대지에 안채와 사랑채를 남북으로 병렬 배치하고 두 건물사이에 방앗간채와 곡간을 배치하여 전체 배치형식은 남부지방 상류주거의 전형인 튼 □자형을 이루고 있으며, 대문채는 대지의 우측으로 바짝 붙여 배치함으로써 시각적인 효과와 함께 사랑마당과 행랑마당을 겸하는 마당을 확보하였다.","a":"진주 이세후 종가","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666244.jpg"},{"q":"중앙의 아미타불좌상을 중심으로 좌우에 관음보살과 지장보살이 협시하고 있는 아미타삼존상이다. 아미타불상은 목불(木佛)이고, 관음보살상은 옥석(玉石)으로 만들었으며 대세지보살상은 소조불(塑造佛)이다. 중앙의 아미타불좌상은 고성 건봉사에서 모셔온 불상으로 전해지고 있는데 방형(方形)의 얼굴에 육계(肉髻)가 펑퍼짐하며, 통견(通肩)의 법의(法衣)가 배 앞에서 ‘W’자형을 그리고 있는 19세기 양식 불상이다. 머리에 무늬 없고 단순한 보관(寶冠)을 쓰고 있는 관음보살상은 의자에 앉아 왼다리를 내리고 오른다리는 올린 특이한 자세를 취하고 있다.","a":"안양암 대웅전 삼존불상(아미타불,관음보살,지장보살)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590618.png"},{"q":"월계 마을 북서쪽에 있는 초포산에서 남쪽으로 흘러내린 산줄기의 해발 20m 내외의 구릉 능선상에 있는 2기의 고분이다. 1호분의 평면은 네모난 모양과 둥근 형태를 모두 가지고 있는 장고분이고 2호분은 평면형태가 둥근 원형이다. 1호분은 북서쪽에서 남동쪽으로 완만하게 내려오는 구릉의 능선상에 있는데 구릉 위쪽에 네모난 부분을 두고 있다. 둥근 부분의 남동쪽은 민묘 등으로 인하여 약간 변형되었고 네모난 부분의 북서쪽은 길이 생기면서 훼손되었다. 2호분은 둥근 형태를 하고 있는 원분으로 1호분의 남동쪽 아래에 자리하고 있다.","a":"영광월산리월계고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654346.jpg"},{"q":"김해 김씨 17대 손이 살고 있는 가옥으로 현 소유자의 14대 조부가 세워 지금에 이르고 있으며, 본래 초가였던 것을 60년전 기와로 바꿨다고 한다. 안채와 사랑채로 구분되어 있는데 안채는 양양지방에 남아있는 북방계통의 집이다. 왼쪽으로 넓은 부엌을 배치하고 오른쪽으로 가운데를 갈라 나눈 뒤, 다시 구획하여 6개의 작은 방을 만들었다. 부엌 앞으로 내밀어 지은 외양간은 창고로 개조하였다. 사랑채는 나중에 늘려지은 것으로 보이는데 안채와 달리 큰 방 셋을 마련하고 밖으로 툇마루를 두어 방과 방이 서로 연결되도록 하였다.","a":"양양김성래가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660479.jpg"},{"q":"면동마을 길가에 자리하고 있는 높이 122㎝의 석상이다. 전체적인 형태는 큼지막한 둥근받침 위로 4각의 석상이 놓여 있는 모습이다. 둥근받침은 네 조각의 돌이 이어 있으며 가운데가 4각으로 파여 그 곳에 석상을 고정시켜 놓았다. 자연석을 그대로 사용한 석상은 앞면과 양 옆면을 약간 다듬었을 뿐 뒷면은 자연석 그대로이다. 받침은 윗면에 8판의 연꽃무늬를 새겨 넣었고, 석상에는 앞과 옆면에 13개의 다양한 상들을 조각하였다.","a":"강진사문안석조상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662190.jpg"},{"q":"효(孝) 사상과 결합하여 크게 성행한 감로탱화는 조상의 극락왕생을 위해 그린 불교그림으로, 부처를 극진히 대접하여 조상의 영혼이 지옥세계로부터 구제되기를 간절하게 기원하는 마음을 표현한 것이다. 이 그림은 크게 세부분으로 표현되었다. 그림의 맨 윗부분에는 불·보살의 모습이 표현되었고, 중간에는 부처님께 올리는 여러가지 음식을 차려 놓은 성반(盛飯)이 마련되어 있으며, 그 아래에는 먹지 못해 고통받는 아귀왕과 함께 지옥장면, 싸우는 모습, 형틀에 묶여있는 모습, 광대패놀이, 호랑이에게 쫓기는 모습 등등 인간이 그 업보에 따라 겪게 되는 갖가지 장면들이 묘사되어 있다.","a":"고성 운흥사 감로도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642317.jpg"},{"q":"조선 전기의 문신 ○○○의 묘역이다. ○○○은 본관이 진주(晉州)다. 1453년 계유정난 때 수양대군을 도왔으며, 1455년 단종의 선위(禪位; 왕위를 넘김)로 세조가 등극할 때 협력한 공으로 좌익공신(佐翼功臣) 2등에 책정되고 진산부원군(晉山府院君)에 봉해졌다. ○○○ 묘역은 위쪽에 ○○○ 묘, 아래쪽에는 그 아들 강윤범(姜允範)의 묘가 있다. ○○○ 묘는 부인 영천군부인(榮川郡夫人) 파평윤씨(坡平尹氏)와 쌍분(雙墳)으로 조성되어 있으며, 각 봉분 앞에는 석상과 현대에 건립한 묘표가 있다. 그 앞에 4각형의 장명등과 문인석 한쌍이 설치되어 있다.","a":"양평신복리강맹경묘역","c":"시도기념물","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646806.jpg"},{"q":"○○은 표은 김시온(1598∼1669)을 추모하기 위해 적암 김태중이 앞장서서 숙종 5년(1679)에 지은 정자이다. 1949년 화재로 일부 불타버린 것을 고쳐 지었고, 1988년 임하댐 건설로 지금 있는 자리에 다시 옮겨 지었다. 표은 김시온은 병자호란(1636) 때 의병을 일으켜 활약하였고, 병자호란 뒤에는 벼슬길을 포기하고 와룡산에 와룡초당을 지어 40여 년동안 절의를 지키며 제자를 가르치는데 전념하였다. 건물은 一자형으로 앞면 4칸·옆면 2칸의 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"송정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662420.jpg"},{"q":"조선 중종 34년(1539)에 ○○○ 송흠(1459∼1547)이 지은 정자로, ○○○은 맑은 물을 보고 나쁜 마음을 씻는다는 뜻이다. 송흠은 효성이 지극하여 101세 된 노모를 봉양하기 위해 지방에서 외직을 맡아 효행으로 상을 받고, 효헌이란 시호를 받았다. 중종 33년(1538)에는 청백한 관리로 뽑히기도 했다. 건물은 앞면 3칸·옆면 1칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 오른쪽 2칸은 마루를 깔고 왼쪽 1칸은 방을 두었는데, 3면을 들어 올릴 수 있는 열개문으로 하여 개방적인 면이 보인다.","a":"장성 관수정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022101118515200.jpg"},{"q":"○○○○은 1897년 순교자 신석복 마르코(1828~1866년)의 출생지 바로 옆에 서 있는 성당으로 경남지역에서 가장 일찍 설립된 천주교회 본당이다. 신석복은 1828년에 명례리 1209년에 출생한 소금장수였는데 1866년 병인박해 때 김해 가산에서 붙잡혀 대구감영에서 순교했다. 순교할 때 “나를 놓아준다 해도 다시 천주교를 봉행할 것이다.”라는 말을 남겼다. 그의 유해는 지금 강 건너 진영 천주교 묘지에 봉안되어 있다. 명례 본당의 초대 주임이었던 강성삼 신부(1866~1903년)는 김대건 신부와 최양업 신부에 이어 한국의 세 번째 신부이다.","a":"밀양 명례성당","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2015120819191600.JPG"},{"q":"이 건물은 ㄷ자형의 안채와 一자형의 사랑채가 모여서 전체적으로 ㅁ자형의 평면형태를 이루는 전형적< 典型的 >인 영남지방< 嶺南地方 >의 주택< 住宅 >이다. 원래는 영양남씨< 英陽南氏 > 종택< 宗宅 >으로 진사< 進士 > 남구수< 南龜壽 > 선생이 건립< 建立 >하였으나 현< 現 > 소유주< 所有主 > 10대조< 十代祖 >인 황파< 黃坡 > 김종걸< 金宗傑 >의 조부< 祖父 >가 장인< 丈人 >으로부터 건물을 이어받아 거촌리< 巨村里 > 거주< 居住 > 의성김씨< 義城金氏 >의 종택으로 내려오고 있다.","a":"경암헌고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658677.jpg"},{"q":"○○○○○의 ○○은 인조 때 한성부 좌우윤을 지냈으며 백성을 위해 교화를 베풀고 청렴했던 ○○○이라는 인물의 ○○으로 서울과의 관련성이 크고, ○○과 ○○ 내 석물들은 조선 후기 묘제 및 석물 제작 양상을 알 수 있게 한다는 점에서 보존가치가 크다. 특히 신도비(神道碑)는 조경(趙絅)의 문장과 이정영(李正英)·조위명(趙威明) 등 당대 명문장가와 명필들의 글씨를 확인할 수 있게 하는 자료로 정사(正史)인 실록 등을 보완하는 사료적 가치를 가진다.","a":"충정공 목서흠 묘역","c":"시도기념물","nc":"","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644867.jpg"},{"q":"조선시대의 문신인 포저 조익(趙翼,1579∼1655)과 그의 셋째 아들 송곡 조복양(趙復陽,1609∼1661)의 시문집을 새긴 목판으로, 모두 633매이다. 조익은 조선시대 문신으로 음서로 정포만호가 되고 선조 35년(1602) 별시과에 내과로 급제한 이래 여러 벼슬을 거친 후 대사헌, 좌의정까지 올랐다. 그러나 이이, 성혼의 문묘종사가 받아 들여지지 않자 사직했다. 성리학의 대가로 예학에 밝았다. 조복양은 김상헌의 문인으로, 인조 11년(1633) 사마시에 합격하고 여러 직을 거쳐 부교리로 붕당의 폐를 한탄하여 사직하려 했으나 이루지 못했다.","a":"포저유서및송곡문집판각","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639213.jpg"},{"q":"대한제국 말 애국자인 장태수(1841∼1910) 선생의 영정을 모시고 추모하는 사당이다. 건물은 1935년 안동 장씨들이 일제침략에 반대하며 자결한 선생의 항일정신과 자주정신을 기리기 위해 세웠다. 장태수 선생은 조선 후기의 문신이자 순국지사이다. 철종 12년(1861) 문과에 급제하여 예조정랑, 사헌부지평 등 여러 벼슬을 지냈고 고종 32년(1895) 단발령이 내려지자 벼슬을 버리고 스스로 남강거사라 하였다. 1910년 일본이 합병하자 불충과 불효의 죄를 씻는다고 단식하여 24일만에 순국하였다.","a":"서강사","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661817.jpg"},{"q":"경상남도 ○○시의 ○○○ 암벽에 있는 마애불이다. ○○○는 가락국의 거등왕이 칠점산의 선인(仙人)을 초대하여 거문고와 바둑을 즐겼다는 전설이 있는 곳이다. 이러한 전설로 인해 이 마애불은 거등왕의 초상이라고 전해지기도 한다. 민머리에 가늘고 긴 눈, 넓적한 코, 두툼하고 넓은 입술 등이 고려시대 마애불의 지방 양식을 보여준다. 신체를 단순한 선으로 묘사해 양감이 없고 평면적이며, 광배(光背) 역시 선으로 구분해 아무런 무늬없이 소박하다. 전체적인 분위기가 고려시대에 많이 만들어진 거대한 마애불 양식을 잘 보여주는 작품이다.","a":"김해 초선대 마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641510.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 대전 유성구 교촌동의 마을 뒷산에 있는 남방식 고인돌로 모두 7기가 밀집되어 있다. 이 고인돌은 작은 것은 길이 1m, 큰 것은 약 7m로 다양하며, 일부는 받침돌이 지상에 노출되어 있다.","a":"칠성당지석묘군","c":"문화유산자료","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659738.jpg"},{"q":"삼장사의 옛터에 남아 있는 탑으로, 무너져 흩어져 있던 것을 일부 수습하여 세워 놓았다. 삼장사는 절이름의 유래나 역사에 대해서는 알 수 없으나, 밭으로 변한 주변에 건물의 기단을 비롯한 여러 석조물이 남아있어 절터였음을 말해주고 있다. 탑은 전체의 무게를 받쳐주는 2층 기단(基壇) 위로, 3층의 탑신(塔身)을 세운 모습으로, 원래는 5층 석탑이었을 것으로 추측된다. 기단은 아래위층 모두 각면의 모서리와 가운데마다 기둥모양을 본떠 새겼다. 탑신의 몸돌은 모서리에만 기둥조각을 해두었을 뿐 다른 꾸밈은 보이지 않는다.","a":"산청 삼장사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641394.jpg"},{"q":"○○○는 지리산 3대 사찰 중 하나로서 통일신라 흥덕왕 3년(828) 덕운선사가 세워 처음에는 절 이름을 감로사라 하였다. 그 뒤 통일신라 헌강왕 원년(875) 보조선사가 고쳐 지었고 정유재란 때 소실되어 다시 고쳐 세우고 수리하였으나 영조 49년(1773)에 화재로 절의 모든 건물이 불타 버렸다. 그 이듬해부터 혜암스님이 복원하면서 오늘의 ○○○로 이름을 고쳐 불렀다고 한다. 현존하는 건물은 극락보전, 팔상전, 응진전 등 20여 동의 건물이 있다.","a":"천은사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661959.jpg"},{"q":"취죽당 김응명의 8대손 김몽노(1828∼1884)의 생가이다. 대지를 2단으로 조성하여 사랑채 부분과 안채를 나누고 있다. 안채는 사랑에 덧대어 설치한 중문을 통하여 출입하게 하였고 뒤편에는 사당을 지었다. 사랑채의 구성은 좌우에 중간문과 고방을 두었고 왼쪽 온돌방에는 옛 방식인 중간설주가 서 있다. 오른쪽 온돌방에는 4짝 여닫이문을 달아 격식을 갖추었다. 사랑채 구성의 특이성으로 인하여 한옥 건축의 귀중한 자료로 평가되는 건물이다.","a":"운곡정사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658786.jpg"},{"q":"중앙에서 파견된 관리나 외국사신이 묵던 숙소로 세워진 시기는 알 수 없다. 원래는 지금의 선산초등학교 부근에 있던 ○○○○ 건물들 중의 하나였으며『동국여지승람』에 의하면 그곳에는 남관, 북관, 청회루, 양소루가 있었다고 한다. 1914년에서 1984년까지 선산읍사무소로 쓰이다가 1986년 경상북도 유형문화유산으로 지정되어 오늘에 이른다. 앞면 5칸·옆면 4칸의 1층 건물로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있다. 앞면의 가운데 칸에는 현관을 만들었으며 기둥 사이마다 꽃받침을 두어 앞면에는 귀신얼굴을, 좌우 옆면에는 개와 코끼리를 조각했다.","a":"선산객사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640740.jpg"},{"q":"조선 16대 임금인 인조의 다섯째 아들 숭선군의 묘소이다. 군의 이름은 징(徵)이며, 시호는 효경(孝敬)이다. 인조 2년(1624) 이괄(李适)의 난으로 인조를 따라 공주(公州)로 잠시 피신한 일이 있었는데, 궁으로 돌아와서도 항상 공주를 그리워하더니 숙종 16년(1690) 세상을 떠날 때 공주에 묻어 줄 것을 유언하였다고 한다. 그러나 당시 왕족의 무덤은 도성(都城)에서 90리 밖으로 나갈 수 없다는 법 때문에 중단되었고 그 후 후손에 의해 다시 이곳으로 옮겨져 만들어졌다.","a":"숭선군묘","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2024110414152401.jpg"},{"q":"｢佛說長壽滅罪護諸童子經｣은 唐의 沙門 佛陀波利가 번역한 것으로 불보살의 加被와 수행을 통하여 모든 죄악을 없애고 장수하는 법에 대한 가르침을 기록한 경전이다. 말미의 간기에 의하면 고려 고종연간에 정권을 專橫하였던 진양공 최이의 福壽無疆을 발원할 목적으로 간행된 경전임을 확인할 수 있다. 간행시기에 대해서도 末尾에 󰡒時辛丑正月󰡓이라고 밝혀 판각 시기가 1241년 正月임을 알 수 있다. 경전의 제목과 서두 부분이 일부 훼손되기는 하였지만 전반적으로 보존상태가 양호하다. 표지는 두꺼운 장지를 사용했고 표제는 후대에 삽입한 것으로 보인다.","a":"불설장수멸죄호제동자경","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638944.jpg"},{"q":"이 ○○○○은 복장기에 의해 1612년 玄眞, 學文, 明隱, 義能 등의 금어에 의하여 조성되고, 1677년에 중수되었음을 알 수 있다. 이 관음상은 총고 39.5cm 크기의 단아한 목조각상으로 조각기법이 뛰어난 작품이다.","a":"함양상연대목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643059.jpg"},{"q":"조선 성종 때의 문신이자 문장가인 삼탄 이승소의 문집으로, 목판본 6책 15권이다. 이승소는 세종 29년(1447) 문과에 급제하여 성종 12년(1481) 정헌대부를 역임하였으며, 이조·형조판서를 거쳐 좌참찬에 올랐다. 당대 문장가로 예악·음악·의약·지리 등 여러 방면에 조예가 깊었으며, 성종 5년(1474) 신숙주, 강호맹 등과 함께 『국조오례의』를 편찬하기도 하였다. 시호는 ‘문간’이다. 『○○○』은 이승소의 외손자인 이수동에 의해 청주판이 간행되었으며, 중종 8년(1513) 함흥판이 간행되었고, 중종 30년(1535) 청주판의 중간본이 간행되었다.","a":"삼탄집","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638605.jpg"},{"q":"이 木造阿彌陀佛坐像은 ○○○○○ 무량수전 내 중앙 수미단의 향좌측에 봉안되어 있다. 사측에 의하면 이 불상은 ○○○을 건립할 때 통도사에 있던 것을 이운해 왔다고 한다. 불상의 전체 높이가 58.3㎝인 규모가 작은 불상이며, 통견에 아미타구품인을 결한 채 결가부좌하고 있는 모습이다. 머리부터 저부까지의 하나로 된 몸체 1板, 결가부좌한 다리부분 1板, 그리고 底部 木板 등 목재 3판으로 조성되어 있는 이 불상은 背面과 저부에 腹藏孔이 가구되어 있는데 저부 복장공 덮개의 결실과 함께 복장 내부가 텅 비어 있다.","a":"통영 약수암 목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643075.jpg"},{"q":"이 가옥은 한국의 전통적인 양반집으로 안채와 2동의 사랑채, 곡간채, 사당, 내외의 문간채등으로 구성되어 나름대로 격식을 잘 갖춘 주택임. 남서측에서 솟을3문을 통과하여 출입하면 안사랑채와 바깥사랑채가 나란히 위치하고 그 뒤로 안채와 곡간채가 직교하여 위치하고 있으며, 안사랑채 사당이 경역을 달리하여 동편에 자리하고 있다.","a":"창평춘강고정주고택","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658424.jpg"},{"q":"임피향교의 입구에 위치하고 있는 건물로 임피유생들이 역대 수령들의 위패를 모시고 1년에 한 차례 제사를 지내는 곳이다. 유생들은 이곳에 모여 여가를 보내며 시와 노래를 즐기기도 한다. 지어진 연대는 중앙마루에 쓰여진 기록으로 보아 철종 6년(1855)임을 알 수 있다. 건물은 앞면 6칸·옆면 3칸으로 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 건물의 디딤돌로 사용되는 돌 중에 탑의 일부분으로 쓰이던 부재 2개가 발견되고 있으며, 향교의 부속건물 중에서도 주춧돌로 옥개석 1개가 사용되었다. 또한 진평호씨의 집에서도 옥개석의 일부를 주춧돌로 사용하고 있다.","a":"노성당","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639591.jpg"},{"q":"조선 숙종(재위 1674∼1720) 때의 문장가인 ○○○이 살던 옛집이다. 서재로 사용하였다는 염선재와 함월정이라는 정자가 남아있다. 1720년경 집 앞에 정자를 지었는데, 제자인 권상하가 그의 호를 따서 정자이름을 ‘함월정’이라 하였다고 전한다. 1983년 ○○댐 건설로 인하여 지금의 위치로 옮겨 지었다. 고종 11년(1874)에 후손들이 무릉사를 지어 권상하와 ○○○을 제사하고 있다.","a":"충주 최응성 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638520.jpg"},{"q":"이용강 대감의 장례 때 시신을 묘소까지 운반하기 위해 제작된 기구이다. 이용강은 조선 고종 때 경상감사와 공조판서를 지낸 분으로, ○○ 황간으로 낙향하여 노년을 지내었다 한다. ○○는 세도있는 양반가의 것으로서, 민간층에서 사용하는 ○○와는 다르게 특별히 제작된 것으로 보인다. 긴 멜대를 중심으로 한 기본틀 위에 관을 싣는 몸체를 올리고 맨 위에는 햇빛을 가리기 위한 천을 넓게 드리웠다. 몸체의 아래 위에는 난간을 두르고 검은 천을 덮은 뒤 색띠와 술을 늘어뜨렸다.","a":"영동 신항리 상여","c":"시도민속문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658216.jpg"},{"q":"요지란 자기와 기와, 그릇들을 만들어 굽던 가마터를 말한다. 이 가마터는 운수면 ○○○에서 약 300m 떨어진 산기슭에 있으며, 14세기말∼15세기초에 만들어진 것으로 추정된다. 이곳 사람들은 옛 부터 이곳을 도장골·가마골·사기골으로 부르고 있다. 버려진 ○○○○조각의 종류로는 대접, 항아리, 접시, 장군이 있으며, 문양은 귀얄문, 인화문, 상감대선문이 주류를 이룬다. 적은 양의 조선 백자와 조선 청자조각이 흩어져 있다.","a":"고령대평리분청사기요지","c":"문화유산자료","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663042.jpg"},{"q":"이 작품은 ○○○오존도로, 중앙에 ○○○불을 중심으로 앞쪽 좌우에 지장과 관음, 뒤쪽 좌우에 아난과 가섭이 대칭구도를 이루면서 시립해 있다. 존상들은 신체에 비해 머리가 작은 편이며 신체비례도 좋은 편이다. 색채는 붉은색을 위주로 하여 어두운 녹청과 군청 안료들이 사용되었으며, 사물의 윤곽과 운문 등은 황색으로 그려 장식적인 효과를 더하였다. 본존불은 2단의 나무 좌대 위 청련좌에 결가부좌하였으며, 엄지와 중지를 맞댄 양손은 오른손은 가슴 앞으로 들고 왼손은 무릎 위에 두었다.","a":"남해용문사아미타여래오존탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666071.jpg"},{"q":"불교에서 번(幡)은 불, 보살의 위상을 드높이는 역할을 하며, 법회의 성격에 따라 다르게 사용된다. 인로왕보살(引路王菩薩)은 망자의 영혼을 극락세계로 인도하는 보살이다. ○○○의 ‘나무대성인로왕보살번’은 번두(幡頭)와 번신(幡身), 번수(幡手), 번미(幡尾)로 구성되어있다. 인로왕번은 적, 녹, 황, 백, 흑의 오방색을 기본 구성으로 하며 번의 가장 상단인 번두는 일반적으로 어두운 색이 사용된다. ○○○ 인로왕번의 가장 상단인 흑색의 번두에는 네 마리의 용이 원을 그리며 구름, 파도, 바위와 함께 배치되었다.","a":"화성 용주사 남무대성인로왕보살번","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637807.jpg"},{"q":"천봉산 기슭에 있는 ○○○는 백제 무령왕 3년(503)에 아도화상이 처음 지었다고 전한다. 통일신라시대에는 큰 사찰의 면모를 갖추었고, 고려 원종 원년(1259)에 다시 지었다. 그 후 조선시대에도 여러 차례 다시 짓거나 수리가 있었다. 지금 남아있는 ○○○은 영조 33년(1757)의 대화재로 불타 없어진 것을 4년에 걸쳐서 다시 지은 것이다. 한국전쟁 때 ○○○의 대부분 전각이 불탔으나 ○○○은 보존되었으며, 1982년에 해체하여 복원하였다. 아미타불을 모신 ○○○은 앞면 3칸·옆면 3칸의 규모이며, 사람인(人)자 모양의 단순한 맞배지붕집이다.","a":"대원사극락전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639927.jpg"},{"q":"○○시(구 진양군)와 사천시(구 사천군)의 경계를 표시하여 이정표 역할을 하던 비로, 직사각형의 자연돌을 약간 다듬어 놓은 모습이다. 전하는 이야기에 따르면, 천태산 마구 할머니가 물레를 하려고 바위 3개를 가져오는데, 1개는 머리에 이고, 1개는 지팡이로 짚고, 1개는 치마에 담아 가져오다가 2개는 숲에 버리고, 치마에 담고 오던 바위만 지금의 자리에 세워두었다 한다.","a":"진주 두문리 이정표석","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664268.jpg"},{"q":"백제의 충신이었던 성충·흥수·계백을 기리기 위해 지은 사당이다. 성충은 백제 의자왕(재위 641∼660) 때 충신으로, 좌평으로 있으면서 잘못된 정치를 바로잡기 위해 애쓰다 옥중에서 단식을 하다 죽었다. 흥수는 백제 의자왕 20년(660) 나당연합군이 공격해 오자 탄현을 지키다 대신들의 반대로 지키지 못하고 결국은 멸망하였다. 계백은 나당연합군이 공격해 오자 결사대 5,000여명을 뽑아 지금의 연산인 황산에서 싸우다 전사하였다. 1957년 지은 이 사당은 1981년 다시 지어 현재의 모습을 하고 있으며, 해마다 10월 백제문화제 때 삼충제를 지내고 있다.","a":"삼충사","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661081.jpg"},{"q":"○○○은 조선시대 승려인 지탁(知濯)이 찬집한 1권 1책의 불교의식집으로 여러 경전에 산재하여 있는 불·보살상(佛菩薩像)의 조성에 따른 제반 의식과 절차에 관한 내용을 모아 체계화한 책이다. <○○○>은 사찰에서 불·보살상을 조성할 때의 의식 절차를 설명하고 그 의식의 종류마다 의의를 부연하였는데, 이를 행할 때 외우는 주문은 범어·한문·한글을 병기하여 누구나 쉽게 접할 수 있도록 한 점이 특징이다.","a":"복천사조상경","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636729.jpg"},{"q":"이 책판은 고려 충선왕과 공민왕 양대에 걸쳐 고관을 지낸 익재 이제현(1287∼1367)의 문집을 새긴 목판이다. 이 책판은 사간본으로 숙종 19년(1693)에 간행되었으며, 147매이다. 이제현 선생은 원나라의 만권당에서 조맹부 등과 교류하며 고려에 신학문과 사상을 소개하고, 성리학을 전파, 발전시키는데 중요한 역할을 하였다. 저서로 『국사』,『역옹패설』 등을 남겼다. 『익재집』은 여러 차례에 걸쳐 간행되었다. 초간본은 공민왕 12년(1363), 재간본은 세종 14년(1432), 세번째로 선조 33년(1600)에 간행되었다.","a":"익재집책판","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640757.jpg"},{"q":"이 전적은 다라니 3점과 불경류 3책이다. (1) 다라니는 태장계만다라(胎藏界曼茶羅), 일체여래심비밀전신사리보협인다라니(一切如來心秘密全身舍利寶篋印多羅尼), 전신사리보협인다라니(全身舍利寶篋印多羅尼)이다. ① 태장계만다라(37×40cm) 이 자료의 인출시기는 지질과 먹색으로 고려시대의 것으로 추정되며, 밀교에서 금강계만다라와 함께 양부만다라를 이루고 있다. 가운데의 글자는 밀교에서 비로자나불을 상징하는 ‘아(阿)’자이며, 여러 층으로 된 밀교의 다라니 진언이 판각되어 있다.","a":"구미금강사소장전적","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641121.jpg"},{"q":"○○산성은 ○○시 안림동 산56-1과 직동산 24-1 및 목벌동 산54에 걸쳐 있으며 ○○○ 또는 금봉산성으로 불리워지기도 한다. 삼국시대에 축성된 것으로 보여지는 이 성은 외축 내착형이며 산 정상을 이어 쌓아진 테뫼식 산성이라고 할 수 있다. 축성 재료는 석재를 고루 쌓아 전형적인 고식을 보이며 성 둘레는 1983년 ○○시 조사에 의하면 1,145m이며 중간 중간이 무너지고 5개소에 775m의 성곽이 남아 있으며 성안의 넓이는 46,524㎡이고 성벽의 높이는 7∼8m에 이르고 있다.","a":"충주 남산성","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649562.jpg"},{"q":"용화사는 신라시대 때 세운 절로 알려진 유서깊은 절이다. ○○○은 고려 태조 26년(943) 도솔선사가 지은 것으로, 이에 관한 설화가 전한다. 도솔선사가 미륵산의 암굴에서 수도할 때 호랑이와 가깝게 지냈는데 어느날 호랑이가 처녀를 업어와 바쳤다고 한다. 선사는 호랑이를 꾸짖고 처녀를 고향으로 데려갔는데 처녀의 아버지가 은혜를 갚기 위해 300냥을 선사에게 주었고, 그 돈으로 ○○○을 지었다고 한다. 지금도 ○○○ 위쪽에 이 바위굴이 남아 있다. 현존하는 ○○○은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"통영 도솔암","c":"문화유산자료","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663954.jpg"},{"q":"○○○는 지었을 당시의 정확한 기록은 알 수 없고, 고려 선종 6년(1088)에 의천이 다시 지었다고 한다. ○○○의 본래 이름은 장육전으로 통일신라 경문왕 원년(861)에 다시 지었으나 임진왜란 때 소실되어 현종 1년(1660)에 복원하였고, 다시 영조 36년(1760)에 고쳐 세워 오늘에 이르고 있다. 경내 가장 구석진 곳에 있는 ○○○은 앞면 1칸·옆면 1칸 규모의 작은 전각이다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"선암사각황전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662169.jpg"},{"q":"○○○은 정면 5칸 측면 2칸 규모의 팔작기와집으로 정자들 동쪽의 병풍처럼 생긴 큰 바위 위에 자리잡고 있는데, 이 건물은 예천 지역의 대표적 독립운동가인 권원하(權元河)와 관련이 있는 건물로 알려져 있다. 정자의 우측에 있는 별묘(別廟)는 3칸 규모의 맞배기와집으로, 원래는 인산서원(仁山書院)의 사당이었으나 서원이 훼철(毁撤)되자 사당만 이곳으로 이건하여 권맹손(權孟孫), 권오기(權五紀), 권오복(權五福), 권용(權墉)을 봉사하는 별묘로 사용하고 있다.","a":"예천권씨병암정및별묘","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663493.jpg"},{"q":"○○○는 월악산 기슭에 있는 절로 신라 진평왕 4년(582) 아도가 지었다고 하나 연대가 확실하지 않다. 그 뒤 신라 문무왕(재위 661∼681) 때 원효가 고쳤다고 하며, 조선 선조(재위 1567∼1608) 때 사명대사가 다시 지어 오늘에 이르고 있다. ○○○○○은 아미타불을 모시는 건물이다. 앞면 3칸·옆면 3칸이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물이다.","a":"제천 신륵사 극락전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638597.jpg"},{"q":"왼손에는 약그릇을 들고, 오른손은 손가락 끝이 땅을 향하게 하고 있는 전형적인 석조약사불상으로 현재는 도금 처리하였다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 뚜렷하다. 엷은 미소를 띠고 있는 타원형의 얼굴은 이목구비가 선명하여 박력있는 모습이다. 옷은 왼쪽 어깨와 팔을 감싸 흐르고 있는데, 옷주름이 형식적으로 처리되어 양감이 충분히 나타나지 않는다. 손·무릎 등의 표현도 투박하여 양감이 떨어지는 모습이다.","a":"함안 장춘사 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641340.jpg"},{"q":"○○○ 선생은 본관이 안동(安東)이며, 호는 청음(淸陰)·석실산인(石室山人) 등이다. 병자호란이 일어나자 예조판서로 주화론(主和論)을 배척하고 끝까지 주전론(主戰論)을 폈다. 1645년 특별히 좌의정에 제수되고, 기로소(耆老所)에 들어갔다. ○○○○○ 묘는 선영(先塋) 중 조부 김생해(金生海) 묘 아래 단독으로 조성되어 있다. 봉분 앞에는 묘표, 혼유석, 석상, 향로석이 설치되어 있으며 그 아래로 묘명비(墓銘碑)와 문인석 1쌍이 건립되어 있다. 묘표는 운수방부(雲首方趺; 구름이 조각된 비신 머리와 네모난 비좌) 형태로 운수는 앞뒤 면에 일출(日出)을 형상화했다.","a":"김상헌선생묘","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646377.jpg"},{"q":"완주 ○○○는 867년에 보조국사(普照國師) 체징(體澄)이 창건하였다고 전해지며, 그 뒤 고려 중기에 보조국사 지눌이 다시 고쳐 지었다. ○○○의 ○○○에는 ○○○○상을 주존불(主尊佛)로 모시고, 왼쪽에 보제존자, 그 좌우로 시왕상, 인왕상, 사자상 등이 배치되어 있다. 흙으로 만든 ○○○○은 나무로 만든 연꽃무늬 대좌(臺座) 위에 놓여 있다. 원만한 인상에 눈·코·입 등이 가지런하며, 양 귀는 긴 편이 아니나 큼직하여 근엄하면서도 자비롭다. 옷은 양 어깨를 감싸고 있는데 양 팔에 걸쳐 옆으로 흘러내리고 있다.","a":"송광사명부전소조지장보살삼존상및권속상일괄","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2016090818002700.jpg"},{"q":"○○○○○은 주색 바탕의 화면에 황색선으로 도상을 묘사한 선묘불화이다. 1781년 제작된 이 탱화는 금어 함식(咸湜)이 그렸다. 화면 상단 중앙에는 아미타여래좌상이 높은 연화좌대에 결가좌하고 그 아래쪽 좌우에는 팔대보살상이 시립하고 있으며, 그 위쪽에는 십대제자상이 좌우측에 각각 5구씩 배치되어 있다. 화면 상단 천공에는 합장형의 분신불이 작게 묘사되어 있다. 견본채색의 재질인 이 탱화는 세로가 긴 직사각형(155.5cm×113.7cm)으로 1폭(3부(副) 1포(鋪))이다. 당초 ○○○ 인법당에 봉안되어 있었으나 현재는 성보박물관에 소장되어 있다.","a":"하동 쌍계사 국사암 아미타후불탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642379.jpg"},{"q":"고종 31년(1894) 동학농민운동이 터졌을 때, 관군이 동학군과 싸워 나주성을 지킨 것을 기념하기 위해 세운 비이다. 거북을 새긴 받침돌 위에 비몸을 세우고 그 위에 지붕돌을 올린 모습이다. 받침돌은 땅 속에 파묻혀 그 윗부분만 보이고 있다. 비문의 내용은 크게 세부분으로 나뉘어 농민운동이 일어나 나주에까지 동학군이 쳐들어오게 된 과정과 당시 나주목의 수령이던 민종열 목사가 여러 장수들을 지휘하여 치밀한 방어계획을 세웠던 사실, 그리고 관군과 동학군이 나주목에서 싸우는 과정등을 자세하게 서술하였다.","a":"금성토평비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662167.jpg"},{"q":"○○○은 조선 선조 때의 문신 초간 권문해草澗 權文海, 1534∼1591가 벼슬에서 물러난 뒤 심신心身의 수양을 위해 세운 정자이다. 권문해는 퇴계 이황의 제자로서 문과에 급제하여 대구부자, 좌승지 등을 지냈고, 우리나라 최초의 백과사전인 『대동운부군옥大東韻府群玉』을 지은 인물이다. 선조 15년1582에 처음 세워진 ○○○은 1592년에 화재로 불탔다. 권문해의 아들 권별權鼈이 인조 4년1626다시 지었으나, 인조 14년1636에 다시 불탔다.","a":"예천 초간정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641309.jpg"},{"q":"식영정은 한호(閑好) 임연(1589∼1648)선생이 1630년에 무안에 입향 이후 강학소요처로 지은 정자로 영산강[이호(梨湖)]과 그 주변의 경관과 어울려 많은 시인 묵객들이 찾은 곳이다. 그리고 임연의 증손으로 『동사회강』을 지은 문인 학자인 노촌(老村) 임상덕(林象德, 1683∼1710)이 제현과 교류하는 등 무안 몽탄 이산리의 나주임씨 강학교류 공간이었다. 무안 이거와 경관, 정자건립 등에 관해서는 1643년경에 임연이 지은 『복거록(卜居錄)』에 잘 나타나 있고 교류한 문인도 많다.","a":"무안식영정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662267.jpg"},{"q":"이 ○○는 석질과 양식 면에서 뛰어난 것은 아니지만 14세기 또는 15세기 ○○로서 시대가 확실한 명문을 가지고 있으며, 고려의 문인이자 무신인 ○○의 주인공 ○○○○ 12세때 자서명이 음각된 ○○라는 점에서 역사적인 가치를 지닌다. 또한, 1762년에 이 ○○가 발견될 당시 함창현감이 제작케 한 ○○집은 목질이나 양식이 당대의 것으로 인정된다. 특히, 이 ○○를 두고 조선시대 당시의 文士 30여명이 記, 詩, 歌, 行 등으로 찬양하고 있어 그 정신문화적 가치는 매우 높다","a":"김선치의 벼루","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641155.jpg"},{"q":"신도비란 왕이나 고관 등의 평생업적을 비석에 기록하여 그의 묘 남동쪽에 세워두는 것으로, 이 비는 고려 후기의 문신이자 학자인 목은(牧隱) 이색 선생을 기리고 있다. 이색(1328∼1396)은 고려 후기 조선을 건국한 이성계를 따르지 않고 충절을 지켰던 삼은(三隱)의 한 사람으로, 공민왕 때에는 전제의 개혁, 국방계획, 교육의 진흥, 불교의 억제 등 여러 개혁정책에 관한 건의문을 올리기도 하였다.","a":"이색신도비","c":"문화유산자료","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661105.jpg"},{"q":"◦ 비신(碑身)이 없이 귀부(龜趺, 받침돌)와 이수(螭首, 머리돌)만이 주변 산기슭에서 발견된 어느 고승의 탑비이지만 비신이 없어 주인공을 알 수 없음. ◦ 다만 조각 수법, 양식, 크기, 그리고 옆에 있는 뛰어난 수법의 8각 원당형 승탑(부도) 파재(破材)로 보아 고려시대 어느 유명한 승려의 탑비와 부도로 추정됨. ◦ 이수의 중앙 정면 전액(篆額)에는 글씨가 없고, 다만 용과 구름 문양이 화려하고 섬세하며, 귀부에도 거북등 모양과 발 고리 턱수염 등이 생동감있게 조각되어 있음.","a":"보령수부리귀부및이수","c":"시도유형문화유산","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639050.jpg"},{"q":"풍산 홍씨 집성촌인 도래마을 깊숙한 곳에 자리잡고 있는 살림집이다. 원래 안채, 사랑채, 행랑채를 갖춘 집이었다고 하는데 지금은 안채만 남아 있다. 건물에서 발견된 기록(상량문)으로 미루어 1918년에 지은 것으로 추정한다. 안채는 6칸 크기의 一자형 집으로 부엌방과 부엌·안방·대청마루방으로 구성되어 있다. 대청마루에는 앞쪽으로 1칸 반 크기의 작은방을 두었고 뒤쪽에 함실아궁이를 만들어 놓았다. 비교적 건물의 규모가 크고 구성과 구조가 건실하여 당시 주택을 살피는데 좋은 자료가 되고 있다.","a":"나주홍기창가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658357.jpg"},{"q":"개암사 종각에 보관되어 있으며, 전체 높이 89.0㎝, 입 지름 61.5㎝이다. 종의 윗부분에는 종을 매다는 고리인 용뉴와 소리의 울림을 도와주는 용통이 있다. 어깨부위에는 사각형으로 띠를 둘렀으며, 그 안에 다시 원을 그리고 범자를 새겨 넣었다. 일부는 이 사각형의 구획안에 2행의 한자 명문을 양각하였다. 어깨 아래쪽으로는 4각형 모양의 유곽과 보살입상이 4개씩 교차로 배치되어 있다. 유곽 테두리 안쪽으로 9개의 꽃무늬를 한 유두가 있다. 보살입상은 구름위에 천의를 입고 두 손을 모아 꽃을 받들고 있다. 종 입구는 어깨부위와는 다르게 띠를 두르고 꽃무늬를 새겼다.","a":"개암사동종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639558.jpg"},{"q":"우리나라는 고려중기 이후로부터 금속활자 인쇄기술이 매우 발달되었던 사례를 보이고 있다. 이러한 역사적 사실을 바탕으로 ○○○는 조선시대에 들어와서 계미자와 경자자 다음에 세 번째로 세종 16(1434) 갑인년에 구리(銅)를 주성분으로 주조된 금속활자이다. 특히 세종대의 고도의 과학기술과 장인정신을 바탕으로 주조되었던 까닭에 한국활자사에 있어서 가장 아름답고 정교한 활자로 평가되고 있는 것이다. 그리하여 조선시대의 가장 대표적 활자로 6차례 이상 개주를 거듭하였던 관계로 맨 첫 번째로 주조된 ○○○를 ‘초주○○○’로 구분하여 이름하고 있다.","a":"선덕사소장갑인자복각묘법연화경 권1~2","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643312.jpg"},{"q":"○○○○○은 극락전 앞에 자리하고 있으며, 그 높이는 2.5m이다. 원래 대웅전 앞에 있었으나, 1973년 현재의 위치로 옮겨 세웠다. 석탑의 하층 기단은 여러 장의 판석을 이용하여 결구하고 사방에 안상을 조각하였다. 그 상부에는 4매의 판석으로 구성하여 상층기단을 올렸다. 기단의 면석에는 2개의 우주(隅柱)와 1개의 탱주(撑柱)가 새겨져 있다. 탑신석과 옥개석은 각각 하나의 석재로 구성되어 있다. 탑신석에는 양 우주가 정연하게 새겨져 있으며, 상층으로 갈수록 정연한 체감비를 느낄 수 있다.","a":"석남사삼층석탑","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637254.jpg"},{"q":"삼강문은 충신, 효자, 열녀를 기리기 위해 세운 정려(旌閭)이다. 이 삼강문은 임진왜란 때 금산전투에서 순국한 의병장 고경명(高敬命,1533~1592)과 그 가족 6명의 충효열을 기리기 위해 세웠다. 1844년에 건립한 이 건물은 일반적으로 사용하는 정려의 건축 양식으로 평면은 정면 4칸, 측면 1칸으로 맞배지붕이다.","a":"고씨삼강문","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645751.jpg"},{"q":"○○○이란 조선시대 전라도와 경상도에 설치한 수군의 진영으로, 이 ○○○○은 전라○○○의 군사 조직과 운영실태를 알 수 있는 자료이며, 어떤 작전을 수행하고 있었는지도 알 수가 있다. 수록된 내용은 적과 만났을 때 대처하는 여러 가지 방법을 묘사한 예진도와 직진도 등 15개 사항이다. 도첩의 안쪽에 정조 4년(1780)에 수군편제를 하였다는 기록이 있어 1780년 이후 작성을 한 것으로 짐작된다. 조선 후기 ○○○의 조직과 작전 등을 구체적으로 알려 준다는 점에서 커다란 자료적 가치를 지니는 작품이다.","a":"우수영전진도첩","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662142.jpg"},{"q":"사당과 안사당, 그리고 가옥 한채와 2층 건물로 구분된 구조이다. 사당은 조선 고종 2년(1865)에 세워 허씨 4대 선조의 위패를 모신 곳이다. 가옥은 1912년에 지은 집으로 손님 접대나 서재로 사용하고 있다. 2층 건물은 1912년에 지어 현재 집무실로 사용 중인데 가옥과 구름다리로 연결되어 있다. 안사당은 고종 22년(1885)에 지은 것으로 솟을대문 형식이며 대문 양쪽에 방이 있다. 예전에는 손님을 접대하였으나 지금은 사용하지 않는다.","a":"고성장산리허씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664078.jpg"},{"q":"좌측에는 윤제형가옥이 있고 우측에는 윤승구가옥이 위치하고 있으며 ‘ㄱ’자 형의 안채와 ‘ㄴ’자형의 문간채가 함께 튼 ‘ㅁ’자형의 배치를 하고 있으며 안채는 안채마루 종도리는 광무 5년(1901년) 상량한 것으로 기록되어 있음. 안채의 부엌공간이 현대식으로 개조되고 부분적인 구조도 원래의 모습에서 변형된 부분이 있으나 전체적으로는 20세기 초창양식을 유지하고 있음","a":"아산 박우현가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019052217361400.JPG"},{"q":"‘○○○ 고려 ○○○’는 지하식 돌방무덤[石室墓]과 상부의 2층 기단이 결합된, 특이한 구조의 유구이다. ○○○는 우두산(해발 484.4m)에서 남서쪽으로 뻗어 내린 능선부에 위치하고 있다. 발굴 조사에 의하면, 돌방무덤은 지하에 깬돌을 쌓아 평면 형태가 원형인 무덤방을 조성하고 정면에 무덤방으로 들어가는 긴 네모꼴의 널길[羨道]을 만들었다. 천장은 평천장으로 너비가 1.3m나 되는 편평한 큰 돌 2매로 덮었다. 따라서 무덤의 전체 모습은 열쇠 구멍처럼 생겼다. 무덤방의 바닥 지름은 1.63m 가량이며, 높이는 1.67~1.75m이다.","a":"여주상교리고려석실묘","c":"시도기념물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647260.jpg"},{"q":"단장면 미촌리에 있는 ○○○은 일직손씨(一直孫氏) 시조인 손응(孫凝)의 20세손이며 격재 손조서(格齋 孫肇瑞)의 13세손인 칠산 손응용(七山 孫應龍:1741~1822)의 묘하제숙소(墓下齊宿所)로 철종 14년(1863년)에 창건되었다가 소실된 것을 1906년에 중창한 것이다. 증손인 손건(孫建)이 1868년 9월에 창건하여 당호(堂號)를 모선재(慕先齋), 구호당(龜湖堂)이라 하였으나 1895년 화재로 또 소실되어, 5대손인 손기형(孫基亨)이 1906년 중창하여 ○○○으로 고쳐불렀다.","a":"밀양 칠산정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666601.jpg"},{"q":"윤사형이 아들 윤무에게 노비,전답을 별급한 문기. 윤사형이 장손 윤여경의 생자를 기념하여 노비전답을 별급한 문기. 정밀의 첩 량정이 남편에게 자신 소유의 노비를 기상하는 문기 김몽린이 4자녀와 첩에게 재산을 분급하는 분급문기. 이중에 사위 문현도 있음 정밀이 아들 승업, 승훈에게 재산을 분급하는 분급문기. 정밀이 아들 승업, 승훈에게 재산을 분급하는 분급문기. 처변재산 중 토지를 분급. 정승업, 승훈 형제의 화회○○○. 모변 재산중 노비 분재. 하위보의 자 하증 등 5형제가 합의하여 재산을 나눈 문기.","a":"분재기","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642726.JPG"},{"q":"1728년(영조 4)에 이인좌(李麟佐)가 일으킨 반란을 토벌한 ○○○의 공적을 칭송한 비이다. ○○○은 안성과 죽산 전투에서 대승을 거두고 이인좌의 난을 진압하여 분무공신(奮武功臣) 1등에 봉해졌으며 우찬성을 거쳐 우의정에 발탁되었다. ○○○는 안성 군민들이 재물을 모으고 돌을 다듬어 1744년(영조 20)에 건립한 것이다. 함께 종군(從軍)하였던 조현명(趙顯命)이 비문을 짓고 박문수(朴文秀)가 글씨를 썼다. 그리고 이광덕(李匡德)이 전액(篆額 ; 전서체로 비석의 이름을 새긴 부분)을 썼다.","a":"오명항선생토적송공비","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637468.jpg"},{"q":"○○○는 경주 출신으로 호는 수운(水雲)이며, 외세의 침략과 봉건사회의 모순에 반대한 종교였던 동학(東學)의 교조(敎祖)이다. 가난했던 그는 장사를 하거나, 서당에서 글을 가르치면서 생계를 이었고, 의술(醫術)과 점술(占術)에도 관심이 많았다. 난세에 참된 도를 구하려 했던 수운은 양산, 울산, 경주 지방에서 수련을 멈추지 않았다. 1860년 4월 5일 마침내 결정적인 종교체험을 통해 도를 구하고, 그 이듬해부터 포교를 시작하였다. 1863년에는 경상도와 전라도뿐만 아니라 충청도를 넘어 경기도까지 교세를 떨쳤다.","a":"수운최제우유허지","c":"시도기념물","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018021417113000.jpg"},{"q":"함평군 월야면에 살던 동래 정씨·진주 정씨 두 문중의 아홉 부인들이 ○○○○ 때에 왜적을 피해 영광군 묵방포까지 피신하였다가, 왜군 를 만나서 의롭게 죽을 것을 결심하고 모두가 바다에 몸을 던져 순절한 곳이다. 아홉 부인들이 죽음으로 정절을 지킨 것을 기리기 위하여 숙종 7년(1681) 이곳에 순절비를 세웠다.","a":"영광정유재란열부순절지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654019.jpg"},{"q":"청계 김진 선생의 셋째 아들 운암 김명일(1534∼1570)의 종가집이다. 건물에 적힌 기록에 따르면 조선 영조 30년(1754)에 지은 것으로 추정된다. 안채, 사랑채 등으로 구성되어 있으며 안채와 사랑채가 서로 붙어 있는 형식이다. 안채는 앞면 6칸·옆면 6칸 크기에 ㅁ자형 평면을 갖추고 있다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이고, 가운데 대청을 중심으로 왼쪽에 웃방·안방 등을 배치하였다. 오른쪽에는 건넌방이 있어야 할 자리에 마루를 깔고 고방을 만들었는데 보기 드문 예이다.","a":"의성김씨운암종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658665.jpg"},{"q":"이 지역은 1883년 일본 조계(租界)를 시작으로 1884년 청국 조계(租界)가 설정되는 ○○지역으로 만국공원(현 자유공원)으로 연결되어 ○○과 조경이 마련된 공간이다. 약 120년의 역사를 그대로 간직하고 있는 본 ○○○○○은 중앙에 석조 ○○이 형성되어 있고, 양단을 중심으로 급한 경사인 점을 감안하여 ○○참을 두고, 조경식재 공간을 마련하여 공간의 이용적 측면과 인천항 경관을 여유롭게 즐길수 있도록 설계되어 있는 것이 특징이다.","a":"청·일 조계지 경계 계단","c":"시도기념물","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645682.jpg"},{"q":"○○○는 사원에 세우는 비로, 사원을 건립하게 된 동기와 모시는 인물을 찬양하는 내용을 기록해 둔다. 이 비는 임진왜란 때 우리나라를 도와준 중국 명나라의 임금인 신종과 의종의 제사를 지내는 ‘○○○’라는 사당에 자리잡고 있다. ○○○는 우암 송시열의 가르침에 따라 그의 제자 수암 권상하가 명나라 의종이 죽은 지 60년이 지난 숙종 30년(1704)에 지은 것이다. 비의 형태는 연꽃무늬를 새긴 바닥돌 위에 네모난 받침돌을 놓고, 그 위로 비몸을 세우고 지붕돌을 얹은 모습이다. 비문은 일본인들이 고의로 글자 획들을 쪼아 놓아 알아보기가 힘들다.","a":"괴산 만동묘정비","c":"시도기념물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649497.jpg"},{"q":"○○○과 ○○○는 권이진(1668∼1734) 선생의 호를 따서 지은 건물과 그에 소속된 재실로 보문산 남쪽 기슭 아늑한 곳에 자리잡고 있다. 부모를 간절히 생각하는 효성스러운 마음을 늘 품고 싶다는 뜻을 지닌 ‘유회(有懷)’는 중국 명나라 때 학자인 전목제의 ‘명발불매 유회이인(明發不寐 有懷二人)’이라는 시에서 따온 말이다. ○○○은 앞면 4칸·옆면 2칸 건물로 활수담이라는 작은 연못 뒤쪽에 있으며, 앞면과 양쪽 면에 난간이 돌려진 툇마루가 있고 가운데 넓은 대청마루를 중심으로 양쪽에 온돌방을 배치하였다.","a":"유회당(부)기궁재","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637185.jpg"},{"q":"○○○○○의 ○○를 간행하고 전해져오는 판목으로, ○○의 서문과 발문에 의하면 ○○의 원고가 완성된 것은 1648년이며 판목이 새겨진 것은 1685년경으로 판단된다. ○○를 통해보면 판목의 수량은 도합 40매 정도이며 현재 17매의 판목은 소실되고 23매 판목만 전해지고 있다. 비록 결판이 있기는 하나 17세기의 지방○○인쇄술의 수준과 판각술을 짐작할 수 있는 자료이고 보존상태가 양호하다.","a":"경주김씨 판도판서공파 족보 목판","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638959.jpg"},{"q":"옥련선원 내 삼성각(三聖閣) 뒷산에는 예로부터 인근 주민의 신앙대상으로 전해 오는 관덕암(觀德巖)이라는 바위군이 있는데, 이 바위군에서 벼락 때문에 떨어져 나온 바위면에 ○○○○ 1구가 새겨져 있다. ○○○○이 새겨진 바위는 거대한 바위 둘이 맞붙어 있었던 것인데 벼락을 맞아 깨어지면서 거꾸로 박혀있기 때문에 ○○○○은 아래위가 거꾸로 되어 있다.","a":"마애지장보살좌상","c":"문화유산자료","nc":"","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659351.jpg"},{"q":"고려 고종 때의 문신으로서, 고종 4년(1217)에 거란이 강동을 침입하였을 때 늙으신 아버지를 대신해 전쟁터에 종군하여 충효쌍수의 위업을 남긴 영헌공 ○○○의 시와 행적 등에 관한 기록을 모아 새긴 ○○이다. ○○○는 당시 전주사록에 임명되어 어려운 사람들을 돕고, 선정을 펼쳐 사람들이 그를 존경하였다. 그 뒤 내직으로 보문각교감, 판사재사 등을 지냈고, 지공거가 되어 과거시험을 주관하기도 했다. 그가 죽은 후 나라에서 ‘영헌’이라는 시호를 내렸다.","a":"김지대 영헌공실기 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642207.jpg"},{"q":"퇴계 이황 선생의 후예로 독립투사이며 시인이었던 육사 이활(1905∼1944) 선생의 생가이다. 一자형의 안채·사랑채가 평행으로 배치되어 있는데 서로 똑같은 공간을 이루고 있어 특이하다. 원래는 안동군 도산면 원천동에 있던 것을 1976년 4월 안동댐 수몰로 인해 이곳으로 옮긴 것이다.","a":"이육사생가","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658459.jpg"},{"q":"칠갑산 남쪽 기슭에 자리잡고 있는 절로, 신라 문성왕 3년(841)에 혜조국사가 지었다고 전한다. 이후, 517년경 전각이 모두 불타고 삼존불상만 화를 면했다. 16년 후 마곡사의 인명선사가 다시 짓고 여러 차례 보수·중건하였다. 1907년 큰 화재로 소실되었는데, 1908년 월파스님이 다시 지었다. 현재 절 안에는 삼존불상을 모시고 있는 대웅전과 산신각, 석굴암, 중암, 서암 등 암자가 있다. ○○○의 현판은 3·1운동의 33인 중 한 분인 오세창 선생이 직접 쓴 것이다.","a":"정혜사","c":"문화유산자료","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661141.jpg"},{"q":"○○○ 마을 가운데에 자리하고 있는 성당이다. 현재 남아있는 건물은 본당과 사제관 2동으로, 중국에서 기술자를 불러짓는 등 건축에 특별한 신경을 쓴 흔적이 곳곳에서 엿보인다. 본당은 직사각형 모양으로 예전에는 앞면에 종탑이 있었으나, 지금은 종을 치던 구멍만 남아있다. 1900년 9월 손우기, 김방수 등에 의해 본당건물이 건립된 것을 시작으로, 1906년 4월에 완성된 우리나라 초기 성당 중 하나이다.","a":"부여금사리성당","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019051414591200.jpg"},{"q":"조선 철종 8년(1857) 담양지역의 부사 벼슬을 지내던 황종림이 이 지역 노인들을 돌보고 젊은이들을 교육하기 위하여 지은 2개의 정자 중 하나이다. 1925년에 고쳐 지었고, 1981년에는 고속도로 건설로 인해 88올림픽 고속도로 옆으로 옮겨 지었다. ○○○은 앞면 2칸·옆면 2칸 규모로 이루어져 있으며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○처럼 노인을 돌보고 젊은이를 교육하기 위하여 지은 정자는 매우 드물고 중요한 사례이다.","a":"남희정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661918.jpg"},{"q":"○○○○ 문중에서 소장하고 있는 ○○○로 계후입안(繼後立案) 1매, 호구단자(戶口單子) 7매, 노비매매문서(奴婢賣買文書) 2매 등 모두 10점이다. 계후입안은 양자 들이는 것을 증빙해 주는 입안으로서, 가경 5년(1800)에 작성된 것이다. 김신한(1766∼1798)이 아들 없이 죽자, 그의 아내 함안조씨(1767∼1827)가 남편의 육촌형 김개한(1762∼1815)의 둘째 아들 형윤(1787∼1840)을 양자로 들이려고 양측이 서로 합의한 내용을, 관청으로부터 인준받은 것이다.","a":"산청 상산김씨 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664923.jpg"},{"q":"◦ 보령지방의 해안은 조석간만의 차가 커서 예부터 갯벌에 살을 매어 고기를 잡는 전통 어로가 많이 행해졌음. 그중 갯벌에 돌로 담을 쌓아 만든 살을 독살이라하며, ○○○에는 10곳의 독살이 있었는데 모두 훼손되고 이 곳 독살만이 형체를 유지하고 있음. ◦ 원래 2개였던 독살이 하나로 통합된 형태로 북쪽 날개의 길이는 70m 정도이고 남쪽의 날개는 100여m 정도임.","a":"보령독산리독살","c":"시도민속문화유산","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658267.jpg"},{"q":"‘○○○○’은 조선 시대의 학자인 성수침(成守琛, 1493-1563)과 그의 아들 성혼(成渾), 아우 성수종(成守琮) 및 백인걸(白仁傑)의 위패를 모시고 제사 지내는 곳이다. 1568년에 세워졌으며, 1650년에 나라에서 인정받아 ‘사액서원’(賜額書院 ; 국왕으로부터 서적·토지·노비 등을 하사받아 그 권위를 인정받은 서원)이 되었다. ○○○○은 ‘기호사림’(畿湖士林; 경기도와 충청도를 근거지로 하는 사림)이 중심이 된 서인(西人; 조선 시대의 한 정파)들의 본거지가 되기도 하였다.","a":"파산서원","c":"문화유산자료","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659854.jpg"},{"q":"조선 후기의 문신인 ○○○ 선생의 ○○화이다. ○○○은 광해군 15년(1623) 인조반정에 공을 세워 기평부원군에 봉해졌고, 이후 대사간과 이조참판을 지내었다. 사후에는 영의정에 추증되었으며, ‘충경공’이라는 시호를 받았다. 그림은 짙은 회갈색의 무늬없는 관복을 입고 약간 오른쪽을 바라보고 않은 전신좌상으로, 크기는 가로 95㎝, 세로 174㎝ 이다. 옷주름이 힘차게 표현하였으며, 머리에 쓴 사모는 비교적 꼼꼼하게 묘사하였다. 두 손은 옷소매 안에서 마주 잡고 있다.","a":"유백증 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638677.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 쌍계사로 들어가는 입구에 마련된 이 부도밭에는 모두 9기의 부도가 자리잡고 있다. 이 절에서 돌아가신 아홉 승려의 사리를 모셔두고 있는데, 6기는 종모양을 하고 있고, 나머지 3기는 지붕돌을 갖춘 4각 부도이다. 종모양의 탑몸돌을 하고 있는 부도들은 4각 또는 6각의 바닥돌 위에 놓여 있다. 바닥돌은 연꽃무늬를 둘렀으며, 탑몸돌 꼭대기에는 꽃봉오리 모양의 돌을 얹어 머리장식을 하였다. 지붕돌을 올린 부도들은 기단(基壇) 위로 동그란 탑몸돌을 얹고 지붕돌을 덮은 모습이다.","a":"쌍계사부도","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661017.jpg"},{"q":"○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 쌓아두는 돌탑으로, 부정과 악의 출입을 막아 마을을 평안하게 하고자 하는 신앙의 대상물이다. 이 ○○○은 ○○○ 마을의 엉물부근 해안도로 주위에 동서로 서 있는 2기의 ○○○ 중 동쪽에 자리하고 있다. 높이가 402㎝로, 정상에 새의 형상을 한 약 50㎝의 긴 돌이 놓여 있는데, 이는 북쪽의 액운을 막기 위해서라고 한다.","a":"몰래물마을방사탑1호","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659242.jpg"},{"q":"조선후기(19세기)의 전형적인 ○○○○○으로 4개의 면을 이어 붙여 만들었다. 직육면체의 동체 윗부분에 가운데가 잘록한 목을 별도로 만들어 붙였다. 동체의 4면에는 가장자리를 1줄의 청화선으로 두르고 근경, 중경, 원경의 ○○○○○을 회화적으로 그려 넣었다. 모서리를 깎아 낸듯 좁게 비껴난 어깨부분에도 청화선을 두르고 그 안에 간략한 당초문으로 장식하였다. 청화색은 약간 어두우며 동체전면에 담청색을 띠는 유약을 입혔다. 바닥은 평저(平底)이며 바닥에는 유약을 닦아낸 뒤 가는 모래를 받쳐 구웠다.","a":"백자청화산수인물문사각병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636468.jpg"},{"q":"충청남도 부여군 부여읍 ○○○에 있는 고려시대의 옛 절터에 모셔졌던 주존불(主尊佛)로서, 현재는 절터만이 남아 있다. 부처의 얼굴이 눈병에 효험이 있다는 이야기가 전해져서 얼굴이 많이 손상되었다. 머리 위에는 넓은 상투 모양의 머리묶음이 있으며, 둥글고 풍만한 얼굴은 손상되어 세부기법은 알 수 없다. 양 손은 가슴에 모아 오른손이 왼손 검지를 감싸고 있는데, 손과 발의 세부수법이 형식화 되었다. 옷은 몸에 밀착되어 간략한 옷주름으로 표현하여 무릎 앞에까지 덮여 있는데, 옷주름이 섬세하지 못하다.","a":"부여석목리석조비로자나불좌상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639035.jpg"},{"q":"○○○○○는 대청댐 수몰 전 문의초등학교 정문에서 남쪽으로 100m 전방에 있던 것인데 1980년 대청댐 건설로 문의면 미천리에 문산관과 함께 이전하였다가 2002년 3월 문의문화유산단지로 재이전하였다. 이 석교에 대한 문헌은 조선 헌종 초기에 편찬된 「충청도읍지(忠淸道邑誌)」에 처음으로 나온다. 축조시기는 고려시대로 추정되는데 교각내에 을묘이월(乙卯二月)이라는 각자가 남아 있다. 교각 상판은 2.5m×0.3∼0.9m 규모의 화강석과 청석으로 이루어져 있는데 총 10개이며, 석주는 1.3m의 화강석으로 이루어져 있다.","a":"청주 문산리 돌다리","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638795.jpg"},{"q":"○○○○○는 금수산에 있는 사찰로 신라시대에 지어졌다고 하나 정확한 창건연대는 알 수 없다. 다만 현재 법당인 극락전은 영조 16년(1740)에 중수한 것으로 확인되었으며, 이 목조여래좌상은 극락전을 건립할 때에 함께 조성된 불상으로 추정된다. ○○○에는 목조여래좌상 이외에도 청동보살머리, 전패(殿牌) 등이 전한다. 극락전에 모셔져 있는 목조여래좌상의 보존상태는 양호한 편이며, 최근에 극락전을 새로 고치고 단장하면서 목불에 금박을 다시 입혔다. 불상의 규모는 비교적 큰 편으로 통나무로 조각되었는데 두 손은 따로 만들어 끼운 형태를 하고 있다.","a":"제천 무암사 목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638766.jpg"},{"q":"○○○○○은 ○○○ 난골마을 구릉에 1기, 경작지의 논두렁에 1기가 있으며, 서로 300m 간격으로 떨어져 있다. 덮개돌은 화강암으로 땅 위에 비스듬히 놓여 있는데 논두렁에 있는 것은 크기가 길이 210㎝, 너비 210㎝, 두께 90㎝정도이며 받침돌은 보이지 않는다. 구릉에 있는 것은 길이 180㎝, 너비 150㎝, 두께 90㎝정도이며, 받침돌로 추정되는 돌들이 덮개돌 아래에 깔려 있다. 내부 구조는 학술조사를 실시하지 않아 자세히 알 수 없다. 이 ○○○○○은 청동기시대 ○○○ 일대의 정치·사회·문화 등을 연구할 수 있는 중요한 자료가 된다.","a":"창평동지석묘군","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645903.jpg"},{"q":"○○○에 보존되어 있는 그림으로, 석가가 영취산에서 설법하는 모습을 그린 ○○○○○이다. 이 ○○○○○는 면 바탕에 채색하여 그려진 것으로, 화면은 중앙에 석가여래상이 연꽃무늬 대좌 위에 결가부좌하고, 그 전면 좌우측에는 문수·보현보살이 안쪽을 향한 모습으로 연꽃무늬 대좌 위에 반가좌하고 있으며, 그 위쪽으로 사천왕상과 관음·세지보살, 그리고 아난·가섭상을 비롯한 제자상이 본존을 에워싸고 있다. 본존의 육신부는 황색을 바르고 먹선의 하묘선 위에 붉은색 선으로 윤곽선을 처리하였다. 머리 부분은 입자가 거친 군청안료를 바르고 윤곽선은 녹청으로 융기되게 표현하였다.","a":"마하사 영산회상도","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659360.jpg"},{"q":"오봉 권책 선생의 후손 권응주가 분가하면서 지은 집이라고 전하며 1700년대에 고쳐 지었다고 한다. 집은 크게 정침·사당·곡강정으로 구성되어 있는데, 정침 오른쪽 뒤에 사당이 있고 앞면 왼쪽에 곡강정이 자리잡고 있다. 정침은 앞면에 4칸 대청을 두고 좌우로는 온돌방을 두었다. 왼편에 광·안방·부엌을 배치하여 왼쪽 곁채와 연결하였고, 오른편에는 출가한 자녀가 사용했다는 신방과 마루가 놓이면서 오른쪽 곁채와 연결된다. 사랑채 부분은 사랑방을 중심으로 오른쪽에 마루방을 설치하였다.","a":"곡강고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658869.jpg"},{"q":"지금 부평초등학교 교정 모퉁이에 있는 옛 ○○○○○ 건물이다. ○○○○○는 숙종 3년(1677)에 중수했다는 기록이 있으나 세워진 내력을 정확히는 알 수가 없다. 고려시대 의종 4년(1150)에 안남○○○로, 고종2년(1215)에 계양○○○로, 조선시대 태종 13년(1413)에 부평부가 ○○○○○로 승격되었다. 따라서 모든 정황으로 볼 때 ○○○○○로 승격이 되면서 ○○ 건립에 착수하여 약 5년 후(태종 18년, 1418)에 완공된 것으로 보인다. ○○ 옆에 보호되고 있으며 이때 풍치목으로 심어진 듯한 은행나무의 수령이 약 600여년쯤 되는 것과도 일치한다.","a":"부평도호부 관아","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019102116124600.jpg"},{"q":"○○○은 ○○○○○가 선농불교(禪農佛敎)를 실천하며 일제시대 독립운동 자금조달을 위한 농장이다. ○○○○○는 3.1운동 당시 민족대표 33인의 한사람으로 독립운동가이고 불교에서는 반농반선의 선농불교를 주창·실천하였다. ○○○○○는 이곳의 산림과 황무지를 개간하여 과수를 심고 ○○○이라는 농장을 설립하였다. ○○○○○는 백운산의 8부능선에 위치하여 외부에서의 접근이 쉽지 않다. 이곳을 거점으로 일제의 억압을 피해 뒷산으로 넘어 다니며 독립운동을 하였다고 전한다.","a":"함양백룡성선사화과원유허지","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656914.jpg"},{"q":"新增 東國輿地勝覽 金海都護府 城地條에 보면 「마현성 : 과녀산성(寡女山城)」 이라고 한다. 북쪽으로 30리, 둘레 1300척 우물의 하나이다. 」 라고만 기록되어 있어 자세한 축성내역은 일 수가 없다. 일설에는 가락국 수로왕때 축조된 것이라고 하나 신빙성이 없다. 위치는 생림면 면소재지인 봉림에서 밀양, 삼량진으로 가는 지방도로를 따라 북쪽으로 4km정도 올라가면 마현마을이 있는데 이 마을 건너편 즉 도로 오른쪽에있는 산성 성이 바로 ○○○○이다. (현황) 이 성은 해발 약 215m정도의 뾰족하고 경사가 심한 독립된 산봉우리 정상부 주위에 축조되어 있다.","a":"김해 마현산성","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655878.jpg"},{"q":"이 건물은 조선후기의 실학의 대가인 이재 황윤석(1729~1791)선생의 생가이다. 이재 선생의 선친인 황전공이 건립하였으며 지금은 안채, 사랑채, 문간채가 남아 있다. 안채는 정면 6칸에 앞뒤에 퇴간을 둔 5량 가구의 일자형 벽체는 안방에서 아래, 중방사이를 모두 관벽으로 하고 중방에서 하방사이는 솟을 동자를 세운 머름청판으로 꾸며 격식을 갖춘 것이 특색이다. 당초에는 사랑이 안채 뒷편에 있었으나 터만 남아 있고 사랑채, 문간채는 소실 되었던것을 1909년에 다시 지었다.","a":"황윤석생가","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658314.jpg"},{"q":"본 불상은 허리를 곧게 펴고 머리를 약간 숙여 결가부좌의 자세를 하고 있는 여래상이다. 머리에서 무릎아래까지 불신 전체의 내부를 깊게 파내어 조각한 목조불로서, 전체적으로 보존상태가 양호한 편이다. 양 손은 제1지와 제3지를 맞댄 채 양팔을 옆구리에 붙인 상태로, 오른팔은 팔꿈치를 접어 가슴 높이에서 손바닥이 보이도록 바깥을 향하고, 왼팔은 손바닥을 위로 하여 가슴 아래에 위치한 중품하생인의 모습이다. 복장물은 불상의 내부를 복장개부의 입구에서부터 얼굴부위까지 경전 등으로 가득 채우고 있었는데, 주로 책자형 경전과 향 등이었다.","a":"선암사 목조아미타여래좌상 및 복장유물","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636781.jpg"},{"q":"○○○는 파평윤씨의 화양동 입향조인 사제공 윤장 선생을 기리기 위해 문중과 유림에서 성금을 모금하여 지은 재실로 1907년 중수된 건물이다. 윤장 선생은 조선조 문과에 급제하여 사제판사(司帝判事) 벼슬을 지내던 중 단종 원년(1453)의 계유정난을 피하여 낙향하여 화양동에 은거하면서 강학하였다. 배면 경사지형을 정지하여 거의 평지에 가깝게 조성한 대지에 1칸의 대문채와 재실을 일직선상에 배치하고 4면에 담장을 둘렀다.","a":"합천 영사재","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664914.jpg"},{"q":"조선시대 여산부의 관아건물로, 개조하여 여산 우체국으로 이용하다가 현재에는 경로당으로 사용하고 있다. 앞면 5칸·옆면 3칸의 규모로, 지붕의 옆선이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 낮은 기단 위에 앞면과 왼쪽에는 약 90㎝ 높이의 둥근 주춧돌을 놓고 뒷면과 오른쪽은 경사지를 이용하여 낮은 주춧돌을 놓았다. 지붕 처마를 받치기 위해 장식하여 만든 공포를 짜지 않고 소박한 민도리로 처리하였으며, 앞뒤에 퇴칸을 두었다.","a":"여산동헌","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639506.jpg"},{"q":"둔산동 ○○○○은 우리나라에서는 처음으로 한 곳에서 구석기·신석기·청동기시대의 유적이 발굴된 곳이다. 구석기시대의 유적은 약 2백평 정도의 면적에서 몸돌, 망치돌 등 50여점의 석기와 석기를 만들 때 떨어져 나온 작은 부스러기들이 나왔다. 이들 유물 가운데 쌍날찍개, 긁개, 밀개 등은 유물의 형태와 떼어낸 수법으로 보아 후기구석기의 이른 시기이거나 중기구석기의 늦은시기 유물로 보인다. 신석기시대의 유적은 직경 2∼3m 내외, 깊이 0.8∼1.3m 정도의 작은 집자리 유적 13기가 조사되었으며, 빗살무늬토기 조각·보습·갈돌·어망추 등이 나왔다.","a":"둔산선사유적지","c":"시도기념물","nc":"","r":"대전광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645815.jpg"},{"q":"조선 전기 문신인 금남 오응(1422∼1470) 선생이 할아버지의 묘 근처에 세운 재실이다. 지은 시기는 정확히 알 수 없으나 오응 선생의 호가 금남이라서 ‘금남재’라 불렀다. 오응은 4도 관찰사를 지냈으며, 그의 할아버지는 오상덕 선생으로 황희 정승의 매형이다. 그런 인연으로 황희 정승을 모시고 있는 대강면 풍계서원에서 함께 제향하여 오다가 자기 조상을 남의 가문에서 계속 모시게 할 수 없다고 하여 오씨 문중에서 금남재 옆에 ‘술산사’를 지어 따로 모시게 되었다고 한다.","a":"남원금남재","c":"시도기념물","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653345.jpg"},{"q":"○○○는 조선초 군령과 군무를 총괄하던 군사 기구로 의흥○○○의 약칭이다. 그 후 여러 차례 제도의 변화를 겪다가 고종 2년(1865)에 흥선대원군이 다시 조직했으나, 고종 17년(1880) 폐지하고 통리기무아문에 소속되었다. ○○○은 흥선대원군 집권 당시 ○○○ 청사로서 고종 5년(1868)에 지은 것이다. 고종 17년(1880)에 통리기무아문 청사로, 고종 31년(1894) 이후로는 시위대 청사로, 순종 4년(1910)부터 1926년까지는 조선 보병대 사령부로 쓰였다.","a":"삼군부 청헌당","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636086.jpg"},{"q":"조선 선조 39년(1606) 유빈 선생의 무덤을 수호하기 위해 후손 영순이 지은 건물이다. 유빈 선생은 고려말 이방원(조선 태종)과 같이 과거에 합격하고 영흥부사를 지냈다. 건물의 구성은 ㄱ자형의 행랑채와 제사를 지내는 곳인 추원재와 정침이 튼ㅁ자형을 이루고 있으며, 문틀 가운데에 문설주를 설치한 특이한 구조를 하고 있다. 조선 중기의 재실 모습을 잘 유지하고 있는 건물로 평가 받고 있다.","a":"종릉재사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640866.jpg"},{"q":"탑이 서 있는 터 주변에는 청량사라는 절이 있었다고 하며, 곳곳에 절을 이루는 건물에 쓰였던 돌과 기와조각이 흩어져 있다. 탑의 둘레에 높이 1m 가량의 석축을 쌓아 기단부(基壇部)는 거의 보이지 않아 맨윗돌만 드러나 있고, 그 위에 5층의 탑신(塔身)이 올려져 있다. 탑신의 각 층 몸돌은 모서리마다 기둥모양을 새겼으며, 2층 이상은 1층에 비해 급격히 낮아졌다. 지붕돌은 밑면의 받침이 3단씩이고, 네 귀퉁이는 약간 들려 있다. 꼭대기에는 노반(露盤:머리장식 받침)과 복발(覆鉢:엎어놓은 그릇모양의 장식)만이 남아 머리장식을 하고 있는데, 후대에 만들어 보충한 것이다.","a":"부여세탑리오층석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639030.jpg"},{"q":"○기원전 1세기~기원후 3세기경에 축조된 것으로 제주도 고인돌 분포에 있어 산북지역의 외도, 광령지역과 같이 군집을 이루고 있고 원형을 유지하는 등 제주도의 전형적인 ○○○로 제주의 선사시대 연구를 위한 귀중한 학술자료로서 문화유산적 가치가 높이 평가 되고 있어 향토문화 보존에 필요하다고 인정되는 유적임.","a":"상예동지석묘5호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657721.jpg"},{"q":"\"조선 중기의 문신이자 학자인 약봉(藥峰) 서성(徐省, 1558∼1631) 선생의 묘이다. 1613년(광해군 5)에는 계축옥사에 연루되어 단양·원주 등에서 11년간 귀양살이를 했다. 인조반정 후 복직하였다. 묘역은 부인 여산 송씨(礪山宋氏)와 함께 합장된 단분(單墳 ; 하나의 봉분)의 형태이다. 곡장(曲墻 ; 봉분이 있는 구역을 보호하기 위해 주위에 두르는 담)은 1969년에 신축한 것이지만, 묘제(墓制)와 석물은 대부분 옛 것 그대로이다. 봉분 아래에는 원형으로 둘레석을 세워 봉분을 보호하였는데, 사대부 묘로서는 독특한 묘제이다.","a":"서성선생묘","c":"시도기념물","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646036.jpg"},{"q":"근대 시기의 대표 언론인 민세 안재홍(安在鴻, 1891~1965)이 태어나 살던 집이다. 안재홍은 일제강점기에 조선일보 주필로 재직하면서 신간회와 물산장려운동을 이끌었으며, 고대사 연구와 문자보급에 앞장선 민족지사이며 학자였다. 이 집은 평택시 고덕면 계루지 마을의 야산 기슭에 남향하고 있다. 원래 상당한 규모의 집이었으나 지금은 안채와 사랑채, 대문채만 남아있다. ‘ㄱ’자형 안채와 ‘一’자형의 사랑채가 안마당을 중심으로 ‘ㄷ’자형 배치를 이루고 사랑채의 동쪽으로 대문채가 위치한다. 상량문에 안채는 1914년에 지었으며, 사랑채는 1932년에 지었다고 기록되었다.","a":"안재홍생가","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646706.jpg"},{"q":"1972년에 청담대종사의 사리탑 및 사리탑비·사적비 등을 조성하기 위해 사리탑 부지를 터파기할 때 고려 범종 1점을 비롯한 ○○시(靑銅匙) 5점, ○○저(靑銅箸) 1짝, ○○국자 2점, 동경 1점, 동전 1점이 ○○로 출토되었으며, 현재 청담기념관에 보관중이다. 출토지가 분명한 이 ○○들은 전형적인 고려시대 금속공예품과 조선시대 상평통보(常平通寶), 그리고 일본 에도시대 동경이 서로 섞여 있는데 이는 사리탑 부지가 오랜 기간 존속된 건물지임을 증명해주고 있다.","a":"도선사 청동 종 및 일괄 유물","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594733.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 묘앞에 세워두는 것으로 이 비는 조선 숙종 때 우의정을 지낸 ○○ 선생의 공적을 기리고 있다. ○○는 숙종 8년(1682) 문과에 급제한 후 사헌부 ·사간원에 재직하면서 당대의 시국에 대한 많은 상소를 올리는 한편 노론과 소론의 격심한 당쟁을 완화시키려 애썼다. 그후 대사간을 거쳐 판결사로 있을 때에는 노산군의 복위를 주장하여 단종으로 왕위를 회복시켰고, 아울러 단종비 송씨의 묘를 능으로 추봉하고 능을 조성하는 공사를 맡아 보았다. 이후 형조판서를 거쳐 숙종 29년(1703) 우의정이 되었다.","a":"충헌공 김구 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"송파구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636207.jpg"},{"q":"조선 영조(재위 1724∼1776)의 후궁이자 사도세자의 어머니인 영빈 이씨의 신주를 모시고 제사지내던 왕실의 사묘인 ○○○이 있던 자리이다. 후궁에게서 태어난 임금이 모친의 신위를 모신 사당을 사묘라고 한다. 처음에는 의열묘라 불렀으나 영빈의 손자인 정조가 왕위에 오른 뒤 대우를 높여서 ○○○이라 이름을 고쳤다. 현재 영빈의 신주는 육상궁에 모시고 있는데, 융희 2년(1908)에 옮긴 것이다. 앞면 3칸·옆면 2칸 규모의 1층 건물로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이고 벽은 벽돌로 쌓았다.","a":"선희궁 터","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636114.jpg"},{"q":"마을입구의 마련된 보호각 안에 서 있는 2구의 장승으로, 할아버지와 할머니의 모습을 하고 있다. 마을사람들은 장승이라기보다 비석이라고 부르며 있으며, 이 거리를 ＇비석거리라 칭하고 한다. 할아버지 비석은 얼굴이 전체의 절반을 차지하고 있다. 원유관을 쓴 머리, 움푹 패인 눈, 넓은 코, 두꺼운 입술, 역삼각형의 수염 등이 표현되었고, 관리가 임금을 뵐 때 손에 쥐는 홀을 들고있다. 할머니 비석은 머리가 위로 치켜올라간 듯 둥그런 얼굴을 하고 있으며, 눈은 패였고 코와 입은 닳아서 흔적만 남아있다.","a":"천변리석인상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661934.jpg"},{"q":"입석(선돌)은 길쭉하고 커다란 돌을 약간만 다듬어 마을 입구 등에 세워 기념하거나, 신앙의 대상물로 삼았던 것으로, 주로 마을의 경계를 나타내거나, 농사의 풍요를 위해 세웠다. 섬진강 주변의 완만한 언덕 위에 자리하고 있는 이 입석은 거대한 자연돌을 세워 놓은 것으로, 섬진강을 내려다 보며 서 있다. 전체적으로 네모지고 두툼한 모습이며, 앞·뒷면은 거친 편이나 옆면은 고르게 잘 다듬어 놓았다. 마을 주민들에게는 소원을 빌고 액운퇴치를 기원하는 민간신앙의 대상이 되고 있으며, 규모가 꽤 큰 편이다.","a":"구산리입석","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662053.jpg"},{"q":"퇴수헌 라사종(退修軒 羅嗣宗, 1440~1491)의 충절을 기리기 위해 세운 충신문과 그의 아들 라운걸(羅云傑, 1456~1493)과 손자 라빈(羅濱, 1473~1495), 라린(羅潾, 1475~1495) 세 부자의 효성을 기리기 위해 세운 삼효문이다. 라사종은 1491년(성종 22) 여진족을 막다 전사하였고, 라운걸과 라빈·라린 형제도 부친의 원수를 갚지 못하자 삼년상을 마치는 날 자결하였다. 1638년(인조16)에는 라사종의 충신 정려가, 1717년(숙종 43)에는 라운걸 세 부자의 삼효 정려와 라사종의 벼슬과 충정忠貞 시호가 내려졌다.","a":"청주 안정라씨 삼세충효문","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649692.jpg"},{"q":"예산 ○○○○○는 돌의 홈을 중심으로 왼쪽과 오른쪽에 비문이 각자(刻字)되어 있는데 내용을 살펴보면 다음과 같다. 오른쪽 석각은 “□□6년 계미 3월 12일(□□六年 癸未 三月 十二日)에 이산(伊山)과 덕풍(德豊)의 승려와 결연 향도들이 축대를 쌓아 비석을 올려놓고 고한다. 성에서 나와 용오리 들머리에 매향을 도감(都監) 승려들이 함께 하였다[□□六年 癸未三月十 二日伊山德豊袈裟 結(緣)香徒□告 城出龍吾里埜頭 埋香庫同].”라는 내용이다.","a":"예산효교리매향비","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653101.jpg"},{"q":"남주한의 조상에게 제사지내는 곳으로 순조 28년(1828)에 지었으며, 1888년에 수리하였다. 앞면 4칸·옆면 2칸 규모로 지붕은 옆면이 여덟 팔자 모양인 팔작지붕이다. 대청을 중심으로 좌·우에 온돌방 2개가 있으며, 돌담과 높이 솟은 대문, 현판 그리고 이곳에 대한 기록이 원형대로 보존되어 있다. 특히 이곳은 온돌방에 불을 지피면 연기가 내부로 빨려 들어가게 하여 열효율을 극대화하도록 굴뚝을 설치하지 않은 특이한 건물이다. ○○○는 전통온돌의 구조를 연구하는데 귀중한 자료가 된다.","a":"영동 영모재","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638669.jpg"},{"q":"이곳의 ○○○○○ 화석은 약 1억년 전의 전기 백악기 시대에 살았던 공룡들의 것으로 보인다. 당시의 공룡들은 아열대 기후 아래 우기와 건기가 반복되고 열대 무역풍이 영향을 미치는, 사바나 지역의 하천평야 일대에서 살았던 것으로 알려져 있다. 대곡천에는 여러 장소에서 ○○○○○이 확인되지만, 이곳의 ○○○○○ 화석은 보존상태가 가장 양호한 것이다. 이곳의 ○○○○○은 약 100㎥ 넓이의 바위에 새겨져 있는데, 용각류 팔용과에 속하는 것(60톤급)과 조각류 이구아나과에 속하는것(고성룡족인) 등 24여 개다.","a":"대곡리공룡발자국화석","c":"문화유산자료","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659796.jpg"},{"q":"일제시대 당시 횡성군내의 옛 절터에 있었던 것을 옮겨 온 것으로, 바닥돌과 기단(基壇)을 잃어버려 3층의 탑신(塔身)만 남아있다. 남아 있는 탑신 각 층의 몸돌과 지붕돌은 각각 하나의 돌로 쌓아 올린 것이다. 몸돌의 높이는 1층보다 2층이 많이 줄어들었고, 3층은 2층보다 조금 작다. 위로 올라갈수록 적당하게 작아져 안정감을 주고 있는 지붕돌은 밑면의 받침이 4단씩이고, 윗면의 경사가 급하며, 네 귀퉁이는 살짝 들려 있다. 3층 지붕돌 윗면에는 6㎝정도의 작은 구멍이 있는데, 이곳에 머리장식을 설치하였던 것으로 보인다.","a":"읍하리삼층석탑","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637907.jpg"},{"q":"고려 중기의 문신 문극겸(1122∼1189) 선생을 모신 사당이다. 문극겸은 고려 의종(재위 1146∼1170) 때 문과에 급제한 후 여러 관직을 두루 역임하다가 의종 24년(1170) 정중부의 난 때 죽음을 당할뻔 했으나 전에 내시 백선연의 비행을 탄핵한 덕분으로 화를 면하였다. 이후 명종(1170∼1197)이 왕에 오르자 이의방의 추천으로 높은 관직에 올라 많은 문신들을 어려움에서 구하였다. 무신 정권기에 문신으로 장군직을 겸임하여 문무를 겸하는 시초가 되었으며 글씨에도 매우 뛰어났다.","a":"고간원지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652765.jpg"},{"q":"○○○○○은 고려시대에 우리나라 연안을 빈번히 침범하던 왜구의 노략질을 막기 위해 설치한 구라량의 진영이 있던 곳이다. 그 뒤 구라량이 폐쇠되어 쇠퇴했던 것을 조선 순조(재위1801∼1834) 때 진주 병마절도사가 진주목 관하의 창선도와 적량첨사와의 군사적 연락을 위해, 둑을 쌓아 ○○을 만든 것이다. 당시에는 300여 명의 상비군과 전함 2척을 상주시켜 병선의 정박지로 삼고 왜구를 방어하였다. 이 ○○○○○을 쌓기 위하여 진주목 관하 73개면에서 수천명이 동원되어 1820년경에 완공하였다고 전한다.","a":"사천 대방진 굴항","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664034.jpg"},{"q":"○○○에 보존되어 있는 그림으로, 지장보살과 시왕(十王)을 그린 불화이다. 크기는 세로 186㎝, 가로 205㎝로, 사자머리가 장식된 높은 대 위에 양반다리로 앉아있는 지장보살을 중심으로 그 좌우에 70구에 달하는 각종 상들을 정연하게 배치하였다. 조선 후기의 ○○○ 중에 유난히 많은 무리를 거느리고 있는데, 정연한 배치를 위해 그림 중간에 붉은색 구름을 그려넣어 화면을 위아래로 나누었다. 중앙에 있는 지장보살은 깎은 머리에 투명한 두건을 쓰고 있으며 손에는 기다란 지팡이와 보주를 들고 있다. 옷은 양 어깨에 걸치고 있고, 몸에는 귀걸이와 팔찌 등을 장식하였다.","a":"홍천수타사지장시왕도","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638179.jpg"},{"q":"○○○는 통일신라 성덕왕 22년(723)에 삼법화상이 ‘옥천사’라 하여 세운 절로 그 뒤 정강왕 때 ‘○○○’라 바꾸었다. 절 경내에는 대웅전, 설선당, ○○○, 고승당 등의 많은 건물들이 있다. ○○○는 통일신라 문성왕 2년(840)에 진감선사가 세웠고 조선 인조 19년(1641)과 1978년에 보수를 하였다. 이곳은 우리 민족에 맞는 불교음악(범패)을 만든 곳으로 훌륭한 불교 음악의 명인을 많이 배출하였다. 또한 진감선사가 섬진강에 뛰노는 물고기를 보고 팔음률로서 ‘어산(魚山)’이란 불교 음악을 작곡하였다고 하여 ○○○라 한다.","a":"하동 쌍계사 팔영루","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663976.jpg"},{"q":"○○○는 신라 성덕왕(聖德王) 18년(719)에 중아찬 김지성(金志誠)이 자신의 장전(莊田)을 희사(喜捨)하여 부모의 명복과 일족(一族)·국왕의 안녕을 빌기 위하여 창건하였다. 현재 대적광전(大寂光殿)에 봉안된 석조 ○○○○○의 머리부분(頭部)과 앞면은 훼손이 심하고 광배(光背)와 대좌(臺座)는 없어졌다. 양쪽 다리는 결가부좌(結跏趺坐)한 모습으로 지권인(智拳印)을 결(結)하고 있으며, 넓고 건실하게 조각된 무릎과 더불어 어깨선도 각(角)이 진 당당한 모습을 하고 있다.","a":"감산사석조비로자나불좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641043.jpg"},{"q":"○○○○○ 지장삼존불상 뒷면에 봉안된 이 탱화는 ○○○ 대웅전에 봉안된 석가영산회상도와 께 1856년에 제작된 것이다. 비단 바탕에 채색으로 그려진 이 불화는 부분적으로 얼룩 및 박락이 진행되고 있으나, 전체적으로 화면 상태는 양호한 편이다. 화면의 구도는 중앙의 지장보살을 중심으로 하단 전면에 도명존자와 무독귀왕을 비롯하여 옆으로 사천왕이 나란히 배치되어 있으며, 상단에는 4위의 보살이 좌우대칭으로 둘러 싼 구도이다.","a":"장안사 명부전 지장보살도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636768.jpg"},{"q":"선조 때 진사참봉을 지낸 청주 한씨 한춘부와 효종 때 한두남의 제사를 모시는 곳이다. 1925년 세운 이 재실은 안채, 관리사 2동으로 되어 있는데 안채는 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 이 건물은 제사를 지내는 곳으로 중앙마루를 중심으로 좌우에 온돌방을 배치하였고 방과 마루 사이에는 문을 달아 필요시 하나의 공간으로 활용할 수 있게 하였다. 관리사는 앞면 2칸·옆면 2칸 규모의 건물로 주변에는 4각으로 흙담을 쌓았다. ○○○는 성주댐의 건설로 지금 있는 자리로 옮겨 관리하고 있다.","a":"봉두리영모재","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663045.jpg"},{"q":"신재 주세붕의 업적을 기리기 위해 세운 서원이다. 주세붕(1495∼1554)은 조선 전기 문신이며 학자이다. 주로 홍문관과 성균관 등 학문기관의 관직을 지냈으며, 지방관으로 있을 때에는 교학진흥을 통한 교화에 힘썼다. ○○○○은 선조 24년(1591)에 ‘동림서원’으로 세웠으나, 현종 원년(1660)에 칠원현 남고에 ‘남고서원’으로 새로 세웠다. 숙종 2년(1676)에는 ‘덕연’이란 이름을 나라로부터 받아 사액서원이 되었다. 그 뒤 흥선대원군 서원철폐령으로 고종 5년(1868)에 폐쇄되었다가 1964년에 다시 세웠다.","a":"함안 덕연서원","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663961.jpg"},{"q":"세종25년(世宗;1443) 전라도 화암사(花岩寺)에서 찍은 목판본으로 당대의 명필인 성달생(成達生)*이 쓴 것이다. 시주(施主)에 이녕대군(李寧大君), 영흥대군(永興大君) 등이 동참했으며, 사육신 중 한사람인 성삼문(成三問)이 감찰(監察)로 등장한다. 이와 동일한 판본으로 전남 영광군 군남면 용암리 월명산 890번지 소재 연흥사(烟興寺) 소장(所藏) 『○○○○○』이 전라남도 유형문화유산 175호로 지정되어 있으며 이 책은 화암사판의 번각본(飜刻本:한 번 새긴 책판을 본보기로 삼아 그 내용을 다시 새긴 책)으로 보인다.","a":"묘법연화경 권4~7","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638876.jpg"},{"q":"조선 후기의 문신이며 대문장가였던 영재 ○○○의 묘소이다. 묘는 단분(單墳)이며 특별한 장식이나 석조물이 없다. ○○○은 어렸을 때부터 강화학파의 학맥을 계승한 이시원으로부터 양명학을 바탕으로 한 충의(忠義)와 문학(文學)을 배웠다. 5살 때 문장을 구사할 만큼 재주가 뛰어나 신동이라는 말을 들었다고 한다. 고종 4년(1866) 15세의 어린 나이로 문과에 급제하였고 고종 11년(1874)에는 사신을 수행하여 기록을 맡았던 서장관에 발탁되어 크게 이름을 떨쳤다.","a":"이건창 묘","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645605.jpg"},{"q":"일제시대 애국지사이자 항일 시인인 일도 오희병(1901∼1946) 선생이 태어난 집으로 그의 할아버지 시동이 고종 1년(1864)에 세웠다. 정침은 전체 ㅁ자형으로 사랑채 앞면과 오른쪽에 마루가 돌출되어 있다. 대문간을 중심으로 왼쪽에 글방이 있고 오른쪽에는 사랑채가 놓여 있다. 대문채는 대문간을 중심으로 외양간과 마구간, 오른쪽에 방과 부엌을 두고 있다.","a":"오일도생가","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662955.jpg"},{"q":"이 건물은 신라 무열왕때 의상조사가 창건하여 웅정암이라 하였으나 임란때 병화로 소실되고 영지대사가 중창하여 ○○○라 함. 그 후 조선 영조 50년(1774) 중수하여 오늘에 이름.","a":"영천 영지사 대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2021101917415200.jpg"},{"q":"○○○○ 서문 ○○○○○은 원래 ○○○○의 서문 인근에 위치한 성남초등학교 교정에 있었는데, 1975년 부산시에서 실시한 ○○○○ 정화사업 때 ○○○○의 서문인 금루관(金壘關)을 복원하면서 2기의 ○○○도 함께 이전하여 복원하였다. 오른쪽 돌기둥에는 \"이곳은 나라의 목에 해당하는 남쪽 국경이다.\"라는 뜻의 \"남요인후(南徼咽喉)\" 글자가 새겨져 있고, 왼쪽 돌기둥에는 \"서문은 나라의 자물쇠와 같다.\"라는 뜻의 \"서문쇄약(西門鎖鑰)\"이라는 글자가 새겨져 있다.","a":"부산진성 서문성곽우주석","c":"시도기념물","nc":"","r":"부산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645025.jpg"},{"q":"영의정 황희·오상덕·황위의 위패를 모시고 있는 서원이다. 방촌 황희(1363∼1452)는 고려 우왕 9년(1383)년에 급제하여 벼슬을 지내다가, 고려가 망하자 은둔생활을 하였다. 그러나 태조 3년(1394)에 이성계의 간청으로 다시 벼슬자리에 올라 18년동안 영의정에 있으면서 선정을 베풀었다. 인품이 원만하고 청렴하여 백성에게 존경을 받았고, 시문에도 뛰어났다. 두암 오상덕은 황희의 매형으로 이색, 정몽주, 이숭인과 교분이 두터웠으며 조선이 서자 절의를 지키기 위해 은둔생활을 하였다. 당촌 황위는 시문이 훌륭하여 이름을 떨쳤고 후학교육에 여생을 마쳤다.","a":"풍계서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661670.jpg"},{"q":"향완은 절에서 마음의 때를 씻어주는 의미를 가진 향을 피우는데 사용한 도구로 향로라고도 부른다. ○○○에 소장된 이 향완은 고려시대의 일반적인 형태인 입 부분에 넓은 테인 전이 달려있고, 나팔 모양의 받침이 있는 향완이다. 높이 28.2㎝, 입 지름 27.4㎝의 크기이며, 높이와 입 지름의 크기가 비슷하여 전체적으로 안정감을 준다. 은실을 이용해 전체 표면을 간략화된 덩굴무늬로 메우고 있다. 몸체의 윗면과 아랫면에도 둔중한 곡선들이 듬성듬성 새겨 있으며, 중간 부분에 2줄의 원을 그리고 안쪽에 범자를, 바깥쪽에는 빗금이 교차되는 거치무늬을 새겼다.","a":"범어사청동은입사향완","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659347.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 전라남도 지방은 전국에서 고인돌이 가장 많이 분포하는 지역으로 지금까지 발견된 것만 해도 약 2만여 기가 넘는다. 완도군에도 많은 고인돌이 분포하고 있는데 청산도에는 23기가 2개의 무리를 지어 분포하고 있다.","a":"읍리지석묘","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662054.jpg"},{"q":"○○○는 1321년 고려 충숙왕대에 당시 합주지주사(陜州知州事)김영돈(金永暾:1285-1348)이 처음 창건하였으며 이 사실을 기문으로 적은 이는 안진(안진:?-1360)이다. 이 누각은 여러 차례에 걸쳐 중건되어 지금에 이르렀다. 대야성(大耶城) 기슭에 위치하여 황강(黃江) 정양호(正陽湖)를 바라볼 수 있게 지어져 오래 전부터 많은 시인·묵객들이 풍류를 즐기는 장소로 되었다. 이황(李滉), 조식(曺植), 송시열(宋時烈) 등과 같은 조선시대 최고 명유의 글이 누각내부 현판에 걸려 있으며, 뒤 암벽에는 ○○○라 새긴 송시열의 글씨가 있다.","a":"합천 함벽루","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663944.jpg"},{"q":"○○○○○는 장흥 부산면 ○○○에서 전승되어온 마을 공동체 의례와 마을 및 ○○○ 관련 기록물로서 조선시대 마을 형성 이후 오늘날까지 계승·유지되어 오고 있다. 특히 ○○○○는 조선시대 후기(1702년께 ○○○ / 1715년 대동계[동계])부터 시작하여 현재까지도 매년 기록하고 있다는 점에서 살아있는 역사 자료이며, 마을공동체 의례의 연혁과 변천을 알 수 있는 희귀 자료이다.","a":"장흥호계리별신제와동계문서","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2020031014145700.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 경상남도 진해시 성내동에 있는 산성으로, 조선 세종 21년(1439)년에 만들어진 것이다. 이곳은 1407년 일본과의 관계유지를 위한 목적으로 항구를 열어 무역을 하던 곳인데, 일본인의 불법이주가 많아지자 이를 막고 읍면을 보호하기 위하여 읍성을 쌓았다. 문종 원년(1451)에는 왜구의 침입을 막기 위해 동·서·북에 수로를 만들어 성 일부를 확장하였다. 중종 5년(1510)에는 삼포왜란으로 일시 함락되기도 하였고, 임진왜란 때에는 고시니 유끼나가가 이곳에 머물기도 했다.","a":"창원 웅천읍성","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654774.jpg"},{"q":"괘불(掛佛)이란 옥외에서 법회를 할때 밖에 내어 걸고 의식을 행하는 걸개 그림 형태의 불화를 말한다. ○○○○○은 지장보살을 중심으로 좌우에 도명존자, 무독귀왕, 시왕들까지 묘사한 ○○○○도를 괘불 형식으로 그린 그림으로 현재까지 발견된 우리나라 유일의 ○○○○○이다. 화기에 의하면 1930년 고산당(古山堂) 축연(竺演)에 의해 제작되었다.","a":"안양암 지장시왕괘불도","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313464600.jpg"},{"q":"이 보살상은 조선후기 불교조각의 보편적인 특성을 띠면서도 얼굴 등에서는 그 개성이 드러난다. 다소 부자연스러운 조형성은 재료에서 오는 기술적, 시대적인 한계를 드러내고 있음은 물론 세부적으로 옷주름이 더욱 딱딱하고 형식화되는 18세기전반 이후에 제작된 불상으로 추정된다. 현재 조선후기 석조 불상들의 조사가 활발히 진행되고 있는 가운데 18세기는 17세기의 전통을 계승하고 19세기와 근대를 있는 시대로서 중요하며 이와 같은 불상을 통해 시대적인 변화와 양식적인 변화의 추이를 유추해 볼 수 있을 것이다.","a":"밀양 표충사 석조보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666344.jpg"},{"q":"경주 ○○○에 전하는 나무 비석 8점, 금구 1점, 석조 치미 1점의 유물들이다. 나무 비석은 18∼19세기 절의 수리 상황을 기록한 자료로, 돌 비석이나 철 비석에 비해 흔하지 않은 예로 그 가치가 높다. 금구는 금고, 반자라고도 하며 절에서 대중을 불러모으거나, 급한 일을 알릴 때 사용하는 일종의 타악기이다. ○○○ 금구는 직경 70㎝, 두께 11.5㎝로 청동으로 제작되었으며 조선 경종 2년(1722)에 만들었음을 알 수 있는 글이 새겨 있다. 치미란 건물의 용마루 양끝에 부착한 대형 장식 기와를 말하는 것으로, 주로 점토로 만들어졌다.","a":"경주기림사소장유물","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663095.jpg"},{"q":"전북특별자치도 익산시 해발 162m의 낭산 정상에 있는 산성이다. 구성, 마한성 등으로도 불리는데 마한성이라고 하는 것은 고조선의 기준왕이 내려와서 쌓았다는 전설에 의해서 불려지는 것이다. 그러나 이 지역에서 지금까지 마한시대와 관련된 유물들이 밝혀지지 않고 있어서 마한시대에 만들었다는 근거는 없다. 다만 성 안에서 백제 이래의 유물들이 발견되어 이 시기에 만들어진 것으로 판단되고, 후세에 와서 익산 일대가 마한의 옛 도읍지였다는 점에서 마한성이라 부르게 된 것으로 추정된다. 이 산성은 정상을 둘러싼 형태로 북쪽은 거의 정상에, 남쪽은 일부 골짜기를 감싸고 있다.","a":"익산낭산산성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653333.jpg"},{"q":"조선 중기 문신인 노수신(1515∼1590) 선생의 덕을 추모하기 위해 세운 건물이다. 그는 중종 38년(1543) 문과를 급제하고 성균관의 전적(典籍)을 거쳐 사서(司書) 등의 벼슬을 하였으나 을사사화 때 파직되어 19년간 섬(진도)에서 귀향살이를 하였다. 그곳에 있으면서 이황 등과 서신으로 학문을 토론하고 1567년 『숙흥야매잠』, 『대학장구』등의 주해를 달아 사림 사이에서 명성을 쌓았다. 선조가 즉위하면서 기용되어 벼슬이 영의정까지 올랐다. 그는 시, 문, 서예에 뛰어났으며 양명학을 깊이 공부하고 승려인 휴정과도 교분을 나눴다.","a":"옥연사","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662769.jpg"},{"q":"○○○○은 고려시대 흥복사, 조선시대 원각사가 있던 자리였으며, 대한제국 시대에 문을 세우고 서울 최초의 도시공원인 파고다 공원으로 정비하게 되었다. <○○○○○>은 1910~1913년에 건립된 것으로 추정되며, 1967년 공원 정비 당시 서울대학교 법대 ○○으로 이전(1969 실시)되어 현재 서울대학교 사범대학 부설초등학교의 ○○으로 이용되고 있다.","a":"구 탑골공원 정문","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017021613283900.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398)에 처음 지었으나, 임진왜란 때 불타 없어지자 선조 33년(1600)에 다시 지었다. 정조 9년(1785)에 마현동으로 옮겨 지었고, 1931년 군수 김영수가 읍성내에 있던 구객관을 수리하고 위패를 모셔 지금의 향교로 전해오고 있다. 임진왜란이 일어났을 때 서방경·서극인·이대임·이눌 등이 향교에 모시고 있던 위패를 용암석굴에 옮겨 놓아 위패만은 무사할 수 있었다고 전한다.","a":"장기향교","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663150.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○ 비래골 마을회관 앞 논에 ○○○ 2기가 있고, 맞은편 구릉 정상부에 1기의 ○○○이 있다.","a":"비래동고인돌","c":"시도기념물","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645829.jpg"},{"q":"○○○ 큰법당에 봉안된 삼장탱(三臧幀)이다. 상하 2단으로 크게 구분하고 상단에는 천장보살을 중심으로 좌우에 보살을 배치하고 그 사이에 권속들로 가득 메우고 있다. 하단에는 이들 보살의 협시와 권속들로 채워져 있다. 이들 삼장보살은 하나의 방형 수미단 위에 중앙 천장보살의 신광만 바탕을 금니로 처리하였을 뿐 나머지는 모두 이중륜광의 두 ·신광을 갖추고 결가부좌 하였다. 채색은 주로 적색과 청색, 백색, 황색을 주로 사용하였으며 부분적으로 금니를 사용하였는데, 천장 ·지지·지장보살상의 몸색은 황색을 사용하였고 나머지 인물들은 백색으로 처리하였다.","a":"강화 청련사 삼장보살도","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637124.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 세워진 시기는 알 수 없으나 조선 영조 2년(1726)에 통영부에서 이곳으로 옮겨 여러 차례 보수했다. 건물의 배치는 공부하는 곳인 명륜당과 동·서재가 앞에 있고, 여러 성현들을 모신 대성전과 동·서무가 뒤에 있는 전학후묘의 형태이다. 또한 출입문이자 휴식공간이었던 풍화루와 명륜당, 사당의 출입문인 내삼문, 대성전이 일직선으로 서 있다. 그러나 명륜당을 중심으로 서 있는 동·서재가 대칭이 아닌 비대칭으로 서 있어 전형적인 향교배치 형식에서 벗어난다.","a":"고성향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641901.jpg"},{"q":"조선 고종 20년(1883) ○○항구의 개방과 함께 만들어 놓은 우물로, 오랫동안 이곳 주민의 생활용수와 식수원이 되어 왔으나, 수도의 보급으로 지금은 사용되지 않아 우물의 형태만 그대로 남아 있다. 우물안은 자연석과 다듬은 돌로 둥글게 쌓아 원기둥을 이루고, 땅위로 보이는 윗부분은 둥근 형태의 콘크리트로 되어있다. 1967년 우물을 보호하기 위해 기와지붕을 올린 6각 정자를 세워 두었는데, 유명 서예가인 동정 박세림 선생이 썼다는 현판이 이 곳에 걸려 있다.","a":"인천 용동 큰우물","c":"시도민속문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2016010417105200.JPG"},{"q":"이 불화는 현재 ○○○ 대웅전에 후불탱화로 안치되어 있는데, 그 앞에 모셔져 있는 ○○○상이 17, 8세기경의 작품인 것을 볼 때 1892년 대웅전의 불화를 제작하면서 불상과 같은 형식의 ○○○화를 그린 것으로 추정된다. 세로 319.7cm, 가로 291.8cm의 대규모 면본 채색화로 현 대웅전의 후불벽보다는 폭이 좁지만 1892년 당시 대웅전의 후불벽 규모에 맞춰 제작한 것으로 보인다.","a":"봉은사 삼세불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636422.jpg"},{"q":"향교는 고려와 조선시대에 유학을 가르치기 위해 지방에 설립한 국가교육기관이다. 공자 등 성현의 위패를 모시는 제사 공간인 대성전과 명륜당이 중심 건물이다. 태조 7년(1397)에 세운 ○○○○는 임진왜란(1592) 때 불에 타 없어진 것을 광해군 5년(1613)에 광양현감과 지방 유림이 힘을 모아 대성전을 지으면서 점차적으로 건물을 지었다. 그 뒤 여러 차례 수리가 있었으나, 한국전쟁 때 완전히 없어진 것을 1966년에 출입문인 풍화루를 돌기둥으로 대신하여 세운 것을 시작으로 건물을 다시 지었다. 현재 남아있는 건물은 대성전·명륜당·풍화루·동재·서재 등이 있다.","a":"광양향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639968.jpg"},{"q":"○○○○는 훌륭한 유학자들의 위패를 모시고 제사지내며 지방 백성들의 교육과 교화를 담당하기 위해 지은 국립지방교육기관이다. 언제 지었는지 정확한 연대는 알 수 없으나, 고려 성종 6년(987) 지금의 의곡사 계곡에 향학당으로 처음 세워진 후 조선 태조 7년(1398) 문묘를 지으면서 향교로서의 모습을 갖추게 되었다. 명종 13년(1558) 현 위치로 옮겨졌으며, 교관과 교수 등은 성균관으로부터 직접 파견되었다. 임진왜란(1592) 때 불에 타 없어졌다가 여러 차례의 공사를 거치면서 원래의 모습을 되찾았다.","a":"진주향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641453.jpg"},{"q":"의성 김씨 문중의 재실로 사용하던 곳이며 서당 구실도 하여 백운서당이라고도 한다. 조선 정조 2년(1778)에 처음 세웠고 1915년에 다시 고쳤다. 건물은 중앙에 마루를 두고 양쪽에 온돌방을 두었다. 재실 앞에는 옛 모습을 간직한 대문이 있고 주위는 전통 기법으로 담을 쌓았다.","a":"괴산 봉서재","c":"문화유산자료","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660750.jpg"},{"q":"이 불상은 높이 29.2cm의 작은 불상으로 개금 원문(改金 願文)에 의하여 아미타불상으로 밝혀진 불상이다. 갸름하게 보이는 얼굴, 약간 긴 상체, 짧은 하체의 결가부좌 자세 등 18세기 초의 목불상의 특징을 잘 보여주고 있다. 경계가 불분명한 높은 육계(肉髻) 정상에는 둥글고 큼직한 정상계주(頂上髻珠)와 머리에 비해서 훨씬 큼직한 반달형 중앙계주 등이 특징적으로 나타나 있다. 나발(螺髮)은 다소 굵고 큰 모양으로 <정수사 나한전 불상>의 것과 유사하다.","a":"정각사 목 아미타불좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636408.jpg"},{"q":"조선 전기 문신이자 학자인 김숙자(1389∼1456) 선생이 터를 잡고 그의 아들인 김종직(1431∼1492) 선생이 평생을 보낸 집터이다. 김숙자 선생은 12세 때부터 길재에게 글을 배우고 세종 1년(1419) 문과에 급제한 뒤 현감 등의 벼슬을 지냈다. 16세기 성리학을 보급하고 사림이 확립한 도통(道統)의 계보에서 길재의 학문을 그의 아들인 김종직으로 하여금 잇게 하였으며, 김종직은 현재 성리학의 거두(巨頭)로 인정받고 있다. 이 건물은 여러 차례 전쟁을 겪으면서 파손된 것을 순조 10년(1810) 사림들과 그의 후손들이 다시 고쳐 세운 것이다.","a":"밀양 추원재","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664212.jpg"},{"q":"우리나라 최대의 산성인 ○○○○을 보수한 뒤 산성의 면모를 새롭게 한 사실을 기념하기 위해 세운 비이다. 현재 금정초등학교에서 서쪽으로 약 200m지점의 주택지 가운데 놓여있는 큰 바위 위에 자리하고 있다. ○○○○은『증보문헌비고』에 의하면 숙종 29년(1703) 감사 조태동이 동래부사 박태항으로 하여금 쌓게 한 것이다. 그러나 그 이전인 현종 8년(1667) 통제사 이지형이 왕에게 ○○○○을 보수할 것을 건의하는 기록이 있어 이보다 더 오래된 시기에 제작된 것으로 보인다.","a":"금정산성 부설비","c":"시도기념물","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645006.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태조 7년(1398)에 처음 지었으며, 그 뒤 여러 차례 보수하여 지금의 모습을 갖추었다. 지금 남아 있는 건물로는 제사지내는 공간으로 대성전을 비롯하여 동무·서무가 있고, 교육 공간으로 강당인 명륜당과 학생들의 기숙사였던 동재·서재가 있다. 또한 출입구로 홍살문과 내삼문·외삼문이 남아 있다. 대성전 안쪽에는 공자를 중심으로 안자·증자·자사·맹자 등 5성의 위패를 모식도 있고, 동무와 서무에는 중국과 우리나라 성현들의 위패를 모시고 있다.","a":"연산향교","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652920.jpg"},{"q":"○○○○○의 ○○○이다. 초명은 哲會, 호는 島蓭, 본관은 平山으로 문경군 가은면 민지리 도내동에서 출생하여 항일의병활동을 하였고 그 공적으로 건국훈장 국민장에 서훈되었다. 행장에 따르면 1907년 의병을 일으켜 문경, 단양, 평해, 영양 등 경상도로부터 울진, 영월, 산동, 제천, 원주, 홍천, 춘천, 화천, 철원, 신계, 곡산 등 강원도지역에서 의병전공을 세웠다. 그러나 일본군의 대대적 소탕작전으로 의병활동은 위축되었고 1908년 경기도 영평전투에서 왼다리에 총상을 입고 체포되어 1919년 2월까지 감금되었다.","a":"의병장 신태식 생가지","c":"시도기념물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654667.jpg"},{"q":"상남 상업지역 주변에 위치한 선사시대인 청동기 시대의 무덤으로, 돌멘 또는 고인돌이라고 불려지고 있다. ○○ 상남 ○○○는 국립○○문화유산연구소에 의하여 1997년 12월 발굴 조사되었다. 내부에 시신을 안치하기 위해 석관을 만들고 그 위에 많은 할석과 대형 개석을 덮은 후 다시 굄돌과 덮개돌을 올린 독특한 구조를 하고 있다. 이 ○○○는 인근에서 발견된 ○○ 덕천리○○○와 함께 우리나라의 대표적인 남방식○○○로 알려져 있다.","a":"창원 상남지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656848.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 남산 ○○○는 조선 태조 3년(1394)에 도읍을 한양으로 옮긴 뒤 설치하여, 갑오경장 다음해까지 약 500년간 사용되어 왔다. 남산의 옛 이름을 따서 ○○○○○라 하기도 하고, 서울에 있다하여 경○○○라 부르기도 하였다. 평상시에는 1개, 적이 나타나면 2개, 적이 경계에 접근하면 3개, 경계를 침범하면 4개, 경계에서 아군과 전투를 벌이면 5개의 불을 올리도록 하였다.","a":"목멱산봉수대터","c":"시도기념물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644792.jpg"},{"q":"교우 ○○○선생은 당대의 거창을 대표한 유학자로 평생동안 성리학에 몰두하였고 동천재에서 80여명의 문하생을 배출하였음. 선생의 문집책판은 1906년 선생이 작고한 이듬해인 1907년에 장사를 끝내고 유고를 문인인 이승래, 이영훈, 박종권 등이 필사하여 1908년에 곽종석 선생이 원집과 속집으로 나누었고 이어 문인 윤희도, 최효근, 윤정하가 정서를 하고 정재희, 김재명선생이 교정을 보아 완성함. 문집의 내용은 목록, 시, 소서, 서기발, 잡저 등 10권으로 구성되어 있으며, 1993년도에 장판각을 만들어 보존하고 있음.","a":"윤주하 교우문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642082.jpg"},{"q":"2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 석탑이다. 아래층 기단은 밑부분이 땅 속에 묻혀있어 자세한 구조를 알 수 없고, 탑신은 몸돌 모서리마다 기둥 모양을 새겨 놓았다. 3층에는 머리장식의 네모난 받침돌이 몸돌 대신 끼워져 있고, 각 층의 지붕돌 밑면에는 4단의 받침을 두었다. 꼭대기에는 복발(覆鉢:엎어놓은 그릇모양의 장식)이 놓여 머리장식을 하고 있다. 소박한 모습의 탑으로, 통일신라시대에 세운 것으로 추정된다. 1999년 석탑을 잘 보존하기 위해 해체 복원하였다.","a":"영양신구동삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662532.jpg"},{"q":"1901년 프랑스인 에밀리온따께(한국이름: 엄택기)신부가 지금의 ○○터에 초가삼간으로 임시 ○○을 세워 선교활동을 하였는데, 바로 그곳에 유리오베르문(한국이름: 목세영) 신부가 1928년에 지은 것이다. 로마네스크식과 르네상스식의 건축양식을 절충하여 지은 이 ○○은 길이 21.45m, 폭 8.76m 규모로 경남지역 천주교 ○○ 가운데 가장 오래되고 그 원래 모습이 잘 남아 있어 한국 근대건축 변천사 연구의 중요한 자료이다.","a":"창원 성요셉 성당","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664646.jpg"},{"q":"○○○○○은 ○○○ 명부전 옆에 건립되어 있는 정 측면 1칸의 목조와즙 건물로 노후로 인하여 최근에 보수가 이루어졌으나 원형을 비교적 잘 유지하고 있다. 기단은 장대석을 활용하여 넓게 마련하였다. 초석은 사각형으로 치석하여 그 위에 사각형 기둥을 올렸으며, 창호 앞에는 디딤돌을 마련하여 높은 문지방을 쉽게 드나들도록 하였다. 창호는 사분합문(四分閤門)이며, 지붕은 방풍널이 시설된 맞배지붕이다. 정면 처마부는 원형 서까래와 사각형 부연(附椽)을 올린 겹처마이고, 후면 처마부는 홑처마로 시공되었다. 건물 양측면에는 화방벽(火防壁)이 설치되어 있다.","a":"진관사독성전","c":"문화유산자료","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314543800.jpg"},{"q":"○○시 원평동에 있는 ○○○의 대웅전에 모셔진 석가여래좌상이다. ○○○는 1952년 5월부터 1954년 4월까지 주지 철우선사(鐵牛禪師)에 의하여 창건되었으며, 철우선사 입적 후에는 정우(正愚)스님이 주지로 있다. 지금은 대한불교 조계종 직지사 말사로 1,500여명의 신도들이 소속되어 있다. 경내에는 대웅전, 심우당, 채월당, 종각, 철우선사 부도탑 등이 있다. 이 불상은 가벼운 납석제를 조각하여 조성한 불상으로 몸체에 비해 머리가 큰 형태이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았는데 위쪽으로 갈수록 커지고, 목에는 1줄의 선이 있다.","a":"구미 금강사 석조석가여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641082.jpg"},{"q":"임진왜란 때 공신인 전봉성(1561∼1597)을 추모하기 위해 세운 사당으로 천안 전씨인 전봉진과 전봉대를 함께 모시고 있다. 그는 임진왜란 때 의병대장인 고경명을 따라 금산전투에 참가했으며 이후 그 공로를 인정받아 함평군수에 제수되었다. 정유재란 때에는 유장춘 등과 힘을 합쳐 율치전투에서 싸우기도 하였으나 아쉽게 선조 30년(1597) 현석포 전투에서 전사하였다. 이 건물은 숙종 32년(1706)에 보수하였고, 영조 52년(1776) 전봉진, 헌종 2년(1836) 전봉대의 위패를 추가로 모셨다.","a":"영암장동사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654268.jpg"},{"q":"이 집은 조선후기에 학문과 도덕 그리고 효행으로 이름 높았던 강서린(姜瑞麟)의 행적을 본받고 기리기 위해 세운 것이다. 조선 영조 8년(1723) 전라 감사 이수항의 건의에 따라, 나라에서 ｢○○○｣이란 이름을 내려주고 비용을 들여 건립하였다. 강서린의 아버지 강해우(姜海遇) 역시 학덕이 높고 효행이 지극하여, 전주시 효자동에 위치한 황강서원에 그의 위패를 모셨다. ｢지행(趾行)｣은 조상의 어진 발자취를 길이 길이 이어가도록 하라는 뜻이다. 비문은 높은 벼슬을 지낸 이기경(李基敬)이 지었고, 현판은 당대의 명필 이익회(李翊會)가 썼다.","a":"지행당","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653309.jpg"},{"q":"이 도면은 1930년경 한국인 건축가 김순하가 설계한 평면도, 단면도, 입면도 등으로 현대건축 도면과 비교해도 손색이 없는 것이다. 일제시대에 한국인 건축가가 설계한 그들의 작품이 실현된 것은 1920년대 후반부터였다. 이 도면은 일제시대 지방 최초의 ○○○면일 뿐만 아니라 한국의 전통건축을 조영할 때 우리 선조들이 ○○○면을 사용했는지 확실하지 않은 점을 고려하면 의미가 대단히 큰 작품이라 평가된다.","a":"전라남도회의실신축설계도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637164.jpg"},{"q":"○○○에 보존되어 있는 그림으로, 석가불의 부탁을 받고 석가불이 입멸(入滅)한 후부터 미륵불이 출현할 때까지 육도(六道)의 중생을 교화한다는 지장보살과 심판관인 시왕(十王)을 함께 그린 탱화이다. 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 채색으로 그려진 이 시왕탱은 중앙의 지장보살좌상을 중심으로 그 좌우측에 머리광배를 갖춘 도명존자와 무독귀왕을 비롯해 시왕·판관·동자·옥졸 등이 배치되어 있다. 화면의 아래쪽 부분 중앙에 있는 기록에 의하면 이 ○○○○○은 조선 순조 12년(1812)에 조성된 것임을 알 수 있다.","a":"양산 통도사 가경17년명 지장시왕탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642346.jpg"},{"q":"조선 초기의 문신이며 대학자였던 신재(愼齋) ○○○ 선생의 묘소이다. 어려서부터 효성이 지극하였으며 학문에도 열성적이었다. 중종 17년(1522) 문과에 급제한 후 여러 관직을 두루 거쳐 중종 36년(1541)에 풍기 군수가 되었다. 중종 38년(1543)에는 풍기 지방에 우리나라 최초의 서원인 백운동서원(뒤의 소수서원)을 세웠다. 명종 6년(1551)에는 황해도 관찰사가 되어 해주에 수양서원을 창설하여 최충을 모시기도 하였다. 죽은 뒤 선생의 유언에 따라 고향에 장사 지내고 조정에서는 예조판서의 벼슬을 내렸다.","a":"함안 주세붕 묘역","c":"시도기념물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654875.jpg"},{"q":"1727년(영조 3) 제작된 ○○○○로 강원특별자치도 내의 탱화로서는 보기드문 18세기 전반의 작품이며, 보존상태가 양호할 뿐만 아니라 단정하고 섬세한 얼굴표현, 유려한 필선과 정교한 문양 등 뛰어난 작품성을 보이고 있다. ○○○○는 천장보살(天藏菩薩)ㆍ지지보살(地持菩薩)ㆍ지장보살(地藏菩薩)과 그 권속을 그린 불화로, 그 도상의 유래가 정확히 밝혀지지 않았으나 지장보살 신앙이 심화되고 확대되어 형성된 것으로 보이며 우리나라에서만 형성되어 발전한 독특한 도상으로 알려져 있다.","a":"구룡사삼장탱화및복장유물","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638245.jpg"},{"q":"○○○에 있는 옛집으로, 지금의 살림채는 ㄷ자형이나 앞쪽에 건물의 흔적이 있는 것으로 보아 원래는 바깥채가 있어 전체적으로 ㅁ자형의 배치를 한 것으로 보인다. 대청을 중심으로 양쪽에 안방과 건넌방을 두었고, 건넌방 앞에 부엌과 상방을 덧붙였다. 일반적으로 안방과 웃방은 장지문을 설치해 터놓을 수 있도록 하지만, 이 집은 그 사이를 벽으로 막았는데 이것은 오래된 집에서만 볼 수 있는 방식이다. 대청과 부엌은 집의 규모에 비해 넓은 편이다. 상방 앞쪽에는 툇마루를 놓아 손님을 접대하는 공간으로 이용하였다.","a":"제천 도화리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638512.jpg"},{"q":"인진왜란 때 큰 공을 세운 이순신(1545∼1598) 장군과 그의 휘하에서 활약한 김억추(1548∼1618) 장군의 충절을 기리기 위해 세운 사당이다. 이순신은 임진왜란과 정유재란 때의 성웅(聖雄)으로 전쟁을 승리로 이끈 분이다. 김억추 장군은 선조 11년(1578) 무과에 급제하고 임진왜란 때 전라도 방어사로 진주에서 열린 이순신의 작전회의에 참여하여 명량해전을 대승으로 이끄는데 커다란 공을 세워 이후에 경상좌병사, 제주목사가 되었다. 사당은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 대 여덟 팔(八)자 모양의 팔작지붕으로 꾸몄다.","a":"강진금강사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654241.jpg"},{"q":"조선 인조 14년(1636) 병자호란이 억울하게 끝나자 도은 강각(姜恪) 선생이 형인 강흡(姜洽) 선생과 함께 법전 양촌에 은거하며 절개를 지키던 곳으로 일명 ‘도은구택’이라고도 한다. 영조 46년(1798)에 수리하였으며, 60여 년 전에 다시 고쳤다. 사랑채와 안채가 튼 ㅁ자형으로 배치되어 있으며, 떨어져 나간 부분이 많다. ㅁ자형의 살림집에 안채와 사랑채가 있고, 그 왼쪽에 재실과 사당이 있다. 안채는 가장 오래된 건물로 사랑채보다 높은 곳에 있다.","a":"봉화법전강씨종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658592.jpg"},{"q":"충열공 이대원(1566∼1587)과 충장공 정운(1543∼1592)을 모신 사당이다. 이대원은 선조 20년(1587) 녹도만호가 되어 남해안에 출몰하는 왜구를 대파하였고, 다시 흥양에 왜구가 침입하자 맞써 싸우다가 손죽도 해상에서 순절하였다. 이에 선조는 사당을 지어 모시게 했는데 이것이 쌍충사의 전신이다. 정운은 선조 24년(1591) 녹도만호로 부임하여 임진왜란이 일어나자 이순신 장군과 함께 목포·당포·한산해전 등에서 용감히 싸우다 부산 몰운대에서 순절하였다. 선조 25년(1592) 이순신 장군의 청으로 이대원과 함께 사당에 모시게 되었다.","a":"고흥쌍충사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654288.jpg"},{"q":"○○○○은 고창~아산간 지방도 확포장공사 구간내에서 2002년 5월부터 7월까지 매장유산조사기관에서 발굴조사하였다. 원삼국시대 및 역사시대에 해당하는 3~5세기경에 축조된 주구묘 13기와 주구를 갖추고 있지 않은 단독묘 4기 등이 조사되었다. 유물은 이중구연호․발형토기 등의 토기류, 환두도․철부․철모․철겸 등 다양한 철기, 유리옥․자마노옥 등의 장신구 등 모두 189점이 출토되었다. ○○○○은 삼국시대 마한과 관련된 분묘로 매장주체부의 축조나 매장된 옹관의 양상, 출토유물의 다양성 등 마한(馬韓) 제소국(諸小國)과의 관계를 살필 수 있는 중요한 유적이다.","a":"고창만동유적","c":"시도기념물","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653879.jpg"},{"q":"충청북도 ○○시 상당구 ○○○에 있는 바위면에 새긴 마애불이다. 머리에는 마치 모자를 쓴 듯하며, 머리 뒤에는 동그란 머리광배가 표현되어 있다. 신체는 균형이 잘 잡혀 있으며, 자연스럽게 흐르는 얇은 선의 옷주름 표현이 돋보인다. 왼손 검지 손가락을 오른손으로 잡을 듯한 모습을 하고 있다. 이런 특징적인 손모양은 동화사 비로암석조비로자나불좌상(보물)이나 도피안사 철조비로자나불좌상(국보)과 비교된다. 불신의 각 부분을 정교하지 않고 간략하게 처리하고 있는 조형감이나 정제되지 않고 거친 조각수법을 고려할 때, ○○○○○은 고려시대에 제작되었을 것으로 여겨진다.","a":"청주 정하동 마애비로자나불좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638572.jpg"},{"q":"이 영정은 ○○○선사의 좌안7분면 바닥가부좌상이다. 화면은 녹색바탕에 운보문이 그려진 상단벽면과 돗자리의 이단구도로 이루어져 있다. 선사는 돗자리위에 방석을 깔고 왼손엔 목리문이 그려진 주장자를 쥐고, 오른손은 염주를 쥐고 있다. 장삼과 가사의 의습선 주변으로는 짙은 농담을 주어 음영을 강하게 표현하고 있다. 화면 향좌측에 ‘○○○대선사진(巘菴堂大禪師眞)’ 의 화제가 있으며, 화면크기는 가로 83.1cm, 세로 113.1cm이다.","a":"헌암당 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643028.JPG"},{"q":"구암(久菴) ○○○은 본관이 청주(淸州)이며, 실증적이며 고증학적인 방법으로 조선의 역사·지리를 연구해 『동국지리지(東國地理志)』, 『기전고(箕田考)』 등을 저술했다. ‘○○○ 묘’는 부인 함창 김씨(咸昌金氏) 합장(合葬) 단분(單墳)으로 조성되었다. 봉분 앞에 혼유석, 묘표, 석상이 놓여 있으며, 그 앞으로 망주석과 문인석이 건립되어 있다. 묘표는 원수방부(圓首方趺; 둥근 머릿돌과 사각 받침돌의 비석 형태) 형태다. 묘역 언덕 아래에 건립된 ‘○○○○○’는 1644년에 건립되었으며, 이수귀부(螭首龜趺; 용이 조각된 비석 머리와 거북 형태의 비석 받침) 형태이다.","a":"구암한백겸묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646905.jpg"},{"q":"이 신도비는 조선 중기의 문신인 행당 윤복(1512∼1577) 선생을 기리기 위해 세운 것이다. 윤복은 전남 해남에서 윤효정의 넷째 아들로 태어났으며, 조선 중종 33년(1538) 문과에 급제해 성균관 학유, 전적, 예조정랑, 사헌부 장령, 승정원 좌부승지 등을 지냈고 외직으로는 부안현감, 광주목사, 안동대도호부사 등을 지냈다. 그는 학문이 깊었고 곧은 성품으로 선정을 베풀었으며, 호남사림의 한 축을 형성한 인물로서 관인의 생활사 자료를 기록 『전라도도사시일록(全羅道都事時日錄)』,『은대일록(銀臺日錄)』으로 남기기도 하였다.","a":"강진 윤복신도비와 영모당","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654361.jpg"},{"q":"이곳은 밀성부원군(密城府院君) 문정공(文貞公) 박씨(朴氏)와 그의 부인인 정부인(貞夫人) 초계정씨(草溪鄭氏)의 묘가 있는 곳이다. 부부의 묘임에도 불구하고 앞에는 문정공 박씨묘가, 뒤에는 정부인 초계정씨의 묘가 전후 일렬로 배치되어 있다. 2기 모두 방형분이다. 앞쪽에 있는 문정공의 묘는 420×320㎝이며, 봉분의 높이는 150㎝가량이다. 정면에는 3매의 면석과 갑석이, 측면에는 각각 4매의 면석과 갑석이 돌려져 있다. 봉토나 면석 등이 일부 흐트러져 있으나 전체적으로는 원형이 거의 그대로 남아 있다.","a":"창녕 박부 묘","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657177.jpg"},{"q":"○○향교 서쪽 서촌에 자리잡은 옛집이다. 조선 고종 24년(1887)에 지은 집으로 안채와 사랑채, 곳간채, 문간채 등으로 구성되어 있다. 안채는 앞면 7칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞뒤로 퇴칸이 있고 내부는 많이 개조되어 있는 상태이다. 사랑채는 앞면 4칸·옆면 1칸 규모로 지붕은 팔작지붕이다. 뒤쪽에 부분적으로 퇴칸이 있으나 후대에 사랑방 옆면 부엌으로 확장하였고, 지붕을 덧달았다. 중사랑채는 앞면4칸·옆면 1칸 규모이며, 지붕은 옆면이 사람 인(人)자 모양의 맞배지붕이다.","a":"밀양 교동 손병준 고가","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664277.jpg"},{"q":"부여시의 외곽지역인 저동마을의 북쪽계곡 늦은목골의 끝이 산기슭과 만나는 지점에 분포하고 있는 백제 때의 무덤들이다. 조사된 무덤은 총 15기인데, 무덤의 형태는 앞트기식 돌방무덤(횡구식석실묘)이 대부분이며, 이보다 큰 무덤방을 가진 굴식돌방무덤(횡혈식석실묘)도 2기 있다. 거의 대부분이 자연상태의 깬돌을 이용하여 축조하였으며, 그 규모는 비교적 작다. 세발토기, 아가리가 곧추선 목항아리, 병, 손잡이가 달린 토기와 관에 쓴 못이 출토되었으며, 이들을 근거로 무덤이 6세기 후반에서 7세기초인 사비시대(538∼660)에 형성되었음을 알 수 있다.","a":"부여지선리고분군","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652831.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 묘 남동쪽에 세워두는 것으로, 이 비는 조선 연산군 때의 문신인 ○○○ 선생의 업적을 기리고 있다. ○○○은 23세에 문과에 급제하여 벼슬길에 올랐다. 세조 13년(1467) 이시애 난이 일어났을 때 난을 평정한 공을 세워 이조정랑에 오르고 다시 춘추관 편수관이 되어『세종실록』편찬에 참여하였다. 성종 12년(1481)에는 명나라에 사신으로 다녀온 후 호조판서에 올랐으나, 연산군 4년(1498) 무오사화 때 왕에게 잘못된 정치를 고치도록 간언하다 낮은 벼슬로 좌천되었다.","a":"홍귀달선생신도비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640479.jpg"},{"q":"○○○○은 신당마을 뒷산의 낮은 구릉지대에 있는 산성으로, 구릉지대의 꼭대기를 빙둘러 쌓았다. 붕괴된 부분이 많지만 전체적인 형태는 남아있다. 성벽의 아랫부분은 돌과 흙을 섞어 쌓은 혼축성이나, 경사가 심한 곳의 아랫부분은 무너지는 것을 막기 위하여 자연석 혹은 다듬은 화강암으로 쌓았다. 이 지역 주민들이 ○○○○을 목마성이라 부르는 것으로 보아, 한 때 말을 키운 듯하나 기록이 없어 확인할 수 없다. 다만 계성면이 옛 현(縣)의 소재지이므로 그럴 가능성을 뒷받침 해줄 따름이다. 성이 만들어진 정확한 연대는 알 수 없다.","a":"창녕 신당산성","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664013.jpg"},{"q":"보광전 내 후불도로 봉안된 ○○○○○는 1850년에 조성된 것으로 특이하게 검은바탕에 금은니로 그린 것이다. 달을 배경으로 중앙에 원형의 두광 안에 관음보살은 기암괴석 위에 유희자 자세로 앉아있고 좌우로 정병과 버드나무, 대나무가 묘사되었는데, 이러한 형식은 고려후기의 ○○○○○의형식에서 빌려온 것이다. 하단에는 여의주를 든 용왕과 선재동자(善財童子), 홀을 들고 원유관을 쓴 제왕이 있고, 하늘과 물을 경계짓는 곳에 중단에는 구름을 수평으로 구획하고 사천왕상을 배치하였다.","a":"현등사수월관음도","c":"시도유형문화유산","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2236113.jpg"},{"q":"안채는 정면 6칸, 측면 2칸으로 전·후에 퇴를 두었으며 5량 구조로 홑처마에 팔작지붕을 얹었다. 안채 정면을 6칸으로 구성한 것은 민가에서 보기 드문 경우로 전면 반 칸을 모두 툇간으로 구성하고 방 부분은 반 칸의 후퇴까지 공간을 확장하였다. 기단은 방형의 다듬은 돌을 쌓아 조성하였고 그 위에 대강 다듬은 돌을 초석으로 놓고 두리기둥을 전면에 사용하고 나머지 기둥들은 방주를 세웠다. 안채와 사랑채 모두 규모가 크며 가구의 장식이 잘 되어 있어 조선 후기 지주계층의 주거연구를 위한 학술적 가치가 충분하며 보존상태 또한 양호하다.","a":"진주 은헌고택","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665109.jpg"},{"q":"패총(貝塚)이란 수렵·어로·채집에 의하여 살아온 옛 사람들이 조개를 먹은 뒤 버린 조개껍데기와 생활쓰레기가 함께 쌓여 이루어진 유적으로 조개더미라고도 한다. ○○○○○은 변산 해수욕장에서 북쪽으로 약 1㎞ 떨어진 합구미 마을 동쪽 산 밑 밭에 있다. 바닷가에 접한 밭이 파도에 깎여 낭떠러지를 이루자 지층이 드러나 1947년 발견되었다. 규모는 남북 약 14m, 동서 약 10m이며, 130㎝ 깊이의 암반에 이르기까지 연속적으로 층위가 쌓여있다.","a":"대항리패총","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653493.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓는 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. 제주대학교 사범대학 부속고등학교 운동장 남쪽에 있는데, 고인돌의 남서쪽을 제외한 주위가 흙과 잡석으로 묻혀 있다. 형태는 바둑판식이나 덮개돌 밑에 여러 매의 넓고 납작한 돌을 둘러 돌방을 만들어서 개석식으로 재분류된다.","a":"용담지석묘1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657652.jpg"},{"q":"경상남도 ○○시에 있는 ○○○은 조선 연산군 6년(1500)에 쌓은 성으로, 둘레는 1172m, 높이 2.61m, 폭 5m정도이고 북쪽과 서쪽이 양호한 상태이다. 성의 형식은 인근의 사등성이나 고현성과 같이 큰돌을 밑에 쌓고 작은돌을 그 위에 올려 쌓았다. 성 안은 대부분 민가가 들어선 마을이고 성 밖은 논으로 사용되고 있으며, 조선 초기 이후의 성의 형태를 살피는데 중요한 자료가 된다.","a":"거제 오량성","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655502.jpg"},{"q":"이 ○○○는 ○○○○○의 운영 실상을 알려주는 자료이다. 철종 9년(1858)∼고종 33년(1896)간의 것으로 모두 11점이며 한지에 필사한 것이다. ○○○에는 울산부사가 박춘복, 박명대 부자에게 내린 ○○○○○ 별장 임명장과 별장과 인근 동수에게 근무를 철저히 하고 군포를 잘 징수하라는 전령문 그리고 미포 정자 등 ○○○ 인근마을로 부터 군량 형식으로 거둔 금전의 내역을 기록한 문서와 울산부에서 ○○○○○에 내려준 조총 등 무기와 솥 등 장비의 목록 또 별장이 이를 점검하여 이상유무를 보고한 문서들이 있다.","a":"주전봉수대관련고문서","c":"문화유산자료","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659802.jpg"},{"q":"원효대사가 창건하였다고 전해지는 다천사에 세웠던 석탑이라 한다. 절의 내력과 역사는 알 수 없고, 다만 다천사가 용문사에 편입될 당시 탑만이 원래의 절터에 남게 되었다고 전한다. 현재 탑신부(塔身部)의 몸돌 2개와 지붕돌 2개만 남아 2층탑의 모습이지만, 원래는 3층이었을 것으로 추정된다. 탑신의 몸돌에는 모서리마다 기둥 모양의 조각이 보이고, 지붕돌 밑면에는 3단의 받침을 두었다. 꼭대기에는 3개의 보주(寶珠 : 작은 공모양장식)가 남아 머리장식을 하고 있다.","a":"남해 다정리 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641505.jpg"},{"q":"이 비석은 1587년(선조 20) 인동현감 류운룡이 야은 길재의 높은 충절을 기리기 위하여 그 묘역을 수리하고 주변에 사당과 오산서원을 창건한 다음 그 앞에 세운 것이다. 야은의 묘소에서 동쪽으로 약 400m 정도 떨어진 구릉상에 위치하고 있다.","a":"지주중류비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640611.jpg"},{"q":"안동 권씨 부정공파 이우당 권환의 종택으로 인조 18년(1640)에 지었다고 한다. 1963년에 건물 전체를 수리하였으며, 지금 있는 건물은 1994년에 일부분을 고친 것이다. 앞면 5칸·옆면 5칸의 안채는 목조기와집으로 ㅁ자형 구조를 하고 있다. 대청은 6칸이며 우물마루를 깔았다. 사랑채는 영조 49년(1773)에 정침을 수리하면서 높은 기단 위에 지었으며, 건물 주위에 난간을 둘렀다. 마을의 모든 건물은 북향인데 이 집만 북동향을 하고 있다.","a":"이우당종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658662.jpg"},{"q":"‘○○○’은 삼국 시대에 처음 쌓은 것으로 추정되는 안성 백운산 무양산성(舞陽山城)에 있는 암자이다. 암자는 여러 개의 불전(부처와 보살을 모시고 기도하는 장소)과 요사(승려가 머물며 생화하고 수행하는 장소)가 세워지는 일반 사찰과는 달리 적은 인원이 수행을 목적으로 불전과 요사를 하나의 건물로 짓고 생활하는 곳이다.","a":"운수암","c":"문화유산자료","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659933.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 이 고인돌은 국도와 ○○○ 아사 마을 진입로가 서로 만나는 곳의 밭에 자리하고 있다. 모두 4기가 놓여 있는데 남쪽에 있는 것부터 첫번째는 길이 3.55m, 너비 2.5m이며, 두번째는 길이 1.45m, 너비 1.15m이다.","a":"거제 학산리 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656632.jpg"},{"q":"보문산 남쪽 기슭에 있는 ○○○는 조선 인조(재위 1623∼1649) 때 학자이면서 교육자인 남분붕(1605∼1674)이 학문을 가르치던 서재이다. 원래 봉소재라 불렸는데 ‘봉소’는 새들의 보금자리란 뜻으로, 실제로도 ○○○ 주위에는 수백년 된 느티나무 등이 많이 있어 많은 새들이 오가고 있다. ○○○는 후진을 양성하는 교육의 장으로, 숙종 40년(1714)과 영조 34년(1758)에 고쳐 세운 기록이 있다. 안채는 앞면 3칸·옆면 1칸 규모의 건물이고, 누는 앞면 1칸·옆면 2칸 규모로 되어 있다.","a":"봉소루","c":"문화유산자료","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659742.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 세종 8년(1426)에 처음 지었고 임진왜란(1592) 때 불탄 것을 숙종 16년(1690)에 다시 지어 오늘에 이르고 있다. 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 제사지내는 ○○○은 앞면 3칸·옆면 3칸 규모이다. 안에는 묵판음화(墨版陰畵)의 공자 영정이 보관되고 있었는데, 1978년 도난당하였고 지금 있는 공자상은 이것을 대체한 것이다.","a":"지례향교대성전","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662626.jpg"},{"q":"원래 이 그림은 8폭이었는데 한 폭이 남아있지 않았다. 그래서 2003년에 권감(權堪, 1760~1823)의 「제○○○○」 한 폭을 더해 8폭 병풍으로 꾸며놓았다. 제8폭에 있는 권감의 칠언시에 따르면 그의 4대조 권이진(權以鎭, 1668~1734)이 호조판서로 지내면서 오랫동안 고향에 가지 못함을 안타깝게 여기다가 1729년 자신의 종가와 선영(仙塋)이 있는 고향 무수동을 화공을 시켜 그리게 했다고 한다. 현재 무수동에 유회당 등의 유적이 남아있고 지형도 거의 변하지 않아 각 폭의 경물을 파악할 수 있다.","a":"무수동도","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023100511085900.jpg"},{"q":"설재 정가신(1244∼1298)을 기리기 위해 세운 서원이다. 정가신은 고려 문신으로 과거에 급제하여 여러 벼슬자리를 거쳤으며 뛰어난 문장가이기도 하다. 숙종 14년(1688) 노안면 금안동에 세운 이 서원은 숙종 38년(1712)에 향사우로 승격되어 ○○○○이 되었다. 경종 3년(1723)에 영안마을로 이전하면서 강당인 영모재를 세웠다. 그 뒤 고종 5년(1868) 흥선대원군의 서원철폐령으로 폐쇄되었다가 1953에 다시 세웠다.","a":"설재서원","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662028.jpg"},{"q":"곡성 ○○○○○은 해발 735m의 동악산 남쪽 골짜기를 흘러내리는 물줄기로, 동악계곡, 성출계곡과 더불어 아홉 구비마다 펼쳐진 넓은 바위 위로 맑은 물줄기가 흐른다. 마치 비단을 펼쳐 놓은 듯이 흐르는 물줄기는 연중 그치지 않을 뿐만 아니라 늙은 소나무들과 폭포들이 한데 어우러져 매우 아름다운 경치를 이루고 있다. 이곳의 경치를 감상하기 위해 예부터 풍류객들의 발길이 끊이지 않았다고 하며, 9개의 넓은 바위에는 선현들이 새긴 문구가 남아있어 그들의 풍류를 엿볼 수 있다.","a":"곡성도림사계곡","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654258.jpg"},{"q":"이 ○○○○○는 기형과 인화기법으로 볼 때 조선 초기인 15세기에 충청도 지역에서 생산되던 ○○○○ 로 추정된다. 태호 중 국보 제177호로 지정된 ○○○○○문 태호<내외호>(粉靑沙器印花文胎壺<內外壺>)의 풍만한 항아리 모양의 외호와 홀쭉한 내호의 전체적인 형태와 동체 표면에 시문된 인화문 등은 동아대학교박물관 소장 태호에서도 엿 볼 수 있다. 이처럼 15세기 전반기에는 ○○○○로 제작된 네 귀 가 달려 있는 항아리가 많이 생산되고 있으며 유존하는 작품 들 또한 많은 편이다.","a":"분청사기인화국화문사이부태호","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636795.jpg"},{"q":"○○○○○은 본관이 청주(淸州)다. 남이(南怡)의 역모를 잘 다스린 공으로 수충보사병기 정난익대공신(輸忠保社炳幾定難翊戴功臣)에 책훈(策勳)되고, 청평군(淸平君)에 봉해졌다. 이 ‘○○○ 묘역’은 조부 한상경, 부친 한혜 등 청주한씨 묘산(墓山)이다. ○○○은 초취(初娶) 성산이씨(星山李氏), 재취(再娶) 안동권씨(安東權氏), 삼취(三娶) 남원황씨(南原黃氏) 세 부인을 두었으며, 권씨 부인과 상하분(上下墳)으로 안장되어 있다. 각 봉분 앞에는 하엽수(荷葉首; 연잎 형태의 비석 머리) 형태의 묘표(墓表)와 문인석 한 쌍이 건립되어 있다.","a":"양평공한계순묘역","c":"문화유산자료","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660173.jpg"},{"q":"경상남도 ○○시 장목면에 있는 이 성은 동쪽을 제외한 3면이 산으로 둘러싸인 계곡에 돌로 쌓은 성이다. 성 밖에는 민가가 있고 안은 경작지로 사용하는 등 주변 형태를 쉽게 파악할 수 있다. 문터에는 성문을 보호하기 위해 쌓은 작은 성이 북쪽과 남쪽에 있는데, 남쪽은 그런대로 남아 있으나 북쪽은 겨우 흔적만 남아 있다. 원래 외포 바닷가에 성을 만들었는데 이곳으로 옮겼다고 하며 『신증동국여지승람』○○조에는 율포부라 불렀다고 한다. 『○○군지』에 보면 숙종 14년(1688) 통제사 이세현이 글을 써 올려 이곳에 성을 만들고 무종 9품의 권관을 두어 방어케 하였다고 한다.","a":"거제 구율포진성(1998)","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656608.jpg"},{"q":"효종 9년(1658) 설악산 신흥사에서 간행한 1책의 목판본으로 이러한 종류의 서책으로는 이른 시기의 희귀 서책에 해당되며, 선조 2년(1569) 무등산 안심사(安心寺) 본(本)을 모각으로 권말의 발문(跋文)이 낙산사 도원으로 바뀐 것 외에는 안심사본과 같다. 이 책은 밀교(密敎)가 우리나라 불교에 미친 영향을 살피는 참고 자료가 되며, 한글 자모의 용법을 설명한 언본과 범자(梵字)를 한글로 설명한 실담장(悉曇章)은 국어 연구의 중요한 자료이다.","a":"내원정사 진언집","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636678.jpg"},{"q":"○○○의 창건과 중수 과정 등 ○○○의 내력을 전해 주는 기록으로, ○○○ 1책과 목판 11매로 구성되어 있다. ○○○는 세 부분으로 구성되어 있는데, 1733년(영조 9)에 신유한(申維翰, 1681~?)이 작성한 본문과 산인(山人) 명학(明學)이 이듬해에 쓴 발문, 사찰 내 각 전각과 부속 암자에 보관된 경전과 기물의 목록 등이 나열된 부록이 그것이다.","a":"창녕 관룡사 사적기","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641793.jpg"},{"q":"○○○란 어떠한 사건에 관련된 사실이나 자취를 기록해 놓은 것으로, 이 비는 ○○○ 내에 자리하여 절의 사적에 관하여 적고 있다. ○○○는 신라 선덕여왕 7년(638)에 자장율사가 창건하였으며, 그후 다섯 차례에 걸쳐 새로이 고쳐지었다. 조선 숙종 36년(1710)에는 신열이 절을 늘려 짓기도 하였다. 비는 자연암석 위에 비몸을 세우고 지붕돌을 갖추고 있는 모습인데, 특히 지붕돌은 조선 후기에 흔히 나타나는 형식이다.","a":"안심사사적비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639536.jpg"},{"q":"○○○○○은 영양남씨 참봉공 남필대(南必大: 1608-1666)가 중수한 이후 남달만(南達萬: 1713-1784)이 중수하였다는 기록이 있으며, 이후 지속적인 크고 작은 보수를 통해 오늘날까지 이어져오고 있다. 과거 이 건물은 종가에 딸린 건축물인데 기존의 종가 건축물의 유구를 찾아 볼 수 없는 점은 아쉬운 점이다. 다만 종가의 옛 모습은 한국전쟁 이후 건립한 안채와 사당을 통해 추정해볼 수 있다.","a":"영덕 처인당","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101611535700.JPG"},{"q":"한국시단의 거목인 신석정(1907-1974) 선생이 살았던 곳이다. 선생은 전북특별자치도 부안 출신으로 17세에 조선일보에 「기우는 해」를 발표하면서 등단하였다. 1931년 『시문학』지에 시 「선물」을 발표하면서 본격적인 작품활동을 전개하였다. 1930년대 최초의 모더니스트라 불리울만큼 서구의 낭만시와 한국적인 면을 가미한 문단의 거인으로 성장하였다. 석정은 조국을 빼앗겼던 일제의 억압속에서도 질긴 시혼으로 민족혼의 배양토 구실을 했다. 저서로는 시집 『촛불』과 『슬픈목가』가 있다. 가옥은 초가 3칸의 집이었으나 지금은 수리하여 4칸 규모로 되어 있다.","a":"신석정고택","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653623.jpg"},{"q":"○○○○○는 1498년(연산군 4) 무오사화로 인해 순천 지역으로 유배된 조위(曺偉)[1454~1503]와 김굉필(金宏弼)[1454~1504]이 돌을 쌓아 대(臺)를 만들어 교유(交遊)하던 곳으로 조위가 ‘항상 마음을 깨끗이 가지라’라는 뜻으로 ‘임청대’라 이름 지었다. 조위는 1498년 순천에 유배 왔고 김굉필은 평안도 희천으로 갔다가 1499년 순천 지역으로 이배(移配)되었다. 1565년(명종 20) 순천부사로 부임한 이정(李禎)[1512~1571]이 그들의 덕을 기리기 위해 임청대비를 세우고 옥천서원(玉川書院)도 건립하였다.","a":"순천임청대","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639921.jpg"},{"q":"○○○ 동쪽 산중턱의 높직한 암반 위에 있는 석탑이다. 지대석 등의 별다른 시설 없이 암반 위에 방형단을 만들어 기단부를 대신하고 탑신부를 얹었다. 모서리 기둥사이의 면석에는 가늘게 층에 따라 7~11선의 종선문을 음각하였는데 각 층이 똑같은 형태이다. 각 층의 옥개석 하면에는 받침을 생략하고 대신 마름모꼴을 음각하였다. 현재 6층까지 탑신이 남아있지만 원래는 7층이었을 것으로 추정된다. 전체 높이는 7.2m이며 제작시기는 고려시대이다.","a":"화순운주사수직문칠층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662300.jpg"},{"q":"이곳에는 ○○ 출신으로 효행이 탁월하여 사림의 모범이 되었던 정운오(1542∼1593), 추담 김우급(1574∼1643), 조영규(1535∼1592), 처사 조정로(1559∼1612)와 그의 아들, 최학령(1512∼?), 아곡 박수량(1491∼1554)을 추모하여 모신 7기의 비(碑)가 있는 곳이다. 이곳에는 원래 고려 고종(재위 1213∼1259) 때 효자로 소문난 절효공 서릉(徐稜)이 학문을 가르치던 모암정사가 있었다.","a":"장성 칠현 유적지","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022101213343600.jpg"},{"q":"2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 석탑으로, 전체적인 모습이 비교적 완전하게 남아 있다. 현재 아래층 기단은 일부만 남아 있고, 위층 기단은 모서리와 가운데에 기둥 모양을 새겨놓았다. 탑신부의 각 층 몸돌에도 모서리마다 기둥 모양을 조각하였다. 지붕돌은 경사면이 완만하고 네 귀퉁이에서 약간 위로 올라가 있으며 밑면에 4단의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식받침), 복발(覆鉢:엎은 그릇모양의 장식), 앙화(仰花:활짝 핀 연꽃모양의 장식)로 이루어진 머리장식이 완전한 형태로 남아있어 눈길을 끈다.","a":"기림사삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640693.jpg"},{"q":"○○○○은 실용성과 경제성을 중시한 근대기에 건축된 서원이라는 점에서 가치가 있으며 근대기 한옥으로 당시 다양하게 발전하는 한옥의 변천과정을 보여준다는 점에서 건립연대는 오래되지 않으나 학술적인 연구대상으로서 보존가치가 있다.","a":"창녕 동산서당 강당","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665437.jpg"},{"q":"금강산 표훈사의 주지인 이화응과 ○○○ 주지 배선주가 1928년 낙가산 중턱 일명 눈썹바위 암벽에 조각한 석불좌상으로, 높이 9.2m, 폭 3.3m이다. 머리에는 커다란 보관(寶冠)을 쓰고 있으며 얼굴은 네모진 모습이다. 얼굴에 비해 코는 넓고 높으며, 귀는 투박하고 목은 매우 짧게 표현되었다. 옷은 각이 진 양 어깨를 감싸고 있으며, 가슴에는 큼직한 卍자무늬가 새겨져 있다. 손에는 깨끗한 물을 담은 병을 들고 연꽃무늬 대좌(臺座) 위에 앉아 있으며, 불신 뒤에는 부처의 몸에서 나오는 빛을 형상화한 광배(光背)가 있다.","a":"강화 보문사 마애관음보살좌상","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637078.jpg"},{"q":"○○○는 전북특별자치도 무안군 상서면에 있는 사찰로, ○○○의 ○○○에는 각기 다른 자세를 취하고 있는 16구의 ○○○이 모셔져 있다. 나한은 ‘아라한’의 준말로, 온갖 번뇌를 끊고 깨달음을 얻어서 세상 사람들의 공양을 받을 만한 공덕을 갖춘 성자를 뜻한다. 『발원기』와『사적기』등 전해 내려오는 기록에 의해 조선 숙종 3년(1677)에 만들었음을 알 수 있다. ○○○○이 지닌 단아한 형태와 부드러운 양감 등은 17세기 불상의 특징을 잘 보여주고 있다. 관련 기록이 잘 보존되어 있으며 양식적으로도 17세기 불상의 특징을 대표할 만한 작품이다.","a":"개암사응진전16나한상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639660.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 세종 19년(1437)에 처음 지었으며 임진왜란으로 완전히 불타 없어진 것을, 영조(재위 1724∼1776) 때에 다시 지어 오늘에 이르고 있다. ○○○의 규모는 앞면 3칸·옆면 3칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"함열향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661698.jpg"},{"q":"충청북도 ○○군 ○○읍 ○○○에는 조선시대에 만들어진 나무로 된 여래좌상과 관음보살좌상이 모셔져 있다. 높이 85㎝의 ○○○○○은 머리에 작은 소라 모양의 머리칼을 붙여 놓았으며, 눈·코·입이 조화를 이루어 정돈된 느낌을 준다. 목에는 3줄의 주름인 삼도(三道)가 뚜렷하고, 양 어깨를 감싼 옷을 걸치고 있다. 양 손목과 무릎에 걸쳐 두껍게 표현된 옷주름은 조선시대 특유의 양식이다. 엄지와 검지의 손끝을 맞대어 오른손은 들고 왼손은 내려 부처가 설법할 당시의 손모양을 표현하였다. 높이 72㎝의 관음보살좌상은 머리에 화려한 관(冠)을 쓰고 있다.","a":"괴산 개심사 목조여래좌상 및 목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638664.jpg"},{"q":"제주시 북제주군 한림읍 명월리와 동명리 일대에 남아 있는 명월성터는 조선 중종 5년(1510)에 목사 장림(張琳)이 쌓았던 성터라 한다. 당시 이 근처의 비양도(飛揚島)가 왜군의 군함을 정박하던 곳이어서, 왜군을 막기 위해 이 곳에 성을 쌓았는데, 둘레가 3020척, 높이가 8척이며 동·서·남쪽에 성문이 있었다고 한다. 성 안에는 샘이 있어 마치 냇물처럼 물이 솟아나므로 항상 물걱정이 없었다는 기록도 있다. 성을 지키는 장수 한 사람이 있었고, 숙소인 객사와 무기를 저장하는 창고 등이 있었으며, 노를 젓는 군사 103명이 배치되어 있었다고 한다.","a":"명월성지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657865.jpg"},{"q":"정송강 유적은 조선 중기 학자이자 정치가인 정철(1536∼1593)이 성산에 와 있을 때 머물렀던 곳으로, ○○○과 식영정으로 구성되어 있다. 정철은 호가 송강으로, 명종 16년(1561) 27세의 나이로 과거에 급제하였다. 그 뒤로 많은 벼슬을 지내다가 정권다툼으로 벼슬을 그만두고 고향인 성산에 내려와 『성산별곡』, 『사미인곡』 등의 문학작품을 지었다. ○○○은 앞면 2칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 앞면에는 ‘○○○’이라는 현판이, 옆면에는 ‘죽록정’이라는 현판이 걸려 있다.","a":"담양 송강정","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653904.jpg"},{"q":"『성호선생문집』책판은 조선 후기 우리나라 문화와 사상사에 하나의 신기원을 이룩한 실학자인 성호 ○○의 방대한 문집을 ○○에 새겨 발행한 것으로, 총 27책 800여 장으로 여주 이씨 문중의 천연정에서 간행되었다. ○○은 둘째형 이잠이 장희빈을 두둔하는 상소를 올렸다가 47살의 나이로 옥에서 죽자, 과거에 나아갈 뜻을 버리고 평생을 조상들의 묘가 있는 안산의 첨성리에서 살았다. 그의 학문은 철저하게 유교적인 기반 위에서 이루어진 것이었으나, 당시의 세계관과 역사의식이 확대되면서 자기나라에 대한 새로운 인식과 실증적인 태도를 갖추었다.","a":"이익 성호문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641785.jpg"},{"q":"○○○는 담양군의 서남부에 위치하는데 영산강 본류에 증암천이 합류되는 지점에서 북쪽으로 100m 정도 떨어진 평지에 위치하고 있다. 마을 북쪽은 삼인산에서 내려오는 구릉이 충적지에 이어지면서 평지를 이루고 남쪽은 영산강변의 충적지가 펼쳐져 있다. 현재 마을 주변이 모두 논이기 때문에 이 지역에서 지형적인 변화는 거의 찾아보기 어렵지만 1/25,000 지형도를 보면 ○○○ 마을은 고리대 마을에서 남쪽으로 이어지는 평지성 저기복의 구릉 남동쪽에 위치하고 있는 것으로 보이며 고분은 구릉의 능선상에 있었던 것으로 추정된다.","a":"담양황금리금구동고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662254.jpg"},{"q":"정난종 일가 묘역은 조선 전기의 문신인 정난종과 그 후손의 무덤이다. 정난종 부부의 무덤은 하단에 위치하고, 장남인 정광보 부부의 무덤이 중단에 있으며, 차남인 정광필 부부의 무덤이 상단에 있다. 그 외에도 정광좌, 정위겸, 정익겸, 정복겸, 정유진, 정유청, 정준항, 정진원 등 여러 후손의 무덤이 남아 있다. 정난종鄭蘭宗(1433-1489)은 세조와 성종 연간에 활동한 인물로 성리학에 뛰어난 당대 최고의 서예가이다. 그는 당대 최고의 서예가로 초서草書, 예서隸書, 조맹부체趙孟頫體를 잘 썼다.","a":"정난종선생묘 및 신도비일원","c":"시도기념물","nc":"","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646490.jpg"},{"q":"강원특별자치도 정선군 신동읍의 ○○○와 덕천리 경계지점인 해발 425m의 산능선을 따라 돌로 쌓은 산성이다. 『신증동국여지승람』에는 정선군의 동쪽 5리 지점에 둘레 782척(237m), 높이 8척(2.4m)으로 돌을 쌓아올렸고, 그 안에 성황사(城隍祠)가 있었으나 절반이 무너졌다고 기록되어 있다. 성벽은 점판암을 이용하여 쌓았으며, 성벽의 가장 높은 곳은 약 8m 정도이고, 안쪽은 약 4m 정도이다. 성벽의 바깥으로는 ㄷ자 모양으로 또 하나의 성벽을 튀어나오게 쌓아 방어력을 높였는데 폭은 5m, 길이 6m, 높이는 3.7m이다.","a":"정선고성리산성","c":"시도기념물","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648353.jpg"},{"q":"조선 전기 무신인 ○○○ 장군의 생가가 있던 곳으로, 북면 송촌마을 뒷산에 자리잡고 있다. 장군은 조선 세종 때 무신으로 무과에 급제하여 벼슬에 나아갔다. 세종 1년(1419)에 삼군도통사가 되어 이종무와 함께 대마도를 정벌하였고 후에 공조판서가 되고 평안도절제사가 되었다. 평안도절제사로 있을 때에는 이민족을 격파하여 우의정으로 특진되었다. 세종 17년(1435) 좌의정에까지 오른 장군은 특히 성품이 자애롭고 근검하였다고 한다. 이 터는 주민들이 정승골이라고 부르고 있으며, 계단식 논과 과수원을 경작하고 있다.","a":"창원 최윤덕 유허지","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655838.jpg"},{"q":"복전암(福田庵)에서 ○○○성으로 오르는 등산로를 따라 1㎞쯤 올라간 곳에 위치한 높이 약 6m의 바위 남쪽에 새겨진 ○○○○○이다. 일명 '장수부처'라고 불린다. 두광(頭光)과 신광(身光)을 지니고 연화대좌 위에 앉은 부처를 얕은 부조(浮彫)와 선각(線刻)으로 새겼는데, 얼굴과 어깨부분은 얕은 부조기법으로 입체감을 살렸으며 그 아래 부분은 선각에 가깝게 처리하여 마치 바위에 그림을 그린 것 같다. 불상의 머리 위쪽의 바위가 균열되면서 머리의 오른쪽(향좌) 나발(螺髮)이 일부 떨어져 나간 것을 제외하고는 보존 상태는 양호한 편이다.","a":"보문산마애여래좌상","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637207.jpg"},{"q":"우리나라 ○○○○에 대한 최초의 기록은 『세종실록』에 언급된 서울 세검정의 ○○○○로서, 대부분 구릉성 산지에서 떨어지는 낙차를 이용한 것이다. 운교리 방앗간 규모는 전면 3칸·측면 1칸이며, 물을 막은 보(洑)는 61m, 보에서 ○○○○에 이르는 수로(水路)는 252m, 수로 넓이는 2m, 깊이는 2m이다. 물레의 재질은 소나무이며, 지름이 310㎝, 폭 130㎝, 날개는 기존의 ‘一’자형이 아닌, 소유주가 도정력을 높이기 위해 특수 제작한 ‘ㄱ’자형으로 된 47개로서, 해마다 부분적인 보수를 하여 보존상태가 양호하며, 현재도 계속 가동하고 있다.","a":"백운면의물레방아","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658339.jpg"},{"q":"조선 정종(재위 1398∼1400)의 열번째 아들인 ○○○을 모시기 위해 세운 사당이다. ○○○은 가난한 백성을 정성껏 도왔으며, 왕자의 신분에도 들에 나가 농사를 지었다. 또한 여름에 홍수로 수백명의 이재민이 발생하자 구제하였으며, 덕을 쌓은 어른이라 하여 적덕공이라고도 불렀다. 처음 연기군 남면 방축리에 있던 건물이 낡아 조선 영조 15년(1739)에 지금 있는 자리로 옮겼다.","a":"장군 덕천군사우","c":"문화유산자료","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1797531.jpg"},{"q":"상대산 기슭에 자리하고 있는 가옥이다. 이곳은 안동 권씨 영해 괴시(槐市)의 입향조 권의협(1579∼1644) 선생의 첫째 아들 대은 권경이 세운 것이다. 1889년과 1978년 두차례 보수를 하였다. 원래 안채와 사당으로 구성되어 있었으나 현재는 안채만 남아 있다. 앞면 5칸·옆면 6칸 반 규모이며 ㅁ자형으로 배치되어 있다.","a":"대은종택","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663040.jpg"},{"q":"이 비는 조선 성종 때의 공신인 ○○○ 장군의 ○○○이다. ○○○는 임금이나 공신의 생애를 기록하여 그의 묘 앞에 세운 비석이다. 조선시대에는 정2품 이상의 관직을 지낸 사람에게 세워주어 그 생애를 기리도록 했다. ○○○은 세조비 정희왕후의 언니의 아들이였고 세조에서 연산군 사이에 의금부사, 오위도청 부총관, 호조판서, 경상도 관찰사, 한성판윤 등을 지냈으며 이시애의 난을 평정하는데도 공을 세웠다. 비석의 받침돌은 화강석이고, 비석의 몸 돌과 비석의 머리돌은 하나의 대리석으로 되어 있다.","a":"이철견신도비","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636914.jpg"},{"q":"원래 강원특별자치도 횡성군 공근면 상동리의 절터에 있던 것을 일제시대에 지금의 위치로 옮겨온 것으로 불신, 대좌(臺座), 광배(光背)를 모두 갖추고 있는 거의 완전한 상태의 ○○○○이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로는 작은 상투 모양의 머리묶음이 솟아있다. 옷은 양 어깨를 감싸고 있는데 얇고 부드럽게 조각하였고, 옷주름은 아주 자연스럽게 온몸을 감싸면서 무릎까지 덮고 있다. 양 손은 가슴에 모아 오른손으로 왼손 검지를 잡고 있으나 손끝이 모두 파손되고 손가락이 없어졌다. 손모양으로 보아서는 비로자나불을 형상화한 것으로 보인다.","a":"읍하리석불좌상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637906.jpg"},{"q":"『○○○○○』은 ‘진실한 가름침의 연꽃 같은 경’이라는 뜻을 가지고 있으며, 이를 줄여 『법화경』이라고도 하는데 대승경전(大乘經典)을 대표하는 경전이다. 인간 누구에게나 평등하게 갖추어져 있는 불성(佛性)을 인정함으로써 인간에 대한 신뢰를 말하고, 그 약속을 인간 스스로 실천하여 성불(成佛)하도록 하는 구체적인 실현 방법을 이야기하고 있다. 또한, 『법화경』은 『화엄경』과 함께 우리나라 불교사상 확립에 가장 큰 영향을 미쳤으며, 삼국시대 이래 가장 많이 유통된 경전이다.","a":"묘법연화경 권4∼7","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638867.jpg"},{"q":"○○○는 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. ‘○○○○○’는 건지산(해발 411m)과 수정산(해발 344m) 사이에 형성된 곡간 지역의 산사면 아래 평지에 위치한다.","a":"용인 맹리 지석묘","c":"문화유산자료","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660068.jpg"},{"q":"○○○는 통일신라 헌안왕 2년(858)에 도선이 세운 뒤 여러 차례 고쳐 지은 절이다. ○○○을 지은 것에 대한 기록은 없으나 조선 정조 6년(1782)에 고쳐 세운 기록이 있어 그 이전부터 존재한 것을 알 수 있다. 또한 이에 앞서 숙종 15년(1689) 인현왕후가 장희빈 때문에 폐위되어 이곳 ○○○ 극락전에 은거하였는데, 이 때 극락전 서쪽에 인현황후의 복위를 빌기 위해 ○○○을 세웠다는 설도 있다. 그 뒤 광무 9년(1905)에 다시 세웠으나 1911년 화재로 소실되었고 이듬해 다시 지어 오늘에 이르고 있다.","a":"청암사보광전","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663056.jpg"},{"q":"○○○는 1973년에 세운 건물로 공자를 중심으로 주자와 안자의 영정을 모시고 있는 사당이다. 앞면 3칸·옆면 1칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 원래 대평면 하촌리에 있던 것을 남강댐 공사로 1995년 지금 있는 자리에 옮겨 지었다.","a":"진주 도통사","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663956.jpg"},{"q":"이 유적은 강원특별자치도 횡성군 둔내면 둔방내리에 소재한 둔내중·고등학교를 중심으로 그 주변지역에 위치하고 있으며, 횡성군의 동쪽 끝지역으로 횡성읍으로부터는 동북방 30㎞ 지점이다. ○○○는 가지구 3기, 나지구 5기 등 총 8기가 발견되었으나, 가지구에서는 터파기 공사로 파손된 상태였고, 나지구에서도 도로 및 사유지로 연결되어 온전히 발굴된 것은 나-2호○○○ 1기에 불과하였다. 한편 보존상태가 양호한 여자형(呂子形) 집자리는 당시 가옥의 구조와 변천 과정을 잘 보여 주고 있다.","a":"횡성둔내철기시대주거지유적","c":"시도기념물","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648917.jpg"},{"q":"○○○가 소장중인 ○○○○○ 모두 8건으로 각각의 명칭은 묘법연화경권제1, 묘법연화경권제3,4, 묘법연화경권제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, 불정심관세음보살대다라니경, 월인석보제21(상), 불설대보부모은중경이다. 구마라습이 지은 묘법연화경 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"창원 봉림사 불교전적류","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642607.jpg"},{"q":"조선 정조 12년(1788)에 농수재 최광익(聾睡齋 崔光翊:1731~1795)이 둘째 아들인 최승우(崔昇羽:1770~1841)를 위해 지었으나 그 형인 최성우(崔成羽:1762~1802)와 집을 바꾸었다고 전한다. 북애라는 명칭은 건너편에 위치한 구미 쌍암고택(국가민속문화유산)에서 이 집을 바라볼 때 북쪽 언덕에 있다하여 지어진 이름이다. 一자형 사랑채와 중문간채, ㄷ자형 안채가 남향으로 배치되었는데, 쌍암고가와 같은 형식이다. 원래는 대문간채와 사당도 있었다고 하나 현재는 남아있지 않다.","a":"해평동북애고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658597.jpg"},{"q":"○○○○은 경상남도 ○○군 남지읍 고곡리에 있는 산성으로, 산의 동쪽 6부 능선을 타고 서·남으로 향하면서 타원형을 그리고 있다. 성벽은 돌과 흙을 섞어 쌓았는데, 사다리꼴의 형태를 띄고 있다. 전체적인 형태는 남아있지만, 무너져 내린 부분이 많다. 이 지역이 옛 가야의 영토였다는 점과 성을 쌓은 방법으로 보아 가야 때 쌓은 성으로 추정되며, 조선 선조 25년(1592) 임진왜란 때 망우당 곽재우 장군이 침입한 왜군을 막아내기 위해 다시 쌓았다고 전해진다. 1950년 한국전쟁 때에는 치열한 전투가 벌어진 곳이기도 하다.","a":"창녕 고곡산성","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664010.jpg"},{"q":"○○○○○ 1호분 서남향 10m 정도에 자리하고 있는 개석식 고인돌 형식으로 축조시기는 대략 기원전 1세기에서 기원 후 1세기경으로 추정된다. 뚜껑돌 형태는 사다리꼴 모양이며 상석이 지표면에 닿이 있으며 좌우 측면에 치석 흔적이 있다. 동쪽으로 약간 기울어져 있다. 장축 280cm, 단축 220cm, 두께 50cm이며 축조시기는 탐라시대 전기 AD 1~300년경이다.","a":"상예동지석묘2호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657712.jpg"},{"q":"괘불은 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리던 대형 걸개그림을 말한다. ○○○에 보관된 이 괘불은 석가를 비롯한 삼존과 문수보살, 보현보살을 비단 바탕에 채색하여 그린 그림으로, 가로 287.3㎝, 세로 456㎝ 의 크기이다. 상단에 그려진 삼존은 전체적으로 부자연스럽게 표현되어 형식화된 느낌이고, 하단에 그려진 문수보살과 보현보살은 비교적 자유롭고 활달하게 묘사되어 위와 대조를 이룬다. 적색과 녹색, 청색이 주로 사용되었으며, 특히 이 시기에 제작된 다른 불화들보다 색채가 밝아 눈길을 끈다.","a":"지장사 괘불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588019.jpg"},{"q":"이 책은 안동지역의 대표적인 향토지 초고본으로, 1602년 권기(1546∼1624)가 그의 스승인 류성룡의 명에 따라 편찬에 착수하여 1608년에 8권 4책으로 완성하였다. 이 초고본『○○○』는 불행하게도 300여 년이 지난 1899년에 김도화와 류도헌의 발문으로 후손인 상학, 상태, 상표가 판각하여 간행하였다.","a":"영가지및책판","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640745.jpg"},{"q":"○○○○○는 1932년에 용화면 월전리에 있던 정참봉의 집을 옮겨 지었다고 전해오는 주택으로 ‘영사재’라 불린다. 오래된 건물은 아니지만 특징 있는 세부 소재를 갖추고 있다. ㄱ자형의 안채와 ㅡ자형의 부속건물 그리고 행랑채의 지붕보다 한단 높이 만든 솟을대문 등이 남아있다. 안채는 자연석을 쌓아 만든 기단 위에 마루 앞면에는 긴 주춧돌을 놓고 다른 부분에는 4각으로 다듬은 주춧돌을 놓았다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕이다.","a":"영동 묵정리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638620.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 세워진 시기는 언제인지는 모르나 원래 의령읍 동동에 있던 것을 조선 선조 15년(1582) 현감 이함이 지금의 자리로 옮겼다고 한다. 그 후 여러 차례 보수했다. 건물들은 급경사지에 세워졌는데 여러 개의 가파른 계단을 통해 서로 연결되고 있다. 공부하는 곳인 명륜당과 동·서재가 앞에 있고 사당인 대성전이 뒤에 있는 전학후묘의 배치이다. 특이한 것은 대성전 좌우의 공간에 동·서무를 세울 수 있는데도 세우지 않은 것이다.","a":"의령향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641829.jpg"},{"q":"○○○는 ¨전등사본말사지¨등의 기록에 의하면 백련사 및 청련사와 함께 고구려 장수왕 4년(416)에 창건되었고, 처음에는 적련사(赤蓮寺)였다는 전설이 전하고 있다. ○○○를 오르는 길목 오른쪽에 자리한 ○○○○○는 숙종 40년(1714)에 세워진 것으로 전체 높이가 3m94cm이고 비신의 높이 3m4cm, 너비 69cm이다. ○○○의 재질은 화강암이고, 지붕모양의 뚜껑돌이 얹혀 있으며 비신의 상부에 ¨고려산○○○지비(高麗山積石寺之碑)¨라는 비의 제목이 있다.","a":"강화 적석사 사적비","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101617211600.jpg"},{"q":"영산회상은 넓은 의미로는 석가여래의 가르침 또는 불교 그 자체를 의미하는 것으로 불교의 상징적인 표상이며, 좁은 의미로는 석가여래가 영취산에서 『법화경』을 설법한 법회모임을 말한다. ○○○○○는 이와 같은 의미와 내용을 표현한 불화로, 석가여래를 주존불(主尊佛)로 모시는 ○○○에 주로 봉안된다. ○○○○○의 후불벽(後佛壁)을 꽉 채운 채 걸려 있는 이 ○○○○○는 족자형의 대형 불화로 괘불(掛佛)의 폭과 맞먹는 대형이면서도 전체적으로 보존 상태가 양호한 작품이다.","a":"범어사 대웅전 영산회상도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636731.jpg"},{"q":"충청남도 천원군 성거읍 청흥리의 ○○○ 법당 뒤의 자연암벽에 돋을새김한 마애여래좌상이다. 미완성의 불상이며 마멸이 심해 윤곽을 알아보기 어렵다. 머리 부분은 직사각형이고 얼굴의 윤곽은 거의 알아볼 수 없다. 양 어깨는 거의 수평으로 당당하게 보이며, 양 발을 무릎 위에 올리고 발바닥이 하늘을 향한 자세로 앉아 있다. 불상의 앞부분과 머리 위쪽 양편에 홈이 있는 점으로 보아 보호각을 설치했던 것 같다.","a":"만일사마애불","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661312.jpg"},{"q":"벽방산 기슭에 위치한 ○○○는 신라 무열왕 1년(654)에 원효대사가 처음 지었다고 한다. 임진왜란으로 불타 없어진 것을 조선 영조 27년(1751)에 다시 지었고, ○○○도 이 때에 다시 지은 것이다. 그 후 여러 차례의 수리를 거쳐 오늘에 이르고 있다. ○○○○○은 앞면 3칸·옆면 3칸의 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 지붕을 받치면서 장식을 겸하는 공포가 기둥 위와 기둥 사이에도 있는 다포식 건물이며, 기둥 사이에는 각각 2구의 포를 배치하였다. 단청으로 채색한 화려한 공포는 일반적인 다포계 후기의 경향을 잘 나타내고 있다.","a":"통영 안정사 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641518.jpg"},{"q":"조선 인조 때의 문신인 태계 ○○의 시문과 글을 모아 숙종 9년(1683)에 판에 새겨 간행한 것이다. ○○은 인조 2년(1624)에 진사가 되고, 인조11년(1633)에 문과에 급제하여 사간원정언, 사헌부지평을 지냈다. 이 문집에는 시(詩), 부(賦), 상소, 책(策), 논(論), 변(辯), 서(書) 등의 내용이 수록되어 있다. 책판은 총 174매가 현재 태계정에 보관되어 있다.","a":"하진 태계문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642025.jpg"},{"q":"○○○ 남쪽 고부와 부안을 잇는 도로변에 위치한 무덤들이다. 원래 4기의 무덤이 있었으나, 도로를 만들면서 가장 동쪽에 있는 봉분이 파괴되었다. 형태는 구덩식(수혈식)이며, 유물은 도굴되어 거의 남아있지 않은 상태이다. ○○○ 무덤들은 백제 전기인 4세기 말에서 5세기 전반의 것으로 구덩식(수혈식)무덤으로는 가장 큰 규모이다.","a":"지사리고분군","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653523.jpg"},{"q":"○○○○○는 충무공 이순신의 충절과 업적을 후대에 전하기 위해 세운 비다. 비문은 광해군 6년(1614)에 좌의정 이항복(李恒福)이 지었고, 비석의 위쪽에 ‘통제사 충무이공 ○○○○명(統制使忠武李公 忠烈廟碑銘)’이라고 되어 있는 전서체의 글씨는 김수항(金壽恒)이 썼다. 비문의 끝부분에 묘비를 세우게 된 경위를 밝히고 있는데 이것은 송시열(宋時烈)이 기록한 것이다. 이후 숙종 7년(1681)에 제60대 통제사 민섬(閔暹)이 머릿돌과 거북 받침대를 갖추어 세웠다고 한다. 비문에는 임진왜란 당시 이순신의 공훈에 대한 칭송과 그에 대한 존경 및 사모의 내용이 담겨 있다.","a":"통영 충렬묘비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2024121812553400.jpg"},{"q":"천관사 극락보전 아래쪽에 놓여 있는 석등으로, 바닥돌을 제외한 각 부분이 8각을 이루고 있다. 등불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 3단의 받침을 두고 위로는 지붕돌과 머리장식을 얹었다. 받침부분은 아래·윗받침돌에 서로 대칭되는 연꽃을 새기고, 그 사이는 기둥을 세워 가운데 받침을 삼았다. 화사석은 불빛이 퍼져나오도록 4곳에 창을 뚫었다. 지붕돌은 여덟 귀퉁이가 시원스레 들려있어 경쾌한 처마선을 그린다. 꼭대기에는 얇은 받침 위로 높지막한 꽃봉우리 모양의 머리장식이 놓여있다.","a":"천관사석등","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639999.jpg"},{"q":"청호마을 동북쪽 산 기슭에 우뚝 서 있는 석탑으로, 자연암반을 바닥돌 삼아 1층 기단(基壇)을 올린 후, 3층의 탑신(塔身)을 올린 모습이다. 탑신의 각 몸돌은 모서리마다 기둥 모양을 본 뜬 조각을 두었고, 지붕돌은 밑면에 1층은 4단, 2·3층은 3단씩의 받침을 새겼다. 특히 지붕돌은 밑면과 윗면의 경사가 비슷하여 단조로운 느낌을 준다. 1층 몸돌이 지나치게 길어 불안정해 보이고, 퇴화된 양식을 보여주는 지붕돌에 의해 전체적으로 둔탁해 보인다. 산 중턱에 자리잡은 점과 자연암반을 바닥돌로 삼은 점, 단순한 조각솜씨들로 보아 고려시대에 세운 탑으로 추측된다.","a":"의성쌍호동삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662390.jpg"},{"q":"공산성 공북루 아래에 자리한 한채의 비각안에 3기의 비가 나란히 서 있다. 이 비들은 정유재란 이듬해인 선조 31년(1598) 공주에 주둔해 있으면서 주민들을 왜군의 위협으로부터 보호해 준 명나라 세장수 이공, 임제, 남방위의 업적을 기리고 있다. 원래 선조 32년(1599) 금강변에 처음 세웠다가 홍수로 매몰되어 숙종 때에 다시 세워둔 것이다. 일제시대를 거치면서 일본인들에 의해 ‘왜구(倭寇)’등의 글자가 훼손되었고, 공주읍사무소 뒤뜰에 아무렇게나 매몰되었던 것을 광복 후 현재의 자리로 옮겨 세웠다.","a":"명국삼장비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639057.jpg"},{"q":"20세기 초 완호 금어에 의하여 조성된 작품으로 관음세지 양대보살과 하단에 사자와 흰 코끼리 등위에 정좌한 문수·보현의 동자상이 배치가 돋보이는 귀중한 자료이므로 문화유산자료로 지정함","a":"사천 백천사 아미타후불탱","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666710.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 원래는 군서쪽 8리에 있던 것을 중종 37년(1542)에 주세붕이 이곳으로 옮겨 지은 후 숙종 18년(1692)에 다시 옛터로 되옮겼다가 영조 11년(1735)에 현재의 위치로 옮겼다. 남아있는 건물로는 공부하는 곳인 명륜당, 향교를 관리하던 교직사, 사당 출입문인 내삼문, 사당인 ○○○과 동·서무 등이 있다. 특히 ○○○과 동·서무의 벽과 창호가 특이해 고풍스럽다.","a":"풍기향교<대성전동.서무>","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640709.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 광해군 9년(1617)에 처음 지었다. 철종 6년(1855)의 성묘중수기(聖廟重修記)가 남아 있는데, 지금 있는 대부분의 건물은 이 때 지어진 것이다. 건물 배치는 교육 공간인 명륜당을 앞에 두고, 제사 공간인 대성전을 뒤로 한 전학후묘의 공간 구성을 이루고 있다. 현존하는 건물로는 대성전, 명륜당, 동재·서재, 풍화루, 내삼문, 외삼문 등이다. 대성전은 앞면 3칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"기장향교","c":"시도기념물","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645140.jpg"},{"q":"조선왕조 태종 때 문신인 ○○의 무덤을 비롯한 6기의 무덤들으로 해발 120m의 야산에 위치한다. ○○은 고려 말 이색의 제자로 요동정벌을 반대하였으며 조선왕조가 건립될 때 계룡산에 도읍을 정하는 것을 반대하기도 하였다. 이방원을 도와 제1차 왕자의 난을 일으켰고, 태종의 즉위를 도와 1등공신에 등록되었다. 벼슬은 영의정부사까지 올랐고, 한나라 장자방과 비유되기도 한다. 이 지역에는 ○○의 무덤을 비롯하여 그의 할아버지 하시원, 할머니 진양정씨, 아버지 하윤린, 어머니 진양강씨 등 진양 하씨의 집안무덤이 있다.","a":"진주 하륜 묘역","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654931.jpg"},{"q":"1935년에 세운 가옥이다. 안채와 사랑채가 건물 하나로 연결된 ㅁ자형으로 같은 시기에 지은 것이다. 안채는 왼쪽으로부터 부엌·큰방·윗방 순이며 꺾어져서 대청이 있다. 대청은 큰방과 사랑채에서만 이용할 수 있게 되어 있는 것이 특이하다. 대청 천장은 뼈대가 그대로 드러나 있는 연등천장이다. 마루에는 조상의 위패를 모시고 있는 공간과 수납 공간인 벽장을 안쪽에 만들어 놓았다. 사랑채는 대문을 중심으로 오른쪽에 아랫사랑·윗사랑이 있고, 왼쪽에 마구간이 있는 구조이다. 마구간 뒤쪽으로는 안채와 연결되는 광이 있다.","a":"삼척 고천리 고택","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660497.jpg"},{"q":"「○○○ 석○○○○○」는 ○○○ 옛 대웅전의 석가여래 좌상 뒤편 후불벽 전면에 봉안된 후불탱화이다. 화기(畵記)를 통해 「○○○ 석○○○○○」가 1921년 12월 동래군 명장리 석금대에 봉안되었고, 증명 비구 혜명(慧明), 금어 완호(玩虎), 시찬(施讚) 등이 관여하였음을 밝히고 있어, 1921년 조성된 이후 어느 시기에 ○○○로 이안되어 왔음을 알 수 있다. 2005년 12월 27일 부산광역시 문화유산자료로 지정되었다 「○○○ 석○○○○○」의 크기는 세로 125.7㎝, 가로 261.0㎝로 옆으로 긴 장방형을 이루며, 면 바탕에 채색을 베푼 작품이다.","a":"복천사석가영산회상도","c":"문화유산자료","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022120810581400.jpg"},{"q":"○○읍의 중심부를 흐르는 동락천 위에 설치하였던 수문이다. 조선 숙종 37년(1711)에 ○○산성의 내성을 쌓을 때 연결하여 처음 설치하였으나, 광무 4년(1900)에 갑곶 나루터의 통로로 삼기 위하여 개천 어구에 옮겼다. 그 뒤 1977년에 다시 지금의 위치로 옮겨 복원하였다. 길이는 18.2m이고 높이는 2.7m, 너비는 4.7m이다. 무지개 모양의 수문이 3개이며, 화강암을 다듬어 쌓았다.","a":"강화 석수문","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018111917345000.jpg"},{"q":"○○○는 신라 지증왕 4년(503) 연기조사가 ‘영악사’라는 이름으로 처음 지었고, 후에 도선국사가 ○○○로 바꾸어 불렀다고 한다. 절 경내에는 대양루를 비롯하여 대웅전, ○○○, 극락전 등이 있다. 나한전이라고도 하는 ○○○은 신라 선덕여왕 5년(636)에 자장율사가 지었으며, 임진왜란 때 불타 없어진 것을 숙종 6년(1680)에 다시 세웠다. 그 뒤 낡은 건물을 1930년 만해 한용운 선생이 보수하여 오늘에 이른다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"사천 다솔사 응진전","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664187.jpg"},{"q":"○○○는 남원시에 있는 절로 평지에 있으며 통일신라시대에 도선이 남쪽 산천을 둘러본 후 헌강왕 1년(875)에 이곳에 지었다. 선조 30년(1597) 정유재란 때 만복사와 함께 불타버린 것을 영조 30년(1754)에 다시 짓고 철불을 ○○○에 모셨다. 처음 지어졌을 당시에는 규모가 대단히 컸다고 한다. ○○○는 남원시의 번영과 깊은 관계가 있다고 믿어왔으므로 시내에 거주한 지방인사들이 후원하고 보호해 왔다. ○○○○○은 약사불을 모시는 곳으로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"선원사약사전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639546.jpg"},{"q":"○○○○○은 자연석의 통바위로서 규모는 높이 2.93m, 길이 13.35m, 폭 2.5m이다. 형태가 배모양 같다 하여 '배바위' 또는 고래모양이라 하여 '고래바위' 또는 베틀에 딸린 북모양이라 하여 '북바위'등으로 불리우며 동쪽으로 머리를 두었다. 배바위의 암각 명문은 매향과 관계된 고려말, 조선초의 기록으로서 전국에서 발견된 매향관련 명문 중 비교적 이른 시기의 자료라 할 수 있으며 조성시기를 달리하는 2건의 매향자료가 기록되어 있어 ○○○○ 및 주변지역의 역사와 매향의식을 확인할 수 있는 귀중한 자료로 평가된다.","a":"당진안국사지매향암각","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653158.jpg"},{"q":"○○○라는 절터에 있는 다층의 목탑 유구이다. ○○○지는 월출산 사자봉에 있는데 그동안 천황사라고 불리어 오다가 발굴 조사에서 ‘○○○’라는 명문이 출토됨으로써 절이름이 밝혀졌다. ○○○에서 통일신라 후기에 조성된 기와들이 발견되어 이때 ○○○가 창건된 것으로 보인다. ○○○의 기단은 한변의 길이가 10.5∼10.8m로 거의 정사각형을 이루고 있다. 남쪽과 서쪽은 장대석과 할석들로 단면 장방형으로 쌓아 만들었다. 기초를 이루는 초석은 양면 각각 4개가 아주 정연하게 노출되었는데 남서쪽 모서리 1개만 유실되고 없다.","a":"영암사자사목탑지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654353.jpg"},{"q":"지촌 김방걸 선생의 덕을 기리기 위해 세운 서원이다. 김방걸(1623∼1695) 선생은 현종 1년(1660)에 증광문과에 병과로 급제하여 벼슬길에 올라 많은 관직을 지냈다. ○○○○은 정조 24년(1800)에 지었으나 고종 때 흥선대원군의 서원철폐령으로 철거되었다. 그 뒤 1926년에 복원하였으며, 1988년 임하댐 건설로 지금 있는 자리에 옮겨 세웠다. 서당 건물은 앞면 5칸·옆면 2칸 규모의 一자형이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다.","a":"지산서당","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662440.jpg"},{"q":"○○○는 통일신라 흥덕왕 6년(831)에 진감국사가 세운 절로 전한다. 원래는 건물이 수십 동에 이르는 큰 규모의 절로 ‘법당사’라고 불렀는데 세월이 흐르면서 폐사되었다. 경내에는 ○○○, 종각, 요사가 있다. ○○○은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. ○○○ 앞에는 5층석탑이 있지만 훼손이 심해서 그 형태를 잃고 있다.","a":"남원사미륵전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661702.jpg"},{"q":"고부읍성이 있는 성황산 북쪽 기슭에 자리하고 있는 탑이다. 주변에서 ‘○○○’라고 새긴 기와조각이 발견되어 이 절의 옛 터로 전하고 있다. 탑은 전체의 무게를 받치는 기단(基壇)을 2층으로 쌓고, 그 위로 3층의 탑신(塔身)을 올려놓은 모습으로, 꼭대기의 머리장식은 뒤에 따로 만들어 얹은 것이다. 각 기단의 4면과, 탑신부의 각 몸돌에는 모서리마다 기둥모양을 본뜬 조각을 두었다. 지붕돌은 밑면에 3단씩의 받침을 두고 있으며, 전체적으로 두터운 편은 아니지만 경쾌한 느낌은 떨어진다.","a":"용흥리해정사지석탑","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639509.jpg"},{"q":"○○○는 신라 문무왕 16년(676)에 의상대사가 세운 절로 여러 차례 고치고 새로 지어 세울 당시의 건물은 없다. 절 이름이 ○○○인 것은 절 뒤에 맑은 샘이 솟아오른다고 하여 붙인 것이다. ○○○은 조선 중기 때 고쳐 지어 오늘에 이르고 있다. 불계에서 영혼을 재판하는 곳으로 현대 사법기관과 마찬가지로 공정하게 영혼들을 재판하여 편히 잠들게 하였다고 한다.","a":"고성 옥천사 명부전","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664177.jpg"},{"q":"전북특별자치도 정읍시 이평면에 있는 ○○○의 법당 안에 모셔져 있는 높이 138㎝의 화강암으로 만든 불상이다. 민머리이며 목에는 3줄로 새겨진 삼도(三道)가 분명하게 나타난다. 얼굴 부분은 잘려진 것을 새로 붙여 원래의 모습을 알아보기 힘든 상태이다. 대좌(臺座)와 몸 뒤에 있는 광배(光背)를 불상과 함께 붙여서 조각하였는데 대체로 보존상태가 양호하다. 연꽃이 새겨진 대좌는 높이 31㎝로 하나의 돌로 만들었으며, 위와 아래에는 폭 4㎝의 띠를 둘러 경계를 지었다.","a":"백운암석불입상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661782.jpg"},{"q":"관촉사는 고려 광종 19년(968) 혜명이 창건한 사찰로, 절내에 들어서려면 이 석문을 통과하여야 한다. 다른 사찰에서는 찾아볼 수 없는 특이한 형태의 문으로 일명 ‘해탈문’이라고도 부른다. 문은 네모난 돌기둥을 양쪽에 세운 후, 양 기둥 뒤쪽으로 길쭉한 돌을 5개씩 쌓아 옆면을 이루게 하였다. 기둥 위로는 네모지고 넓적한 돌을 얹어 놓아 전체적으로 4각의 모습을 하고 있다. 관촉사가 건립된 후 참배객이 몰려드는 것을 막기 위해 동·서·남·북 4곳에 이러한 문을 두었는데, 그중 동쪽에 세운 이 문만이 유일하게 남아 있다.","a":"관촉사석문","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661015.jpg"},{"q":"조선 중종 14년(1519)에 기묘사화가 일어나면서 김대유가 관직을 버리고 내려와 지내면서 후진들을 교육하기 위해 세운 건물이다. 김대유의 호를 따라 ○○○라 이름 지었으며, 주세봉·조식·박하담 등과 토론과 이야기를 하던 곳이다. 규모는 앞면 3칸·옆면 2칸으로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 사방에 토담을 쌓고 문을 두어 그 안에 정자를 배치했다. 방 2칸과 부엌, 우물, 마루를 ㄱ자형으로 배열해 놓았다. ○○○ 밑에는 김대유의 신도비와 참봉 김용희가 쓴 중수기문이 있다.","a":"청도 삼족대","c":"시도민속문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658971.jpg"},{"q":"판식(板式)은 상하단변(上下單邊), 유계(有界), 상하내향흑어미(上下內向黑魚尾)이고 반엽(半葉) 7행 17자 67장(본문 65장, 발문 2장)이고 선장목판본이다. 표제는 “中禮文”이고 내용은 불교에서 수륙제(水陸齋)를 행하는 방법과 그에 딸린 의식을 자세하게 정한 불교 의례서로, ○○○ 의식문 54편이 수록되어 있다. 권미제에 이어 “水陸無遮 平等道場 一切時處 略設儀文”이란 제첨이 새겨져 있고 이어 “신사년 6월에 경상도 협천지(俠川地) 가야산 해인사에서 개판했다”는 간기가 있는데(辛巳年六月日 慶尙道俠川地伽倻山海印寺開板) 신사년의 연대는 정확히 알 수 없다.","a":"천지명양수륙재의찬요","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594715.jpg"},{"q":"이 ○○○는 서전(書傳) ｢순전(舜典)｣의 선기옥형도(璇璣玉衡圖)를 본 떠 목재로 만든 천체관측기구로서 북극출지(북극고도,즉 관측자의 위도)와 더불어 동지와 하지, 춘추분의 태양 거극도(북극으로부터 떨어진 각거리)에 대한 정보와 28수(宿)와 24방위, 12지(支) 등의 정보를 담고 있다. 그러나 이 ○○○는 환 제작형태나 각 환에 기록된 명문들로 볼 때 실제 천체관측용으로 만들어진 것이 아니라 교육용으로 제작된 것으로 보인다.","a":"혼천의","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593124.jpg"},{"q":"팔공산 동화사로 가는 길목의 왼쪽 골짜기에는 용수 마을이 자리하고 있다. 마을에는 직접적인 신앙의 대상물이 되고 있는 당산이 있는데, 여러 그루의 나무사이에 크고 작은 자연석을 둥글게 쌓아 올려 비교적 매끄러운 모습을 간직하고 있다. 이곳에서 마을의 안녕과 번영을 기원하는 제사를 지내는데, 제사비용은 마을 공동으로 마련하고, 마을 어른들이 모여 제관을 정하게 된다. 선출된 제관은 제사 당일 마을 앞 개울에서 목욕재개한 후 혼자서 제사를 올린다.","a":"용수동당산","c":"시도민속문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658106.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 지방에 세운 교육기관이다. 한국전쟁 때 기록을 분실하여 지은 시기를 정확하게 알 수 없으나, 조선 태조 7년(1398) 서본리에 처음 지었고 태종 18년(1418)에 지금 있는 자리로 옮겨 세운 것으로 보인다. 보수를 거듭하여 오늘에 이르고 있는데 건축 당시의 여러 건물은 불타 없어졌다. 현재는 제사 공간인 대성전, 교육 공간인 명륜당, 대문 격인 외삼문과 음식을 준비하는 곳인 주사가 남아 있다. 대지를 3단으로 나누어 앞면에는 교육 공간을 두고 뒤편에는 제사 공간을 배치하였다.","a":"예천향교","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662665.jpg"},{"q":"안동 권씨 33세손 권두희 선생이 지은 정자로, 조상의 얼을 받들고 고을의 번영과 화목을 기원하며 각지의 유학자와 학문적으로 교류하기 위해 지었다. 선생이 자주 정자에 올라 시를 읊고 즐겨 읍청(揖淸)이라 하였다. 정자는 산수(山水)가 매우 아름다운 적벽산과 백마산이 병풍처럼 둘러 있고 경호강이 굽이 돌아 맑은 모래사장을 이룬 곳에 위치해 있다. 앞면 5칸·옆면 2칸 규모로 지붕은 옆에서 볼 때 여덟 팔(八)자인 팔작지붕이며, 건물의 양옆에 누마루를 구성하였다.","a":"산청읍청정","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664681.jpg"},{"q":"훌륭한 유학자들의 위패를 모시고 제사지내며 지방백성의 교육과 교화를 담당하던 지방국립교육기관이다. 고려 충숙왕(재위 1313∼1330, 1332∼1339) 때 처음 지었다고 하는데, 원래 물태리에 있던 것을 조선 정조 3년(1779)에 교리로 옮겼다가 충주댐 건설로 인하여 현재의 위치로 다시 옮겨졌다. 지금은 대성전과 명륜당, 동재와 서재, 내삼문 등이 남아있다. 건물의 배치는 교육공간이 앞에, 제사공간이 뒤에 배치된 전학후묘의 형식을 하고 있다. 학생들이 모여 공부하는 강당인 명륜당을 중심으로 좌우에 학생들의 생활공간인 동재와 서재가 교육공간을 이루고 있다.","a":"제천 청풍향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638484.jpg"},{"q":"○○○ 소장 ○○○○○은 세로 215.5㎝, 가로 228.0㎝의 비교적 큰 화폭에 ○○○·관음 및 대세지보살상 3존 모두 입상형을 취한 도상이다. 화기에 의하면 조선시대 함풍(咸豊) 7년, 즉 조선 철종 8년(1857)에 조성되어 통도사(通度寺) 취운암(翠雲庵)에 봉안되었던 작품임을 알 수 있다. ○○○○○상은 보편적인 도상이라 할 수 있으나, 삼존 모두 입상형식은 조선 후기 괘불탱에 보이는 도량 강림현상의 입상불 외에 주로 고려 후기∼조선 전기에 조성된 ○○○내영 형식의 불화가 주를 이룬다.","a":"양산내원사아미타삼존탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642415.jpg"},{"q":"○○○○은 이산면 원리(院里, 지금의 휴천1동 속칭 구서원)에 1558년(명종3) 영천榮川군수 안상이 창건하고 강당을 경지당敬止堂, 동재를 성정재誠正齋, 서재를 진수재進修齋, 문을 지도문志道門, 대를 관물대觀物臺라 퇴계退溪 이황李滉이 명명命名했다. 1572년(선조 5) 묘우를 세우고 이황의 위패를 봉안하고 1574년(선조 7) 사액賜額을 받았다. 1614년(광해군 6) 현재의 위치에 이건하였으며 1871년 훼철되었다가 1936년 경지당과 지도문만 복원하였다.","a":"영주 이산서원","c":"시도기념물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016121917395400.jpg"},{"q":"향로란 절에서 마음의 때를 씻어준다는 의미를 가진 향을 피우는데 사용하는 도구를 말한다. 높이 23㎝, 입 지름 27.5㎝인 청동으로 만들어진 조선시대 향로로, 입 주위에는 넓은 테를 가진 전이 있으며, 안쪽으로 ‘의령수도사’라고 점선으로 새긴 글자가 있다. 향로 몸체의 둘레에는 4곳에 꽃 모양으로 창을 만들고, 그 안에 봉황을, 남은 공간에는 빈틈없이 덩굴무늬를 새겨 넣었다. 아랫부분의 받침대에는 문양이 없고, 그 형태가 몸체와 균형이 맞지 않으며, 조선 순조 16년(1816)에 보수하였다는 글씨이 새겨 있다.","a":"고성 옥천사 청동향로","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641482.jpg"},{"q":"이 탑은 1973년 경주경찰서 신청사를 준공할 때 기단부基壇部만 남겨두고 지붕돌 3개를 경찰서 정원으로 옮겨 보존해 오다가, 주민들의 꾸준한 요청에 의하여 1995년 원래의 위치인 이곳으로 옮겨 세우고 명칭도 지금의 이름으로 바꾸었다. 단층인 기단은 원래의 돌과 같은 크기로 새로 만들어 4개의 돌을 짜 맞추었는데 모서리기둥과 안기둥을 조각하였다. 그 위에 3층으로 몸돌과 지붕돌을 올렸다. 지붕돌의 밑면에 새긴 5단의 받침은 비교적 뚜렷하다. 탑을 다시 세우고 남은 돌들은 지금도 탑 서쪽에 그대로 보존되어 있어, 원래의 모습을 보다 확실히 알 수 있게 해주고 있다.","a":"경주남사리북삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662356.jpg"},{"q":"영광군 ○○○에 모셔져 있는 3구의 목조○○○○이다. ○○○는 각진국사(覺眞國師)가 처음 지었으며, 정유재란(1597) 때 화재로 소실되었고, 조선 현종 8년(1667)에 다시 지은 뒤 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 중앙의 석가○○○○은 매우 안정되고 삼매경에 빠진 듯한 고요한 분위기를 보여준다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리에는 상투 모양의 육계가 자그마하게 솟아있고, 머리 중간에는 반월형의 계주가 있다. 사각형의 얼굴에 눈, 코, 입이 사실적으로 묘사되어 있으며, 목에는 3개의 주름인 삼도(三道)가 선명하다.","a":"영광연흥사목조삼세여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640164.jpg"},{"q":"요산마을의 서남쪽에 있는 낮고 평평한 구릉에 있는 조선 태종때 사온서직장을 지낸 하현과 그의 아버지, 어머니의 무덤이다. 이 무덤 주변에서 가야의 토기조각들이 보이는 것으로 보아 이 일대가 오래 전부터 무덤자리로 쓰였음을 알 수 있다. 지대석·면석·갑석을 갖춘 8각형의 호석을 만들고, 그 위에 흙을 덮어 완성하였다. 특히 하현의 무덤은 갑석의 위쪽면 모서리가 반전된 귀를 가지고 있어 마치 석탑의 지붕돌(옥개석)과 같은 형태를 하고 있다. 무덤 앞에는 비석·상석·장명과 그 좌·우에 문인석이 있다.","a":"진주 수곡 팔각형 분묘군","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654935.jpg"},{"q":"원래는 승려들이 거주하였다고 전하는 건물이지만 현재는 조선 전기 문신인 이언적(1491∼1553) 선생의 묘소를 관리하기 위한 재실로 쓰고 있다. 그는 24세 때 문과에 급제한 뒤 이조정랑, 밀양부사를 거쳐 중종 25년(1530) 사간이 되었다. 그러나 김안로의 등용을 반대하며 벼슬을 버리고 산으로 들어가 성리학 연구에 전념하였다. 김안로가 물러난 뒤 홍문관교리, 직제학이 되었고 전주부윤으로 재임하면서 선정을 베풀어 그의 송덕비를 세우기도 하였다.","a":"포항 달전재사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658910.jpg"},{"q":"○○○은 곽재우 장군의 공로와 그의 덕을 기린 불망비(不忘碑)를 보호하기 위해 세운 것이다. 곽재우는 조선 선조 25년(1592) 임진왜란 당시, 왜적을 맞아 마음과 힘을 굳게 다진 뒤 전 재산을 털어 의병을 모았다. 스스로 의병대장이 되어 ○○지방을 시작으로 창녕, 합천, 성주 등지에서 왜적을 물리쳤다. 영조 15년(1739) 장군의 공로와, 나라와 민족을 사랑하는 덕을 추모하기 위하여 그 날의 싸움터였던 이곳에 불망비(不忘碑)를 세웠다.","a":"의령 보덕각","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663959.jpg"},{"q":"○○○○는 아메노모리 호슈(雨森芳洲, 1668-1755)가 편찬한 책으로 일본 에도시대부터 메이지시대에 걸쳐 일본에서 가장 널리 사용된 한국어 학습서이다. 연활자본 4권 4책의 완질본으로 전체는 67항목으로 구성되어 있으며, 각 항목별로 관련 한자 표제어 아래에 그 표제어를 한글로 설명하거나 그 용어가 들어가는 문장을 일본어와 한글로 나란히 기재하여 외국어 학습에 편리한 대역본의 형식을 취하고 있다.","a":"교린수지","c":"문화유산자료","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659411.jpg"},{"q":"○○○ 이순신 장군이 정유재란 때인 조선 선조 30년(1597) 10월에서 다음해 3월까지 머물면서 군량미 및 군수물자를 모아 전쟁에 대비하던 곳이다. 장군은 이곳에 돌로 남·서 길이 1㎞, 높이 2m, 폭 1m의 성을 쌓아 적의 배를 구별하고, 군자금을 모으기 위해 오가는 배들에게 1∼3석의 식량을 내어 놓고 통행첩을 받아가도록 하여 열흘만에 일만 석의 군량미를 비축하였다. 또한 이곳에서 무기와 배를 만들며 전열을 가다듬었다고 한다.","a":"고하도이충무공유적","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653965.gif"},{"q":"○○○○○은 요진 시대인 406년경에 처음으로 한역된 것으로 알려져 있으며‚ 부처의 40년 설법을 집약하는 정수를 담고 있는 경전이다. 화엄경과 함께 대승불교의 2대 경전의 하나로 줄여서 “법화경”이라고 한다. 이 경의 내용은 가야성에서 도를 이룬 부처가 세상에 나온 본뜻을 말한 것으로 쿠마라집(鳩摩羅什)의 한역에 송나라 때의 승려인 계환이 주해를 한 것이다. 수도사 소장 ○○○○○은 모두 7권7책으로 권 책수로는 전질이다. 전 7책중 제1책(제1권)만 다른 판본이다.","a":"묘법연화경 권1~7","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636516.jpg"},{"q":"○○○○○은 양식적으로 볼 때 1600년 전후에 조성된 것으로 추정되며, 규모가 작은 삼존불상의 협시보살로 조성된 것으로 보인다. 갸름한 타원형의 얼굴에 높이 솟은 보계, 부드러운 옷주름 등에서 형식화하기 시작하는 임진왜란 이후의 보살상과 차별성이 있다.","a":"서산간월암목조보살좌상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639304.jpg"},{"q":"○○○ 한개마을은 성산 이씨 집성촌으로, ○○○은 이국희(1868∼1939)가 지었다. ○○○이란 이름은 이국희가 조선왕조에서 마지막으로 실시한 소과에 합격하여 진사가 되었지만 벼슬은 하지 않았기 때문에 붙여진 것이라고 한다. 건물은 안채, 사랑채, 고방채 등으로 구성되어 있다. 사랑마당으로 들어서면 사랑채가 있고 사랑채 뒤로 안채가 새사랑채와 나란히 자리를 잡고 있다. 사랑채는 3칸 앞쪽에 툇마루를 들였고 뒤편 왼쪽에는 마루 1칸, 오른쪽에는 온돌방 2칸을 배치하였다.","a":"성주대산리진사댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658871.jpg"},{"q":"○○○는 조선후기 參奉을 지낸 漆原尹氏 尹淳學이 조부인 成均館 進士 尹尙義와 通政大夫 秘書監承을 지낸 부친 尹永達의 학덕을 기리고 후학을 양성하기 위해 1913년에 건립한 재실이다. 재실은 재사와 아래채 대문채로 구성하였는데 아래채는 대문채와 ㄱ 자형으로 연결되어 있다. 재사건물은 정면 5칸 측면 2칸반 규모의 겹집형식으로 앞쪽에만 툇간을 둔 전툇집이며 5량으로 가구하였고 처마는 섯가래만 쓴 홑처마에 지붕은 팔작지붕 형식을 취하고 있다.","a":"합천 동산재","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664111.jpg"},{"q":"조선 중기의 문신이며 시조작가인 농암 이현보(1467∼1555) 선생의 초상화로, 가로 105㎝, 세로 126㎝의 크기이다. 선생이 책상 앞에 앉아있는 모습으로, 「영정개모일기」에 그림에 대한 기록이 남아 있다. 이에 의하면, 순조 27년(1827) 선생의 초상화(보물로 지정되어 있음)가 망가질 것을 우려한 후손들이 이를 본 떠 다시 그려놓은 것으로, 추사 김정희의 소개로 소당 이재관이 분강서원에서 그렸다 한다. 유물 가운데 ○○○는 농암이 관직에 있을 때에 사용하던 관복 띠로서, 폭 3.5㎝이다.","a":"농암영정후사본및금서대","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640355.jpg"},{"q":"1920년경에 지은 집으로 원래는 초가지붕이었으나 1975년경 지붕개량사업 당시 기와지붕으로 바꾸었다. 마을 중앙부 끝 부분에 남서향으로 자리잡고 있으며 비교적 작은 규모이다. 앞면 3칸·옆면 3칸 규모이며, 가운데 봉당과 마루를 중심으로 왼쪽에 방 2칸·오른쪽에 부엌 1칸과 방 1칸을 두었다.","a":"영주수도리김정규가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663213.jpg"},{"q":"조선 중기의 무신인 원균(元均, 1540∼1597) 장군의 묘이다. 임진왜란 때 이순신이 투옥되자 그를 대신하여 삼도수군통제사가 되어 부산에 있는 적을 공격하던 중 칠천량해전에서 대파하여 전사하였다. 이후 1604년(선조 37)에 권율·이순신과 함께 선무 1등공신으로 벼슬이 높여졌다. 묘역은 부인 파평 윤씨(坡平尹氏)와 합장한 원형 단분(單墳; 하나의 봉분)의 형태이다. 1981년 후손들이 묘역을 정비하면서 원형이 상당부분 변형되었고, 또한 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)와 문석인을 제외한 모든 석물들이 1981년에 새롭게 조성되었다.","a":"원균장군묘","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646118.jpg"},{"q":"충청남도 당진군 면천면 상왕산 ○○○의 우뚝 선 암벽에 돋을새김 한 높이 3.5m의 불상이다. 고려말에 무학대사가 사찰을 둘러보니 기이한 바위가 빛을 내고 있어 심상치 않게 여겨 여기에 불상을 조각해 나라의 평안을 빌었다는 전설이 전해진다. 머리에는 상투 모양의 머리묶음을 표현하였고, 얼굴은 윗부분이 넓고 밑부분이 갸름한 형상이며 신체에 비해 큰 편이다. 눈·코·입은 길고 큼직한데 다소 서투르게 표현하여 전반적으로 둔한 느낌을 준다. 세련미는 부족하나 친근함이 드러나는 이런 형태의 얼굴은 고려시대부터 유행하던 충청도 지방의 일반적인 불상 양식이다.","a":"영탑사약사여래상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639202.jpg"},{"q":"1937년 도동 축항공사 때 바다에서 인양한 비석이다. 당시 2개가 있었으나 현재는 1개만이 남아있다. 비석은 가로 70cm, 세로 80cm의 부정형 현무암편으로서 평탄면에 2단으로 각기문(刻記文)을 새겼다. 상단기문은 가로 31cm, 세로 33cm 넓이에 10행으로 새겼고, 하단기문은 가로 18cm, 세로 40cm 넓이에 10행으로 새겼다. 글자의 크기는 2cm 내외의 작은 글자이다. 이 ○○○은 ‘신묘오월(辛卯五月)’이라 새겨져 있어서 조선 숙종 37년으로 추정되는 신묘년의 기록으로 추정된다.","a":"울릉도도동리신묘명각석문","c":"문화유산자료","nc":"","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663317.jpg"},{"q":"신도(神道)란 죽은 사람의 묘로(墓路)를 뜻하며, ○○○란 임금이나 고관의 업적을 기리기 위하여 무덤 앞 또는 무덤으로 가는 길목에 세운 비석을 가리킨다. ○○○는 중국 한대부터 종2품 이상의 관직에 있었던 사람의 무덤 근처나 큰 길가에 세우던 돌비로서 한나라 양 진의 <고대위양공지○○○>에서 기원한 것이라고 한다.우리나라에서는 임금이나 고관의 무덤 동남쪽에 남쪽을 향하여 세운다.","a":"심즙 신도비","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637085.jpg"},{"q":"겸재 하홍도 선생의 위패를 모시는 사당이다. 조선 중기 학자인 하홍도(1593∼1666)는 성균관 유생으로 동료들의 존경을 받았으나, 광해군의 실정으로 벼슬을 단념하고 고향으로 돌아와 학문 연구와 후진양성에 힘썼다. 천문학에도 조예가 깊었으며 저서로는 『겸재집』이 있다. ○○○는 선생이 도학을 연구하고 학문을 강의하던 곳으로 당대의 현인인 미수 허목, 약천 남구만 등이 지내기도 한 곳이다. 여기에는 미수 선생의 친필을 보관하고 있으며 해마다 음력 3월 10일에는 영남 사람들이 선생의 위패를 모시고 제사를 지낸다.","a":"하동 모한재","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664397.jpg"},{"q":"약사전에서 발견되었다고도 하고 다른 곳에서 가져왔다고도 하여 정확한 출처는 알 수 없다. 다만 표면에 붉은 황토가 아직까지 남아있는 것으로 미루어 어느 시기에 목이 잘린 채로 땅속에 매몰 되었던 것으로 추정된다. 발견 과정에서의 훼손인지 왼쪽 어깨와 오른손 등, 왼손 윗부분 등 군데군데 표면이 떨어져 나갔다. 전체 높이 80cm의 작은 불상이지만, 둥글고 부드러운 윤곽선에 양감 있는 신체의 전체적인 비례가 조화로운 점 등에서 통일 신라 불상의 양식을 엿볼 수 있다. 나발의 머리 정상에는 낮은 육계(肉髻 ; 상투 모양의 머리묶음)가 넓게 표현되어 있다.","a":"가평 대원사 석조비로자나불좌상","c":"문화유산자료","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660296.jpg"},{"q":"1936년 일제 강점기에 지은 대구 남산정 공립보통학교의 강당 건물로 현재까지 당시의 건물 유형과 특징이 잘 보존 유지되고 있다. 전체적으로 붉은 벽돌쌓기 단층건물로 지붕은 4각형의 석면 슬레이트를 마름모꼴로 덮었으며, 남쪽 정면 출입구의 현관을 중심으로 좌우 대칭을 이루고 있다. 평면은 장방형으로 4면에 출입구를 두고 있으며 서쪽 정면 출입구 맞은 편에 무대(강단)와 준비실을 두고 있다. 벽면은 콘크리트 줄기초 위에 붉은 벽돌을 쌓아 벽체를 구성하였으며 창문이 설치되는 부분에 벽돌을 1단 들여쌓기하여 벽면을 분할하였다.","a":"남산초등학교강당","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636926.jpg"},{"q":"귀신사는 통일신라 문무왕 16년(676) 의상대사가 창건한 사찰로, 절안에 이 3층 석탑이 자리하고 있다. 바닥돌 위에 여러 장의 돌을 짜맞추어 기단(基壇)을 만들고 그 위에 3층의 탑신(塔身)을 올렸다. 탑신의 몸돌은 모서리에 기둥 모양을 선명하게 조각하였다. 지붕돌은 얇고 넓으며 처마가 거의 평행을 이루다 네 귀퉁이에서 살짝 들려 있다. 꼭대기에는 머리장식을 받치던 네모난 받침돌만 남아 있다. 얇고 넓은 지붕돌의 곡선미와 여러 개의 돌을 짜맞추어 조성된 수법 등으로 보아 백제 석탑 양식을 이어받은 고려시대의 석탑으로 추측된다.","a":"귀신사석탑","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639462.jpg"},{"q":"삼불암 아래의 비각 안에 있는 2기의 비로, 조선 왕조의 개창자인 태조 이성계와 관련된 유적지임을 기념하기 위해 의정부 찬정거 윤정구가 건립한 것이라 한다. 왼쪽 비에는 ‘남○○○○○적비(南海錦山靈鷹紀蹟碑)’, 오른쪽 비에는 ‘○○○○○시성비(大韓中興公德視聖碑)’라 새겨 비의 이름을 밝히고 있다. 광무 7년(1903)에 세웠다.","a":"남해 금산영응기적비대한중흥공덕축성비","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664607.jpg"},{"q":"봉림사터에 남아 있던 탑으로, 일제시대에 반출되었다가 되찾은 것이다. 관리 소홀로 많이 부서진 것을, 1960년 ○○교육청에서 지금의 자리로 옮겨 세웠다. 탑의 무게를 받치는 기단(基壇)은 2층이었을 것으로 보이나, 여러 차례 옮겨 다니면서 많이 깨져나가 위층 기단의 일부만 남아있다. 3층을 이루고 있는 탑신부(塔身部)는 비교적 잘 보존되어 옛 모습을 쉽게 읽어낼 수 있다. 1층 몸돌은 두 조각으로 깨져 있던 것을 붙여 놓았는데 네 모서리에 기둥모양을 새긴 것 외에는 꾸밈이 없다.","a":"창원 봉림사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641379.jpg"},{"q":"신라 선덕여왕 12년(643)에 자장율사가 창건한 ○○○에 모셔진 보살상으로, 현세에서 자비로 중생을 구제한다는 의미를 지닌 관음보살을 표현한 작품이다. 손이 왼쪽과 오른쪽 어깨에 각각 3개씩 모두 6개가 달려 있어 6수(六手) 관음보살로 불리고 있다. 머리에 쓰고 있는 높은 보관(寶冠)에는 꽃무늬와 불꽃 모양의 구슬이 새겨져 있으며, 앞면에는 작은 부처가 새겨져 있다. 양 어깨에는 땋은 것 같은 두가닥의 머리카락이 늘어져 있고, 노출된 가슴에는 구슬장식이 달린 목걸이가 길게 표현되었다. 6개의 손목에는 정교한 팔찌가 끼워져 있다.","a":"월정사육수관음상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637986.jpg"},{"q":"○○○는 봉수산의 동북계곡에 있는 절로, 기록에 따르면 신라 진성여왕 원년(887)에 도선국사가 세웠다고 전한다. 이후 여러 차례 고쳐 지었으며 임진왜란 때 폐허가 된 것을 인조 24년(1647)에 다시 세우고 정조 18년(1794) 고쳐 세웠다. 이때까지는 절 이름이 석암사였으나 고쳐 지으면서 ○○○로 이름을 바꾸었다. 그 뒤 고종 7년(1891) 법당과 요사를 고쳐 지어 오늘에 이르고 있다.","a":"봉곡사대웅전및고방","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661440.jpg"},{"q":"조선 중기의 문신이자 문장가인 송천(松川) 양응정(1519∼1581) 선생의 묘소이다. 중종 35년(1540)에 생원시에 장원급제하고, 명종 7년(1552)에 문과에 급제하여 벼슬길에 나아간 뒤 홍문관 부수찬, 예문관, 승정원 등을 거쳐 대사성에 이르렀다. 당시부터 싹트기 시작한 당쟁의 희생양이 되어 고향으로 돌아가 후진양성에 전념했던 선생은 제자 송강 정철에게 ‘궁리의 뿌리없이 먼저 문자에 능한 자는 있을 수 없다. 나 역시 늦게나마 그것을 깨닫고 후회하고 있으나 때는 이미 늦었다.","a":"양송천묘역","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645747.jpg"},{"q":"○○○○는 사찰 입구에 설치해 두는 것으로, 절에 행사나 의식이 있을 때 이곳에 당이라는 깃발을 걸어둔다. 이 깃발을 매달아두는 길쭉한 장대를 당간이라 하며, 이를 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 있으나 대부분은 두 기둥만 남아 있다. 이 ○○○○는 만덕동에서 제1 만덕터널로 들어가는 진입로 아래의 ○○○터에 서 있다. 두 기둥 중에서 한쪽 기둥만 남아 있으며, 기둥 옆으로는 당간의 받침돌로 보이는 작은 돌이 놓여 있다.","a":"만덕사지 당간지주","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636640.jpg"},{"q":"이 사당은 전주 이씨의 시조인 이한(李翰)과 그 부인의 위패를 모신 곳이다. 이한은 신라 때 ｢사공(司公)｣이라는 높은 벼슬을 지냈고, 그 부인은 경주 김씨이다. 조선을 세운 태조 이성계는 이한으로부터 21대 후손이다. ○○○는 조선 영조 47년(1771)에 세워, 영조가 세손(정조)으로 하여금 쓰도록 한 시조 내외의 위패를 봉안했다. 철종 5년(1854)에 경기전과 함께 보수해 오늘날의 모습을 갖췄다. ○○○는 경기전과 함께, 전주가 조선왕조의 발원지임을 상징하는 곳이다.","a":"조경묘","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639382.jpg"},{"q":"심암 조두순이 살았다고 전하는 집이다. 조두순(1796∼1870)은 조선 후기 문신으로 조선 순조 26년(1826)에 장원급제하여 벼슬길에 올랐다. 그 뒤 여러 자리를 거쳐 영의정까지 이르렀으며, 순조·헌종·철종·고종 등 여러 왕을 섬겼다. 현재 가옥은 각각 ㄱ자형 안채와 행랑채, 대문이 딸린 다른 건물 1동이 ㅁ자형을 이루고 있다. 정면은 행랑채·대문 건물로 앞면 6칸·옆면 1칸 규모이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 안채 지붕도 팔작지붕이며, 건물 중앙에 마루가 있다.","a":"이한직가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661352.jpg"},{"q":"높은 언덕에 위치하고 있는 집으로 18세기 중엽에 지었으며 안채, 사랑채, 행랑채로 구성되어 있다. ㄱ자형의 안채와 一자형의 사랑채, 행랑채가 모여 있어서 전체적으로 ㅁ자를 이루고 있다. 안채는 안쪽 꺾이는 곳에 긴 부엌이 있고 오른쪽에 안방과 대청이 있으며, 옆으로 건넌방이 있다. 전체적으로 툇마루를 깔아 대청과 연결하고 있다. 사랑채는 다른 건물보다 높은 곳에 배치되어 있으며, ‘대성헌’이라는 현판이 달린 대청과 2칸의 사랑방이 있다. ‘대성헌’이란 성주산을 대하고 있다는 뜻이며, 전면에는 반칸폭의 툇마루를 달았다.","a":"양동대성헌","c":"시도민속문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658545.jpg"},{"q":"사적기에 따르면, ○○○은 신라 성덕왕 19년(720)에 창건되어 고려시대 태조 1년(918) 證通국사, 선종 1년(1084) 導生僧痛, 예종 2년(1107) 慈淨國尊에 의해 각각 중수가 이루어졌다. 조선시대는 세종 31년(1449) 信眉선사가 중수했고, 영조 11년(1735)에 소실된 암자를 卓融선사가 재창하였으며, 순조 3년(1803) 就俊師가 중수했다고 전한다. ○○○○○는 1795(淸 乾隆 60)년에 제작되었다. 이 불화는 원래 ○○○ 대웅보전에 봉안되었으나 후에 ○○○으로 移安되어 이 암자의 중심전각인 극락보전의 향우측 벽면에 현괘되어 있다.","a":"보은 법주사 복천암 신중도","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638948.jpg"},{"q":"이 ○○○는 공처럼 둥근 몸체의 위아래에 직립한 구연과 굽을 가지고 있는 조선후기의 원호(圓壺)로 속칭 ‘달항아리’라고도 한다. ‘달항아리’의 성형 과정이 까다로워 몸체를 둥글게 유지하고 있는 사례가 드문 점을 고려하면 본 항아리는 미세하게 좌우의 불균형상태를 이루고 있음에도 우수한 작품으로 볼 수 있다. 본 항아리는 백색점토로 구성되어 전체적으로는 미색의 분위기를 풍기고 있지만 부분적으로 미세한 철분 알갱이가 섞여 있는 부분은 분홍색을 띤다.","a":"백자호","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637237.jpg"},{"q":"이서를 주벽으로 하여 심구령·안성·소연·소산복·이당 등 6현의 위패를 모시고 있는 서원이다. 송강 이서(1332∼1410)는 고려말∼조선초의 문신으로 공민왕 6년(1357) 문과에 급제하여 여러 벼슬을 거쳤으나, 정치가 문란한 것을 보고 관직을 버리고 고향으로 돌아갔다. 그 뒤 태조 1년(1392)에 이성계 추대에 참여하여 조선 개국공신 3등에 올라 안평군에 봉해졌으며, 영의정까지 이르렀다. 이 서원은 정조 13년(1789)에 지금 있는 자리로 옮기면서 ○○○○으로 이름을 바꾸었다.","a":"호암서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661673.jpg"},{"q":"○○○ 소장 ○○○○○’은 복장에서 발견된 발원문에 1671년(현종 12년, 순치 28년) 조선 후기 조각장인 응혜(應慧)와 계찬(戒贊)에 의해 아미타삼본불의 협시보살로 조성된 것으로 기록돼 있어 17세기 불상연구에 중요한 자료로 평가됐다.","a":"삼광사 목조보살좌상","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643341.jpg"},{"q":"고려 후기에 기와를 굽던 터이다. 조사 결과 3개의 터를 발견했는데 구조는 터널식으로 파서 만든 굴가마로 되어있다. 기와 조각 외에 다른 유물은 발견되지 않았고 조각의 대부분은 빗살무늬와 생선뼈무늬를 띠고 있다. 1호 요지는 전체 길이가 약 9m로 천장부분에 약간 손상이 있을 뿐 그 외는 완전하다. 2호 요지는 가장 먼저 발견된 곳으로 1호 요지 사이에 3호 요지를 두고 남동쪽에 있다. 전체 길이는 5.6m로 천장 일부분에 손상이 있을 뿐 상태가 좋은 편이다. 3호 요지는 1호와 2호 요지 사이에 있다.","a":"영주용혈리와요지","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640998.jpg"},{"q":"조선 후기 의병대장인 정환직(1843∼1907)과 그의 큰아들인 정용기(1862∼1907)의 애국정신을 기리기 위해 묘 근처에 세운 재실이다. 정환직은 고종 25년(1888) 의금부 의금도사를 지냈으며 광무 3년(1899) 시찰사, 도찰사겸 도포사를 역임하고 그 뒤 중추원 의관을 지냈다. 그의 아들 용기는 혜민원 총무를 거쳐 민영환 등과 함께 독립회와 만민회에 참여하고 보안회 국채보상운동에 회장으로서 적극 참여하였다.","a":"영천충효재","c":"시도기념물","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654532.jpg"},{"q":"○○○ 극락전에 모셔져 있는 ○○○ 불상이다. 오른손을 어깨 위로 들고, 왼손을 무릎에 둔 채 각각 엄지와 중지를 맞댄 ○○○불 특유의 설법인(說法印) 손갖춤을 맺었다. 양손은 따로 만들어 끼워 넣었다. 전체 높이가 138cm에 이르러 조선 후기에 제작된 불상 가운데 중형에 속하며, 상체를 약간 앞으로 내밀어 구부정한 자세를 취하고 있다. 정수리와 머리 중앙에 있는 큼직한 상투 매듭 구슬, 사각형의 얼굴과 신체 구성, 상체를 뒤로 젖히고 머리를 약간 앞으로 내민 모습, 폭이 넓고 단순한 옷주름 형태 등에서 조선 후기 불상의 특징을 잘 보여준다.","a":"현등사목조아미타좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2227640.jpg"},{"q":"전형적인 조선 후기의 상류주택이다. 원래는 안채와 사당 등이 모두 갖추어져 있었으나 지금은 사랑채와 행랑채만이 남아 있다. 행랑채는 一자형으로 중간에 대문을 냈으며, 사랑채 역시 一자형으로 고종 8년(1871)에 세웠다. 가운데 대청을 중심으로 양쪽에 온돌방을 두었다.","a":"해남정명식가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658355.jpg"},{"q":"영조 41년(1765년) 성황산에서 이곳으로 옮겨와 1914년 부군제 실시에 따라 정읍군에 편입될때 까지 고부관아가 있었던 곳으로 동학농민혁명의 발단이 되었던 1894년 1월 10일 고부봉기때 전봉준을 중심으로 한 농민군이 점령하여 탐관오리를 몰아냈던 역사적 현장이다. 고부관아는 고부초등학교가 들어서면서 관아건물은 전부 철거되고 현재에 이르고 있으며, 이는 전통문화유산과 동학농민혁명의 역사적 사실을 왜곡하고 말살하려는 일제의 만행을 여실히 보여주고 있다. 운동장 한켠에 보이는 초석, 기단석 등 석조물이 이곳이 역사적 현장이었음을 보여주고 있다.","a":"고부관아터","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653852.jpg"},{"q":"○○○는 1722년 초창이후 수차례 보수를 거쳐 1922년 중창된 건물로서 건축 공간구성의 위계성과 구조가 특이할 뿐만 아니라 1908년 백산 안희제 선생이 본 건물에 창남학교를 설립하여 문명개화를 이끌 인재를 양성한 역사성이 있어 문화유산자료로 지정되었음","a":"의령 상로재","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666630.jpg"},{"q":"조선시대 고을의 공무를 수행하던 관아건물로서 현종 8년(1667)에 처음 지었으며, 숙종 25년(1699)에 수리한 것으로 전해진다. 앞면 7칸·옆면 4칸 규모이며，지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 가운데의 오른쪽 6칸에 대청이 있고 왼쪽 4칸은 온돌방이다. 외벽은 사방 전체에 같은 형태의 문이 달려있으며, 앞면 가운데 1칸과 뒷면 왼쪽에 출입문을 달았다. 전체적으로 간결하면서도 앞면을 7칸으로 꾸며 위엄있는 건축형태를 갖추고 있어 조선시대 관아건축의 성격을 잘 나타내고 있다.","a":"김제동헌","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639460.jpg"},{"q":"○○○은 춘천관아 건물인 문소각(聞韶閣)을 신축할 때 내삼문(內三門)으로 함께 건립되었다. 고종 27년인 1890년 춘천관아에 이궁(離宮)이 설치되면서 ○○○은 이궁의 내삼문으로 사용되었다. 한국전쟁으로 인한 문소각 소실과 강원도청사 건립으로 몇 차례 이전되어 있던 것을 2013년 4월 이 자리에 이전을 완료하였다. 현판글씨는 조선후기 명필이었던 송하옹(松下翁) 조윤형(曺允亨)이 쓴 것이다. 정면 3칸, 측면 2칸 규모의 맞배지붕으로 내삼문의 전형인 솟을대문 양식을 온전히 갖추고 있다.","a":"위봉문","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637826.jpg"},{"q":"이 책판은 범어사의 창건에 관한 기록을 새긴 목판으로 모두 3종으로 되어있다. 이 3종류의 문화유산은 모두가 범어사의 창건과 유래, 중창의 과정, 그리고 가람의 위치에 관한 내용을 담고 있다.『○○○○○』은 동계라는 사람의 기록으로 쓰여있지만, 나머지 두 종류는 그 저자가 확실하지 않다. 오래된 목판으로, 절의 창건과 관련된 귀중한 역사자료로 평가된다.","a":"범어사기·범어사창건사적·범어사고적판","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636661.jpg"},{"q":"민영휘(閔泳徽)의 묘소를 관리하기 위해 묘 가까이에 세운 묘막이다. 조선 후기에 지은 건물로 ㄱ자인 안채와 ㄴ자인 사랑채가 배치되어 전체적으로 ㅁ자 평면을 이루고 있다. 안채는 대청마루를 중심으로 왼쪽으로 웃방·안방·부엌을 두었고 오른쪽에는 건넌방을 배치하였다. 부엌쪽은 옆면의 지붕선이 사람 인(人)자 모양인 맞배지붕이지만 건넌방쪽은 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 사랑채는 광·방 2칸·부엌으로 구성된다. 지붕은 안채와 마찬가지로 한쪽은 맞배지붕, 다른 한쪽은 팔작지붕으로 되어 있다. 가옥 전체를 흙담으로 처리하고 기와를 얹었다.","a":"춘천민성기가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660456.jpg"},{"q":"충청남도 서산시 운산면 ○○○에 있는 불상으로, 1970년대 지금의 위치에서 1㎞ 떨어진 용장천 정비사업 때 하천에서 발견되어 현재의 위치로 옮긴 것이다. 전해오는 이야기에 의하면 이 냇가에서 5㎞ 쯤 거슬러 올라간 상류에 2구의 불상이 있었는데, 그 중 하나가 떠내려온 것이라고 하나 정확하지는 않다. 화강암으로 얼굴과 손등을 조각했으나 옆과 뒷면에는 거친 못 자국이 남았고 목이 부러져 있던 것을 접착하였다. 사다리꼴의 얼굴에 관을 쓰고 여기에 작은 부처를 새겼는데 심하게 닳아 있다.","a":"서산여미리석불입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639223.jpg"},{"q":"○○○란 한 인물의 행적을 기리고, 그의 옛 자취를 밝혀 후세에 알리고자 세우는 비로, 이 비는 조선 중기의 문신인 ○○○ 선생을 기리고 있다. 우암 ○○○ 선생은 ○○ 지방에서 출생한 조선의 대유학자이다. 그의 유학사상은 이율곡의 학통을 계승하여 기호학파의 주류를 이루었으며, 조선 인조 대 부터 숙종 대에 이르는 4대에 걸친 노론의 대표로서 정계에서 크게 활약하였고, 뛰어난 학식으로 많은 학자를 길러내기도 하였다. 비는 현재 비각 안에 보존되어 있으며 네모반듯한 받침돌 위로 직사각형 비몸을 올리고 지붕 모양의 머릿돌을 갖춘 모습이다.","a":"옥천 송시열 유허비","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649787.jpg"},{"q":"형태는 저지(楮紙)에 목판본(木版本) 선장(線裝)으로 선덕 6년 신해, 즉 조선 세종 13년(1431) 11월에 밀양에서 남송본을 번각하여 간행한 것이다. 제33권에서부터 제40권까지 8권 1책이며, 반곽의 크기는 24.6cm×25.8cm이다. 내용은 남송 때에 채몽필이 두보의 시에 대한 여러 주석을 모아 편집하여 간행된 판본을 들여와 번각한 것이다. 이 책이 간행된 뒤로 약 40여 년이 지나 성종 때에 비로소 두보의 시가 언해되기 시작하는데, 이처럼 성종 때 『두시언해』가 나오게 된 데에는 세종 때 이 책이 간행되어 널리 퍼졌기에 가능한 것이었다.","a":"양산 대성암 집주두공부초당시","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642394.jpg"},{"q":"유회당 권이진(有懷堂 權以鎭,, 1668~1734)이 원래 그 선인의 묘를 지키기 위하여 1715년(숙종 41)에 건립한 건물로 알려져 있으나 후에는 그의 후손들과 후학의 교육장소로 활용되어 왔다. ○○○을 중심으로 앞쪽에 사당건물로 사용했던 ○○○, 뒤쪽에 ○○○이 자리잡고 있다. ○○○은 정면 5칸, 측면 3칸으로 평면을 구획한 후, 양쪽 툇간 뒤로 2칸씩을 덧붙여 ㄷ자형 평면을 이루고 있는 비교적 규모가 큰 건물이다. 5칸 중 전퇴가 달린 좌측 3칸에 불당을 만들고 우측 2칸은 부엌이다.","a":"여경암(부)거업재산신당","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637205.jpg"},{"q":"조선 광해군 때의 문신인 내암 ○○○ 선생 관련 고문서 82점과 문집외 10종류 16권이다. ○○○은 선조 6년(1573) 황간현감으로 재직하면서 많은 선행을 베풀었으며, 임진왜란이 일어나자 합천에서 의병을 모아 왜군을 물리쳤다. 선조 35년(1602) 대사헌으로 승진하고 그 후 좌참찬, 우의정, 좌의정, 영의정을 지냈다. 그러나 인조반정 때 집권 서인들에게 억울하게 죽임을 당하였다. 순종 2년(1908)에 명예가 회복되어 관직이 복구되었고, 후에 매천 황현과 단재 신채호는 ○○○을 실천하는 개혁적 인물로 평가했다.","a":"정인홍 관계 문적","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642261.jpg"},{"q":"임진왜란 때 수영성을 지키며 왜적과 장렬히 싸우다 순절한 25명의 의로운 충절을 기리고 있는 제단이다. 조선 선조 25년(1592) 임진왜란이 일어나자 경상좌수사로 있던 박홍은 성을 버리고 달아났다. 이 때 수병(守兵)과 성민(城民) 25인이 성문 밖의 선서바위에 모여 피로써 맹세한 후, 바다와 육지에서 적을 상대로 7년간 대항하였다. 이러한 사연은 광해군 원년(1609) 지방민들의 청원으로 알려지게 되어, 동래부사 이안눌이 이 때의 일들을 모아『정방록』을 만들고, 이들의 집 문에 ‘의용(義勇)’이라는 두 글자를 써붙여 그 뜻을 기리도록 하였다.","a":"25의용단","c":"시도기념물","nc":"","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2022040418093800.jpg"},{"q":"○○○은 정경부인황씨(貞敬夫人黃氏) 묘각(墓閣)이다. 이 ○○○에 대한 기록은 ‘○○○기(望楸亭記)’과 ‘○○○중수기(望楸亭重修記)’, ‘○○○팔명 병서(望楸亭八銘 幷序)’ 등을 통하여 건립연유와 초창이후 중수연대를 확인할 수 있다. 대사헌 ·호조참판 등을 지낸 송월당(松月堂) 박호원(朴好元: 1527~1584)은 돌아가신 어머니 황씨를 위해 박씨 3대묘가 있는 이곳에 장사하고 3년을 시묘하였다. 이때 기거할 수 있는 규모가 작은 건물을 지었는데, 이 집의 당호를 ○○○으로 한데서 유래하며, 자손이 부모에 대한 추모(追慕)의 뜻이 담겨 있다.","a":"산청 망추정","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102515182600.JPG"},{"q":"○○○ 삼성각으로 오르는 계단 옆 화단에 있는 ○○이다. ○○은 곡물을 가는데 쓰이는 용구로 위·아래 두 짝으로 구성되어 있다. 지름 69㎝, 두께 20㎝의 화강암으로 되어있으며, 부드러운 곡선으로 잘 다듬어 놓았다. 현존하는 대부분의 ○○은 윗돌만 있으나, 이 ○○은 윗돌과 아랫돌이 모두 남아 있다. 정확한 제작년도는 알 수 없으나 전체적인 양식으로 보아 조선시대 후기에 만든 것으로 보이며, 보통의 ○○보다 2배 정도 규모가 크다.","a":"강화 보문사 맷돌","c":"시도민속문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2018112211071000.jpg"},{"q":"○○○란 바위나 동굴의 벽면에 기호나 물건의 모양을 새겨 놓은 그림을 이른다. 이 ○○○는 경주 평야를 가로지르는 두 하천이 만나는 곳의 북쪽 바위벽에 그려진 것이다. 선사시대의 것으로 추측되는 이 그림은 강물에서 약 15m 높이의 수직 절벽 윗부분에 가로 약 2m, 세로 약 9m되는 범위에 새겨져, 추상적이고 기하학적으로 표현되어 있다. 모두 27점이 확인되었는데, 기하문 8점과 검과 창의 요소를 갖춘 그림 11점, 발자국 4점, 여성기(女性器) 3점, 배 1점, 그외 동물모습과 해석이 어려운 그림 등이 있다.","a":"경주석장동암각화","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654561.jpg"},{"q":"현재 ○○○ 독성각에 봉안되어 있는 이 상은 석조(石造) ○○○으로 전체 높이가 71cm인 소형 불상이다. 독성은 남인도 천태산에 거주하며 부처님의 수기를 받고 정신하는 나한 중의 한 분으로서 독성수(獨聖修) 또는 독성존자(獨聖尊者)라고도 한다. 원래 독성이라는 것은 홀로 인연의 이치를 깨달아서 도를 이룬 소승불교의 성자들에 대한 통칭이었으나 홀로 깨친 이라는 의미에서 흔히 나반존자를 독성이라고 부른다.","a":"도선사 석 독성상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590631.png"},{"q":"○○○은 조선 선조와 인조 때 활동하였던 풍암 김덕보(1571∼?)가 지은 정자로 ‘풍암’이라는 이름은 그의 호를 따서 붙인 것이다. 김덕보는 임진왜란 때에 큰형 덕홍이 금산싸움에서 죽고 의병장으로 크게 활약하던 작은형 덕령까지 억울하게 죽자, 이를 슬퍼하여 무등산 원효계곡을 찾아와 학문을 연구하며 평생을 살았다. 후에 의열사에 신주를 모셨다. ○○○은 앞면 2칸·옆면 2칸 규모로 이루어져 있다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄고 ‘○○○사’라고 쓴 현판이 걸려 있다.","a":"풍암정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659610.jpg"},{"q":"○○○○은 가은읍 전곡리 마을 중간쯤 전망이 아주 좋은 곳에 뒷산을 등지고 남향으로 위치하며, 강학과 제향공간이 각기 별도의 곽을 이루며 앞뒤로 배치하고 있다. 고종 8년(1871) 서원 훼철 당시 사당만 철거되고 강당과 동재는 존치되었으며 강당은 당시의 모습이 비교적 잘 남아 있다. 강당의 천장은 양측 청방 간 상부의 종보와 종보 사이에 종보 폭으로 길게 설치하였고 반자꾸밈은 반자대를 도리방향으로 길게 걸치고 그 사이에 반자판을 끼워 독특한 천장 구성을 이루고 있는 등 건축적 가치를 살필 수 있다.","a":"소양서원","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663592.jpg"},{"q":"○○○은 조선 광해군 9년(1617)부터 12년(1620) 사이에 지어진 궁궐로 임금이 항상 머무르던 곳이 아니라 본궁을 떠나 잠시 머무르던 이궁이다. 광해군 10년(1618)에 지어진 ○○○은 ○○○의 정전으로, 임금이 신하들의 조례를 받고 공식적인 행사를 하던 곳이다. 그러나 1910년 일본인들에 의해 강제로 철거되어 1926년 조계사로 옮겨 세워졌다가 현재는 동국대학교 안의 정각원이라는 법당으로 쓰이고 있는데, 내부가 불교 의례를 행하기에 알맞게 변형되어 있다. 앞면 5칸·옆면 4칸 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕이다.","a":"경희궁 숭정전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636098.jpg"},{"q":"이 건물은 조선 영조(英祖) 12년(1736)에 세워졌으며, 함안조씨 16대손 증 형조판서 (贈 刑曹判書) 조지(趙址)의 맏아들인 조수도(趙守道)와 그의 아들 조함수(趙咸遂), 조지의 계자(繼子) 조동도(趙東道), 그의 아들 조함신(趙咸新)을 위한 재실(齋室)이다. 건물의 동편에는 청송 입향조(入鄕祖)인 조지(趙址)와 그의 계자 조동도(趙東道)를 위한 묘우와 유생들이 강학하던 강당이 있었으나, 고종 5년(1868) 서원 철폐령으로 훼철되고 사당은 우모정(禹摹亭)으로 개액(改額)하여 현존하고 있다.","a":"금대정사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640864.jpg"},{"q":"이 집은 효자로 유명한 백낙중(白樂中)이 살던 곳이다. 고종 황제는 그의 효행을 높이 사서 승훈랑 이란 벼슬을 내렸다. 백낙중이 죽은 후 그 효심을 널리 알리기 위하여, 그의 호 인재(忍齋)에서 <인(忍)> 자를 따서 집 이름을 <○○○>이라 했다. 솟을대문에도 백낙중이 효자임을 표창하는 현판을 걸어 놓았다. ○○○은 전주 한옥보존지역의 대표적인 건물로 한말 건축 기술을 계승한 전통 양식의 건물인데, 조선왕조 붕괴 후 궁중건축양식이 상류층 가옥에 도입된 전형적인 예이다.","a":"학인당","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658295.jpg"},{"q":"이 탑은 ○○○의 대웅전 계단 아래쪽 마당에 위치한 ○○○○으로 원래는 요사체 앞쪽에 있던 것을 현 위치로 옮겨 놓은 것이다. 여러 장의 돌을 높게 쌓아올려 대석을 만든 후 그 위에 2층의 기단과 5층의 탑신을 세웠는데, 기단 아래 부분은 후대에 탑을 세우면서 쌓은 것으로 원래의 탑과는 무관하다. 기단은 2층으로, 하층기단은 넓고 높은 편인데 여러 장의 장대석을 이어 결구하였으나 부분적으로 손상이 있으며, 사이 사이에 잡석을 끼워 지탱하고 있다. 상층기단은 하층 기단에 비하여 높이가 약간 낮은 편이며, 5층의 탑신을 받기에는 폭이 다소 좁아 보인다.","a":"영취사 오층석탑","c":"문화유산자료","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659318.jpg"},{"q":"○○○ 미륵전 오른쪽의 벽면에 봉안되어 있는 이 불상은 두께가 32㎝나 되는 두꺼운 돌에 양각을 한 여래좌상이다. 불신 뒤에는 배(舟) 모양의 광배가 있으며, 현재 시멘트로 된 직사각형의 대좌 위에 안치되어 있다. 민머리 위에 상투 모양의 육계가 사발처럼 솟아있고, 얼굴은 4각형의 평면에 코는 인위적으로 깎아낸 듯 하며 입은 형식화되었다. 목에 3개의 주름인 삼도(三道)가 뚜렷하고 양어깨를 덮은 옷은 옷주름이 섬세하지 못하고 듬성듬성하게 묘사되었다.","a":"영암망월사석불좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640165.jpg"},{"q":"철장이란 철의 원료인 토철, 또는 철광석을 캐던 곳을 말한다. 달천동 및 상안동 일대에 분포하는 이 유적은 원래 이름인 달내[達川]에서 유래하였으며, 그 역사는 삼한시대까지 거슬러 올라간다. 중국문헌 『삼국지 위서 동이전(三國志 魏書 東夷傳)』과 『후한서(後漢書)』에는 ‘한(漢)·예(濊)·왜(倭) 모두가 여기서 철을 가져가며, 모든 시장에서 철을 사용하여 매매하는 것이 마치 중국에서 돈을 사용하는 것과 같다.’는 기사가 있다. 따라서 철이 당시의 경제 발달에 크게 기여하였음을 알 수 있다.","a":"달천철장","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645918.jpg"},{"q":"가신 초등학교 보광분교 앞의 계곡을 따라 1.5km쯤 들어간 자리에 있는 ○○○의 옛 터이다. 주변에는 다량의 기와조각과 석탑의 부재로 쓰였던 돌이 남아있다. 부여박물관에 보관된 대보광선사비(보물 제107호)의 비문에 의하면 ○○○는 고려 충숙왕 5년(1336) 원명국사가 이곳에 와서 크게 일으켰다고 전하는데, 당시의 건물이 500여 칸으로 규모가 큰 절이었음을 알 수 있다. 또 다른 비문에 의하면 임진왜란으로 절이 소실되자 영조 26년(1750)에 승려들이 비문을 새겼다고 전하고 있어, 적어도 ○○○가 임진왜란 무렵까지는 맥을 이어왔던 것으로 추정된다.","a":"부여보광사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652856.jpg"},{"q":"괘불이란 옥외에서 법회를 할 때 밖에 내어 걸고 의식을 행하는 걸개그림 형태의 불화를 말한다. 이 괘불은 조선 고종 19년(1882) 김시대의 발원에 의해 제작된 것으로, ○○○불을 주존으로 한 ○○○삼존불화이다. 19세기 후반 서울지역과 경기 인근지역에서 제작된 괘불 형식을 따르고 있으며, 세로 5.7m, 가로 3.29m의 크기로, 삼베에 채색한 것이다. 큰 화면에 ○○○불·관음보살·세지보살이 화면을 가득 채우고 서 있으며, 그 아래로 십대 제자의 대표인 아난존자와 가섭존자가 합장하고 서 있다.","a":"아미타괘불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588076.png"},{"q":"○○○란 선사시대 사람들이 바위나 동굴의 벽면돌에 기호나 물건, 동물 등의 그림을 새겨놓은 것을 말하며, 풍요와 생산을 기원하는 주술행위의 결과물로 보고 있다. ○○○○○는 ○○○ 마애삼존불상이 있는 바위의 10m 아래에 새겨 놓았는데, 높이 1∼1.5m, 너비 4.5m로, 청동기 시대에 새긴 것이다. 청동 도구로 쪼아서 새기는 방법을 사용하여 3∼5개의 선을 옆으로 연결하였는데, 그 의미는 아직 알 수 없다. 이러한 수법은 고령 양전동, 울산 천전리 바위그림과 비슷하다.","a":"영주가흥리암각화","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640783.jpg"},{"q":"용수암(龍首巖)은 용암 박운(龍巖 朴雲 1493-1562) 선생이 강학(講學) 및 휴식(休息)을 하던 곳이었다고 전해지는 장소에 있는 큰 암벽이다. 바위에는『용암박선생장구지소(龍巖朴先生杖屨之所)』라 하여 『용암 박운 선생이 머물든 곳』이라는 글자가 새겨져 있으며, 옛 모습 그대로 남아 전해져오고 있다. 조선전기 사림파의 한 사람인 용암 박운(龍巖 朴雲) 선생은 1493년(成宗 24년) 선산부 해평현 괴곡리에서 태어났다. 1519년(中宗 14년) 진사시(進士試)에 입격(入格)하였다.","a":"구미용수암","c":"시도기념물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654675.jpg"},{"q":"조선 정조 19년(1795)에 왕이 내린 불교식 가사(歌辭)로, 손수지어 용주사에 내린 게송이다. 원래의 명칭은 『어제화산용주사봉불기복게』인데, 화산의 용주사에 부처를 모시고 복을 기원하는 글이라는 뜻이다. '기복게'는 서문과 본문으로 이루어져 있다. 서문에는 정조사 용주사를 건립하게 된 배경과 삼업(三業) 공양을 바치고 복전(福田, 부모가 양육한 은혜)에 보답하기 위해 게송을 지었음을 밝혔다. 이어지는 게송은 오언절구 형식으로 총 10수 이다. 용주사에는 ‘기복게’ 필사본과 목판 9매가 전한다.","a":"전적수사본","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637360.jpg"},{"q":"남해 ○○○ 대웅전 내에 보관된 이 동종은 음통과 용뉴가 1개씩 있으며, 편평한 천판은 세장방형의 12개 연판으로 구성 되어 있고, 鐘形은 견부에서 鐘口로 내려갈수록 넓어지고 있다. 용뉴는 입을 벌리고 있는 용의 머리와 3개의 발가락을 가진 두 발이 모두 천판과 맞닿아 있고, 몸의 형태는 ‘∩’자형으로 1개의 여의주를 받치고 있으며, 꼬리 부분은 음통을 2번 휘감고 있다. 용의 두부는 큰 눈과 날카로운 이빨, 크게 벌린 입, 뿔 표현이 생동감 넘치고 비늘 표현도 비교적 사실적이다.","a":"남해용문사동종","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665545.jpg"},{"q":"○○○는 중국 삼국지에 나오는 관우 장군을 신으로 모시는 신당의 일종으로, 관왕묘라고도 한다. 임진왜란을 거치면서 왜구를 물리친 것이 관우 장군신의 도움이라 여기던 명나라 군사들에 의해 우리나라 ○○○의 효시인 ‘남묘’가 서울에 처음 건립되었고, 이후 군사들의 사기를 높이고자 왕의 명을 받들어 전국적으로 건립하여 수호신당으로 섬기에 되었다고 한다. 당은 16평 넓이의 기와 건물로, 내부로 들어가면 정면에 18세기 화풍으로 그려 놓은 관우장군과 그 부인의 그림이 좌·우로 배치되어 있고, 그 왼쪽에 또 다른 무신도가 걸려있다.","a":"관성묘","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2022110915521900.jpg"},{"q":"조선 후기 운강 박시묵의 손자인 박래현(1861∼1896)이 고종 18년(1881)에 세운 가옥이다. 그 뒤 둘째 아들 박순희(1896∼1934)가 입주하여 ‘○○○○’이라 하였다. 대문채를 들어서면 사랑마당이 보이고 중사랑채를 지나면 안채인 정침이 있다. 안마당의 왼쪽에는 방앗간채가, 오른쪽에는 곳간채가 있는데 전체적으로는 트인 ㄹ자형으로 배치되어 있다. 정침의 대청 전체에 문을 달아 당시 폐쇄적인 양반댁 부녀자의 생활 양식을 보여 준다.","a":"청도 명중고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658977.jpg"},{"q":"고성 ○○○에 있는 배찬열씨 초가이다. 안채는 4대째 살고 있다고 하며 아래채는 배찬열씨 할아버지 때 지은 것이라고 한다. 안채는 앞면 2칸·옆면 1칸 크기로 옆면과 뒷면 벽채는 막돌을 쌓고 틈은 진흙으로 메웠다. 아래채는 앞면 3칸·옆면 1칸 크기로 앞쪽 반칸에 툇마루와 아궁이를 놓았다. 가운데 칸이 온돌방이고, 양쪽 칸은 헛간이다. 안채는 민가의 가장 원시적인 형태를 띠고 있어 눈길을 끈다.","a":"고성봉동리배씨고가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659055.jpg"},{"q":"설악산 수련원에서 달마봉 쪽으로 약 30분 정도 오르면, 한적한 절터에 이 석탑이 자리하고 있다. 이 석탑은 단층(單層) 기단(基壇) 위에 3층의 탑신(塔身)을 세운 석탑으로, 1층 탑신과 지붕돌［옥개석(屋蓋石)］은 각 하나의 돌로 만들어졌다. 2층 지붕돌과 3층 탑신, 3층 지붕돌과 노반(露盤)은 각각 1석으로 조성되었고, 2층 탑신은 없어졌다. 탑의 가장 큰 특징은 1층 탑신의 4면에 사방불(四方佛)을 조성한 점이다.","a":"속초노학동삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660585.jpg"},{"q":"임진왜란 때 의병장으로 활약한 ○○○ 장군을 기리기 위해 그의 군대가 주둔하였던 옛 성루 터에 세운 비이다. 고루(古壘)란 과거에 전투를 벌였던 ‘작은 성루〔城壘〕’를 말한다. 이재(李縡)가 지은 비문에 “안성군 남쪽 15리쯤에 있는 목촌(木村) 마을의 옆에는 우뚝 솟은 산이 있는데 (중략) 사람들이 서로 전하기를 옛날 ○○○ 장군의 군대가 진을 치던 작은 성루라고 한다”는 내용이 전한다. ○○○은 임진왜란이 일어나자 부친 홍자수(洪自修), 형 4명과 함께 의병을 모아 많은 승리를 거두었다.","a":"홍계남장군고루비","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637449.jpg"},{"q":"경상북도 문경시 산북면 전두리의 ○○○ 뒤쪽에 자리잡은 윤필암과 묘적암 사이의 큰 바위에 새긴 높이 6m, 폭 3.7m의 마애석불○○○○이다. 이곳에 미륵암이 있었다고 전해지는데 지금은 흔적만 남아 있다. 불상을 새긴 바위가 약간 앞으로 숙여져 있어 비바람을 피할 수 있고 또한 갓바위가 설치되어 보존 상태가 매우 좋다. 특이하게 마애불의 머리 위에 연꽃무늬를 한 뿔처럼 생긴 것이 2개 솟아 있다. 이러한 모양의 마애불은 불교양식 변천 연구에 귀중한 자료가 된다. 갸름한 얼굴에 눈은 거의 감고 있고, 입술은 두터우며 귀는 길다.","a":"대승사마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640768.jpg"},{"q":"이명성과 이명덕(1373∼1444) 형제의 학행을 기념하고 후학을 양성하기 위해 세운 곳이다. 이명성은 고려가 망하고 조선이 건국되자 끝까지 벼슬에 나아가지 않고 절개를 지킨 고려 유신인 두문동 72현 중 한 사람이다. 이명덕은 고려말∼조선초 문신으로 호는 사봉이다. 예문춘추관, 좌부대언 등을 지냈고 세종이 즉위하자 이조참판, 병조참판 등 많은 벼슬을 지냈다. 70세에 벼슬에서 물러났으며 후에 우의정으로 추증되었다. 원래는 성종 때 충남 연기군 명탄에 세웠던 ○○○라는 사당인데, 명탄서원이라고도 불렸다.","a":"충절사","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660995.jpg"},{"q":"창원 황씨 문중에서 세운 것으로 조상들의 제사를 모시는 곳이다. 여기에는 황석기·황상·황준·황윤·황우·홍어필의 위패를 모시고 있으며 해마다 음력 10월 15일에 제사를 지내고 있다. 황석기(？∼1364)는 고려말의 문신으로 1342년 조적(曹적)의 무리를 제거하고 왕을 모신 공으로 1등 공신이 되었다. 문장에도 뛰어난 분으로 여러 관직을 거쳐 1358년에는 문하시랑동중서문하평장사에 이르기도 하였다. 황상은 고려말의 무신으로 충혜왕 때 호군이 되었고 공민왕 때 밀직부사가 되었다. 그 뒤 홍건적과 왜구를 토벌하는데 공을 세웠는데 무예에 능하고 용맹이 뛰어났다.","a":"진주 동산재","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663808.jpg"},{"q":"조선시대 영남지방의 과거시험 장소를 기념하기 위하여 세운 건물이다. 정조(재위 1776∼1800)는 이황의 학덕과 유업을 기념하기 위하여, 이조판서 이만수에게 도산별과를 새로 만들어 지방의 인재를 선발하게 하였다. 이러한 과거시험을 기념하기 위해 정조 20년(1796)에 영의정 채제공의 글로 비문을 새기고 ○○○을 세웠다. 그 뒤 순조 24년(1824)에 고쳐 세우고, 1974년 안동댐 건설로 현 위치에서 지상 10m의 축대를 쌓아 그 위로 비각과 비를 옮겨지었다. 비각은 앞면 1칸·옆면 1칸 규모이고, 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕 건물이다.","a":"시사단","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640289.jpg"},{"q":"조선 고종 12년(1875)에 봉촌 최상룡이 행정사무를 볼 수 있도록 마을사람들과 의논하여 지은 것이다. 원래 이 자리에는 달성군 공산면 4개 마을(강동·독좌·위남·단산)에서 쓰던 초가 사무소가 있었다. 이 4개 마을을 합쳐 봉무동으로 행정구역이 바뀌자 초가를 헐고 이 건물을 지었다. 강당을 중심으로 동쪽에 덕교재, 서쪽에 예용재가 있다. 강당은 농민들의 계몽과 마을 규약 등을 가르치고, 선비들이 모여 시를 짓고 풍류를 즐기던 곳이다. 덕교재와 예용재는 마을사람들이 모여 의논하던 곳이다.","a":"봉무정","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636852.jpg"},{"q":"임진왜란을 전후해서 성재 신응순(1572∼1636)과 신응망(1595∼1654)을 배출하여 유명해진 영월 신씨의 집이다. 알려진 바로는 신암규(1815∼1886)가 크게 고쳐 지었다고 한다. 안채와 사랑채를 비롯하여 총 11동으로 구성된 큰 규모의 저택이다. 안채는 중부지방식 평면형인 ㄱ자형 집으로 작은방·대청·방 2칸·마룻방·안방·부엌이 배치되어 있다. 사랑채는 대청·방·골방으로 구성되어 있는 一자형 집이다. 앞뒤로 툇마루를 놓았는데 남쪽 끝에서 대청 앞까지만 설치하였다.","a":"영광신호준가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658389.jpg"},{"q":"○○○은 조선 숙종 27년(1701)에 세운 미호서원의 부속 건물인데, 제월당(霽月堂) 송규렴(宋奎濂, 1630∼1709)이 제자를 모아 가르치던 터에 지어진 건물로 건물안에는 송규렴이 지은 미호신사(渼湖新舍) 상량문이 걸려있다. 송규렴은 조선 중기 문신으로 문과에 급제하여 충청도 관찰사와 예조참판을 지내고 예조판서, 대사헌 등에 임명되었으나 모두 그만두었는데, 80세 때에 이르러 지돈녕부사에 올랐다. 학문이 뛰어나 송시열, 송준길과 함께 삼송(三宋)으로 일컫는다.","a":"취백정","c":"문화유산자료","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659700.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 지상에 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 원래 대덕구 진잠에 있던 것을 1977년 8월에 유성구 원내동으로 옮긴 것이며, 바둑판식 고인돌 3기와 탁자식 고인돌 1기이다. 바둑판식 1호 고인돌의 덮개돌은 길이가 3.25m, 너비 1.86m이다.","a":"내동리지석묘","c":"시도기념물","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645778.jpg"},{"q":"○○○○은 조선 초인 태종 7년(1407)에 창건되었고, 1914년에 대흥면사무소로 개조하여 사용되다가 1979년 해체복원 정비되었다. ○○○○은 기본 구조가 잘 남아 있고, 예산지역에 현존하고 있는 유일한 관아건물이며 1405년에 건립된 대흥향교와 함께 대흥지역의 역사를 증명하는 건축물로서 역사적·건축학적 보존가치가 있다.","a":"예산대흥동헌및아문","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639295.jpg"},{"q":"이 책은 中國 宋나라의 上疏文 중 뛰어난 것을 골라 朝鮮時代 최초로 주조한 銅活字인 계미자로 찍어낸 희귀본 책자이다. 태종(1400∼1418)연간에 간행된 것으로, 펴낸 사람이 누구인지를 알 수 없다. 조선 태종 3년(1403)에 주조한 동활자인 癸未字를 사용하였고 주로 계미소자를 사용하여 인출한 것이 특징이다. 계미자는 경연에 달린 옛 주 달림〈經筵古註〉의 시·서·춘추좌씨전을 바탕으로 만든 글자이다. 고려와 조선시대의 글자 주조술과 조판술의 발달사 연구에 귀중한 자료인데 사용했던 기간이 짧아 전해지는 본이 희귀하다.","a":"송조표전총류 권8~10","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101619444900.JPG"},{"q":"충청북도 ○○시 가금면에 있으며 자연 암벽 위에 얕은 선으로 새겨진 마애불로 연꽃무늬가 새겨진 대좌 위에 서 있다. 크고 길게 찢어진 눈꼬리, 큼직한 코와 귀 등에서 근엄한 인상을 풍긴다. 양 어깨에 걸친 옷에는 3가닥의 선으로 새긴 것과 더불어 구불구불한 선으로 새긴 특이한 형태의 옷주름이 표현되어 있다. 토속적인 분위기와 세련되지 못한 세부 표현, 하체 조각이 생략된 기법, 구불구불한 선 모양 등 이 지방에서 많이 보이는 독특한 지방양식을 보여주는 작품이라고 할 수 있다.","a":"충주 창동리 마애여래상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638503.jpg"},{"q":"액자로 된 본 작품의 뒷면 중앙에는 세로로 1행의 다라니가 붉은 글씨로 적혀있고, 그 가운데 정사각형의 틀이 있으며, 그 안에 다라니·진언·기문 등의 복장물이 확인되었다. 뒷면 네면 모서리에 붉은 글씨로 동서남북을 표시한 한자(一字)씩의 다라니가 쓰여 있다.","a":"복천사독성도및복장유물일괄","c":"문화유산자료","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659386.jpg"},{"q":"임실 ○○○○○은 2016년 <임실군 불교유적 학술연구 용역사업>을 통해서 ○○○○○이 어깨를 덮는 통견 형태의 법의 목 부분이 'V'자 형태의 옷깃이 있는 두루마기를 입은 형상이고, 석불입상의 가슴 중앙과 등 쪽에 있는 수식(垂飾)은 조선시대 문인석에 장식된 수식의 영향을 받은 것으로 밝혀졌다. 석불에 글씨는 없었으며 미륵을 받치고 있는 받침대는 연화문이 새겨져 있는 연화대이다. 조사결과 연구진은 이 석불에 대해서 15세기 불상 조각의 전통이 남아있는 16세기 석조불상으로 추정하였다. ○○○○○을 봉안해 놓은 보호각은 1996년에 1칸짜리 전각으로 세워졌다.","a":"임실이도리미륵불상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639612.jpg"},{"q":"이 신문은 한국인에 의해 발행된 최초의 그리고 유일한 지방지라는 면에서 상당한 의미가 부여될 수 있을 것이다. 이 신문에는 구한말 일제 초기 진주를 비롯한 경남지역 내의 변화, 발전 상황이 투영되고 있어 상당한 사료적 가치가 있다.","a":"경남일보 창간호","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643113.jpg"},{"q":"영실 영원사 오백나한전에 소장되어 있는 ｢○○○ 소장 ○○○○○｣의 판본은 전 7권 2책 중에 권1~3의 1책이 결본으로, ○○○○의 1책만이 해당된다. 이 책은 사육신의 한 분인 성삼문의 조부인 성달생(권 1·7)과 임효인(권2~4)· 조 절(권5~6)등이 1432~1435년까지 4년 동안 글씨를 썼으며 1435~1442년 까지 8년여 동안 ○○○에서 판각하였다. 형태적 특징을 살펴보면, 권1의 책 처음 쪽을 기준으로 변란은 사주단변으로 되어 있으며, 그 반곽의 크기는 가로 13.7cm, 세로 21cm로 되어 있다.","a":"선덕사소장화암사판묘법연화경 권4~7","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643309.jpg"},{"q":"충청북도 ○○시 상당구 탑동에 있는 곽여찬郭汝贊, 곽진은郭鎭殷, 곽원호郭元浩, 곽상조郭相祚 등 ○○○○ 4대의 ○○○와 ○○○○○ 3기이다. 곽여찬은 조선 순조 때의 사람으로 네 살 때 아버지를 여의고 홀로 어머니를 지성으로 봉양하였다. 어머니가 돌아가시자 3년 동안 상복을 입고 묘를 돌보았다. 이 같은 효행이 알려져 1817년(순조 17)에 정려旌閭를 받았다. 곽여찬의 정려각은 정면 1칸, 측면 1칸의 목조 기와 건물로 겹처마에 팔작지붕을 올렸다. 사면을 홍살문으로 둘렀으며, 건물 안에는 현판과 비석이 있다 효. 자비의 규모는 41×93×17㎝이다.","a":"청주 현풍곽씨 효자비 및 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651413.jpg"},{"q":"○○○○○에 대한 고마움을 잊지 않기 위해 주민들이 세운 ○○○로 파손되어 매몰되어 있는 것을 1855년에 후손들이 다시 세운 것 입니다. 전국적으로 아전에 대한 ○○○는 매우 희귀한 사례임.","a":"고성 이방 박영장 불망비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110716563200.jpg"},{"q":"선조, 인조 때에 안신(1569∼1648)이 지은 것으로 『주자가례』를 근거로 하고 우리 풍속에 맞도록 만든 실용예절 책이다. 안신은 조선 중기의 학자로, 임진왜란이 일어나자 김시민의 휘하에 들어가 많은 공을 세웠으며, 서당이 전란으로 파괴되어 학생들이 배울 곳이 없자, 동지들을 모아 서당을 짓고 학생들에게 교육을 권장하였다. 이전의 가례중심으로 쓴 저술들이 분량이 너무 많고 쉽게 얻어볼 수 없을 뿐만 아니라 임진왜란을 겪으면서 그 문적들이 거의 타 없어져서 예학에 뜻을 둔 이들은 문헌이 없음을 아쉬워 하였다. 그 때문에 이 책판을 만들게 되었다.","a":"가례부췌책판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642116.jpg"},{"q":"쌍계정은 고려 충렬왕(재위 1274∼1308) 때에 문정공 정가신이 세웠다고 전하는 정자이다. 이름은 정자 좌우로 계곡이 흐르기 때문에 붙여졌다고 한다. 문정공은 이곳에서 김주정, 윤보와 더불어 학문과 인격을 갈고 닦았는데 이런 이유로 ‘삼현당’이라 불리기도 했다. 그 뒤 조선 세조(재위 1455∼1468) 때 정서, 신숙주 등 당시의 대표적인 학자들이 학문연구 장소로 사용하였다. 앞면 3칸·옆면 2칸 규모로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕이다. 쌍계정과 주변의 오래된 나무들이 풍치있게 어울려 조선시대 대표적 정자로 손꼽히고 있다.","a":"나주쌍계정","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639860.jpg"},{"q":"이○○과 이○○은 신사임당의 자녀로, 둘 모두 어머니의 재능을 이어받아 예능에 뛰어난 솜씨를 지녔다. ○○의 ○○○는 가로 26.5㎝, 세로 30㎝의 종이에 그린 묵화로, 굵은 가지와 잔 가지가 한데 어우러져 은은한 달빛아래 자태를 한껏 뽐내고 있는 매화를 실제로 보는 듯 하며, 깔끔한 분위기가 돋보인다. ○○의 국화도는 가로 25㎝, 세로 35㎝ 크기의 종이에 그린 묵화로, 국화 한줄기가 화면에 솟아오른 단순한 구도이면서도 만발한 국화를 보는 듯 담백한 여운을 풍긴다. ○○과 ○○ 남매의 그림을 이해하고 감상할 수 있는 소중한 자료이다.","a":"매창 매화도 및 옥산 국화도첩","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637876.jpg"},{"q":"구파 ○○○ 의사가 어렸을 적 살았던 곳이다. 선생은 건양 1년(1896) 부안에서 태어나 어려서 부친을 여의고 1907년 이곳으로 이주하여 1919년 독립운동을 위해 중국으로 망명할 때까지 12년동안 생활하였다고 한다. 3·1 독립운동에 가담한 이후 독립운동을 계속하다가 붙잡혀 일본의 장기 형무소에서 복역하던 중 지병이 악화되어 1934년 순국하였다. 1946년 일본에서 유해를 송환받아 효창공원에 안장하였으며 1963년 건국훈장 독립장이 수여되었다.","a":"구파백정기의사고택지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653691.jpg"},{"q":"조선 중기의 유학자 동천 이충범(1520∼1598)이 제자들을 양성하던 곳이다. 조선 초기에 양강 강가에 처음 지어졌다고 하는데, 인조 4년(1626) 이후 숙종 46년(1720)까지 여러 차례의 보수공사를 거쳐 오늘날에 이르고 있다. 처음에는 풍곡당이라고 부르다가 광해군 6년(1614)에 한강 정구 선생이 이곳에 머무르며 자법정풍(資法正風)으로 학문을 장려하였다는 뜻으로 자풍당이라 이름을 바꾸었다. 앞면 5칸·옆면 2칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집으로 18세기경의 건축양식을 잘 간직하고 있는 건물이다.","a":"영동 자풍서당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638500.jpg"},{"q":"○○○는 춘천관아 건물인 문소각(聞韶閣)을 신축할 때 함께 건립되었다. 고종 27년인 1890년 춘천관아에 이궁(離宮)을 설치할 때 개축(改築)되어 문루(門樓)로 사용되었다. 1938년 우두산으로 이전 되었고, 한국전쟁으로 일부가 파손되어 1969년 크게 수리하였다. 2013년 4월 이 자리에 이전을 완료하였다. 현판은 1818~1819년 춘천부사로 재임한 조선후기 명필 자하(紫霞) 신위(申緯)가 쓴 해서천자문의 글씨를 집자(集字)하여 복각하였다. 정면 3칸, 측면 2칸 규모의 팔작지붕으로 누각 아래에 삼문을 낸 전형적인 문루의 모습을 갖추고 있다.","a":"조양루","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637833.jpg"},{"q":"조선 중종 때 형조판서 겸 예문관 제학을 지낸 충암(沖庵) 김정(1486∼1521) 선생의 위패가 모셔져 있는 건물이다. 선생은 조광조와 더불어 지치주의를 실현하기 위해 미신타파와 향론의 상호부조에 힘썼고, 향약을 전국에 실시하는데 큰 업적을 남겼다. 중종 14년(1519) 기묘사화 때 조광조 등과 함께 투옥되었다가 금산에 유배된 후 제주에서 사약을 받고 죽었다. 대덕구 동면 내탑리에 있던 건물과 묘소를 1978년에 동구 신하동으로 옮겼다.","a":"김정선생묘소일원","c":"문화유산자료","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659729.jpg"},{"q":"기봉 유복기(1555∼1617) 선생과 회헌 유의손(1398∼1450) 선생의 위패를 모시고 제사지내는 곳이다. 원래 후손들의 글공부를 위해 서당으로 세웠던 것인데 후손들이 서원으로 바꾸었다. 지금 있는 건물은 임하댐 건설로 1988년 현재 있는 곳으로 자리를 옮긴 것이다. 유의손 선생은 조선 전기 학자로 여러 벼슬을 거치고 문장에도 뛰어났다고 하며, 유복기 선생은 조선 중기 학자로 임진왜란 때 의병장으로도 활약했던 분이다. 사당인 추원사는 앞면 3칸·옆면 2칸 크기로 옆면에서 볼 때 지붕선이 사람 인(人)자 모양과 비슷한 맞배지붕이다.","a":"기양서당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658466.jpg"},{"q":"적상산 분지에 있는 ○○○는 고려 충렬왕 3년(1277)에 월인화상이 지었다고 전한다. 원래는 적상산성을 지키던 승병들의 숙소로 지었다고 하며, 조선 광해군 5년(1613)과 고종 1년(1864)에 수리하였다. 아미타불을 모신 ○○○은 앞면 3칸·옆면 3칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 간결한 맞배지붕집이다. 지붕 처마를 받치면서 장식을 겸하는 공포는 기둥 위와 기둥 사이에도 배치된 다포식 건물이다. 내부에는 이 지역의 신앙물로 천재지변을 몰아 낸다고 전하는 괘불이 있다. 절의 주변에는 조선왕조실록을 보관하던 사고(史庫)의 옛터가 남아있다.","a":"안국사 극락전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639425.jpg"},{"q":"○○○은 조선 헌종·철종년간에 영양현감을 지낸 야옹 정기필(鄭夔弼)선생이 기거하던 주택이다. 야옹선생은 목민관 재임시 청렴한 인품과 덕행으로 명망이 높았으며 관직을 사직하고 고향으로 돌아왔으나 재산과 거처가 없자 당시 안의현감의 도움으로 이 ○○○을 건립하였다고 한다. ○○○이란 이름은 스스로 자신을 뒤돌아보고 반성한다는 의미인 \"反求於諸心\"에서 유래한다. ○○○은 현재 대문채와 사랑채만 남아 있는데 사랑채에 〔崇禎丁丑後二百三十四年〕이라는 상량문이 남아 있어 현재의 건물은 1870년대에 건립 또는 중건된 것으로 추정된다.","a":"거창 반구헌","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664408.jpg"},{"q":"세운 시기를 정확하게 알 수 없는 집이지만 13대째 살아오고 있다고 한다. 여러 차례에 걸쳐 고쳐 지었으며, 지금 있는 건물은 105년 전에 고쳐 지은 것이다. 건물 구성은 안채와 사랑채, 부속채 1동으로 구성되어 있다. 안채는 앞면 6칸·옆면 4칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. ㄱ자형 평면구조를 이루고 있는데 대청을 중심으로 왼쪽에 안사랑방 2칸을 배치하였으며 왼쪽 1칸은 아궁이를 설치하였다. 안방 앞에 딸린 2칸은 부엌으로, 현재는 입식부엌으로 수리하였다.","a":"평창대하리전통가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660589.jpg"},{"q":"임진왜란 때 승병장이 되어 나라를 구하려다 전사한 영규대사의 충혼을 기리고 있는 비이다. 영규대사(?∼1592)는 조선 선조 25년(1592) 임진왜란이 일어나자 3일동안 통곡한 후 스스로 승병장이 되었다. 승병 수백명을 모아 관군과 더불어 청주성의 왜적을 쳤고, 이어 조헌과 함께 금산전투에 참가하여 장렬히 싸우다 전사하였다. 이 일은 이후 전국적으로 승병이 일어나게 되는 계기를 마련하였다. 숙종 5년(1839) 5월 금산군수 조취영이 세운 비로, 일제가 1940년 비를 보호하던 비각을 부수고 비를 묻어놓았던 것을, 해방 후 다시 꺼내 세워놓은 것이다.","a":"의병승장비","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660904.jpg"},{"q":"녹문들판 한쪽에 남서향으로 자리잡고 있는 이 집은 ○○○에 있는 개성 고씨의 집 중 하나이다. 자료에 따르면 순조 28년(1828)에 지었다고 전한다. 一자형 대문채를 들어서면 넓은 마당 건너편에 一자형 사랑채가 놓여 있고 그 뒤쪽에 안채가 있다. 원래는 사랑채 오른쪽 뒤에 중문간을 둔 一자형 아래채가 있었으나 아래채는 1980년대 후반에 철거하고 지금은 안채와 사랑채가 튼 ㅁ자형을 이루고 있다. 대문채는 특이하게 지붕을 옆면에서 볼 때 여덟 팔(八)자를 이루는 팔작지붕으로 꾸몄다.","a":"문경녹문리고병숙가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663216.jpg"},{"q":"경은(耕隱) ○○○은 조선개국 공신 조반의 아들로 태종14년(1415) 문과에 급제하여 장령을 지내고 세종13년(1431)에 춘추관 기주관이 되어 태종실록 편찬에 참여하였다. 그 뒤 우관원을 거쳐 경상도 관찰사, 형조참의 등을 역임하고 1441년에 도승지를 지냈으며, 1443년 이조참판이 되었다. 그의 만년에 이조참판을 그만두고 부친 조반의 별업(별장)인 가정(佳亭)에 은거하였다. 그가 은거하자 세종은 궁중화가를 보내 가정의 모습을 그리게 하였고 이후 많은 선비들이 가정을 주제로 시를 지었으며 안평대군은 이를 모아 <석호가정별업도>라는 서화집을 만들기도 하였다.","a":"조서강 묘","c":"시도기념물","nc":"","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645516.jpg"},{"q":"각종 도장을 보관하는 도장함과 도장으로 이루어져 있으며, 도장함은 사각형의 목재로 이루어져 있고, 뚜껑까지 잘 갖추어져 있다. 표면은 상어껍질로 장식하고 각 모서리마다 금속장식을 부착하여 우아함과 견고성을 보여줌으로써, 그 속에 넣어둔 도장의 중요성을 강조하고 있다. 도장 3개는 모두 동으로 만들어 졌으며, 하나는 조선 현종 12년(1671)에 만들어 졌고, ‘불법승(佛法僧)’이라 새겨 있다. 다른 하나는 연대를 새겨 놓은 글자는 보이지 않지만, 그 형태나 재질로 보아 위의 것과 비슷한 연대에 만든 것으로 추정되며, ‘신흥사승통인(新興寺僧統印)’이라고 새겨 있다.","a":"양산 통도사 인적 및 동인","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641580.jpg"},{"q":"높이 2.54m로, 포천 해룡산(海龍山)의 정상 부근에 동남향으로 서 있는 불상이다. 자연스러운 자세와 비교적 조화로운 신체 비례, 옷주름의 표현 형식 등에서 통일신라시대 불상 양식을 보이나 양감이 줄어들고 세부표현이 정교하지 못한 점 등에서 통일신라 양식을 이은 고려 시대의 불상으로 평가된다. 아무런 장식을 가하지 않은 배 모양의 거신광(擧身光 ; 붓다의 몸에서 나오는 성스러운 빛을 몸 전체를 감싸는 형식으로 표현한 광배)에 불상을 두껍게 돋을새김 하였다.","a":"포천석조여래입상","c":"시도유형문화유산","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637673.jpg"},{"q":"○○○○○은 우리나라에 ○○○가 처음으로 전파되기 시작할 때, 초대 선교사 고요한 주교와 함께 영국으로부터 내한한 조마가 신부가 1896년 ○○에 부임하여 선교를 하면서 2년 후인 1898년에 건축한 건물이다. 이후 ○○○이 퇴락하자 1933년 원형 그대로 중수하여 오늘에 이르고 있다.","a":"강화 온수리 성공회 사제관","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018112014283200.jpg"},{"q":"경상북도 봉화군 춘양면 ○○○에 있는 불상으로, 얼굴이 듬직하고 불신이 거의 완전한 형태로 남아 있다. 체구는 뚱뚱한 편이어서 전체적으로 부드러운 느낌을 준다. 오른손은 허벅지에 대고 왼손은 가슴에 들어 손바닥을 붙인 모습인데, 신라 석불입상에서 가끔 보이는 손모양이다. 양 어깨를 감싼 옷은 가슴 중간에서 U자형의 주름선이 돌아 양 다리로 내려가 발목에서 마무리된다. 세부모습이나 자세, 옷 입는 형식이나 부피감 등에 신라 전통이 강하게 남아 있지만 다소 해이해지고 형식화된 모습을 보인다.","a":"봉화의양리석조여래입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640516.jpg"},{"q":"입석(立石) 즉, ○○은 마을의 입구에 세워 재앙을 막고, 마을에 평화와 농사가 풍년이 들기를 기원하는 마음으로 세우는 것이다. ○○○ 마을 입구에 자리한 이 입석은 이 지역 주민들이 ‘할머니’라 부르고 있으며, 재앙을 막고 풍농·평안을 지켜주는 수호신의 구실을 하고 있다. 전체적인 형태는 길쭉한 자연석 돌을 세워놓은 모습으로 가운데 부분이 볼록하게 나와있다. 이 가운데 부분에는 90㎝정도 되는 원을 만들어 놓았는데, 이는 임신한 여인을 상징하는 것으로 그 당시 사람들이 자식을 많이 낳기를 바라는 마음에서 새긴 것임을 알 수 있다.","a":"옥천 석탄리 선돌","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651533.jpg"},{"q":"원래는 울산 도호부 객사였던 학성관의 남쪽 문루인데, 지금은 정자 형식을 갖추고 있다. 객사란 지방에 출장간 관리나 외국 사신이 얼마간 머물던 곳을 말한다. 태화루라 불리기도 했던 이 건물은 일제시대 말에 도서관을 겸해 사용해 오다가 1940년에 울산공립보통학교(지금의 울산초등학교)의 교정을 넓히면서 지금 있는 자리로 옮겨 짓게 되었다. 옮겨 지을 당시, 학성 이씨 월진파의 정각이었던 ○○○의 이름을 빌려왔고 건물도 정자 형식으로 일부 고쳐 지었는데, 누 아래쪽 양쪽 칸을 막아 온돌방을 만듦으로써 문루 형식에서 정자 형식으로 완전히 탈바꿈을 하게 되었다.","a":"이휴정","c":"문화유산자료","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659768.jpg"},{"q":"조선 후기의 문신 지촌 김방걸(1623∼1695) 선생의 제사를 모시는 제청으로 숙종 38년(1712)에 세웠다. 선생은 현종 1년(1660) 문과에 급제하여 벼슬에 나아갔다. 숙종 15년(1689) 사간이 되었으나 인현왕후 민씨가 폐위되자, 왕의 잘못을 미리 막지 못한데 책임을 느껴 낙향했다. 이후 승지와 대사간 등을 역임하였다. 저서로 『지촌문집』이 있다. 건물은 3동으로 제청은 앞면 5칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"안동 지촌제청","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018021911411100.jpg"},{"q":"조선시대 제주도의 방어유적으로 숙종 4년(1678) 지방관인 최관에 의해 축성되었다. 성안에는 관리들이 사는 건물과 제주를 오는 사신들을 묵게 하기 위한 객사를 비롯하여 창고, 마방 등 여러 건물이 있었다고 전한다.","a":"화북진지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657949.jpg"},{"q":"○○○ 내 연못 중앙에 마련된 작은 터에 자리하고 있는 탑으로, 절 내의 광자대사 부도 앞에 있던 것을 이곳으로 옮겨 놓았다. 원래는 기단(基壇)의 한쪽 면과 탑신(塔身)의 1층 지붕돌, 2·3층 몸돌이 없어진 상태였는데, 이곳으로 옮기면서 새로이 보충하여, 2층 기단에 3층의 탑신을 갖추고 있다. 기단 아래로는 탑을 옮길 때 마련해 둔 3단의 받침이 놓여 있어 전체적으로 높다란 풍채를 보인다. 기단은 각 층마다 면의 모서리와 가운데에 기둥 모양을 새겨 두었으며, 윗면에 3단의 얕은 층을 내어 윗돌을 괴고 있다.","a":"태안사삼층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662161.jpg"},{"q":"이 판본은 추계 추씨인 추적 선생(1246∼1317)이 편저한 것이다. 추적은 고려 원종 2년(1261) 문과에 올라 민부상서 예문관제학을 지냈다. 『○○○○』은 공자 등 제자백가의 책과 시부 가운데서 쉽고 생활에 기본이 되는 내용을 골라 엮은 책인데, 이것은 국가에서 세운 학교의 학생들에게 심성수양의 기본서로 삼기 위함이었다. 현재 전하는 것은 고종 6년(1869) 추세문이 출판한 인흥재사본이 전수되어 국역 출판됨으로써 가정, 학교에서 교육용으로 널리 쓰여왔다. 이것은 총 31장으로 인흥서원의 목판이 유일하다.","a":"명심보감판본","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636913.jpg"},{"q":"○○○○는 1910년 11월 울진지역에서 최초로 건립된 등대이다. 등탑의 구조는 평면 팔각형 콘크리트조 4층의 탑형 구조물(높이 15.6ｍ)로 상부로 갈수록 체감되어 안정감과 수직 상승감을 느끼게 한다. 이 등대는 1950년 6월 한국전쟁 중 폭격으로 인하여 등대기능을 잃기도 하였으나, 1951년 10월에 등탑을 보수·복구하였으며, 1970년 4월 안개시 보내는 소리신호기(무신호기)를 설치하여, 안개나 풍우 속에서도 선박의 항로를 인도할 수 있게 되었다.","a":"울진죽변등대","c":"시도기념물","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654668.jpg"},{"q":"감실은 정면 4칸, 측면 1칸으로 일반 가옥의 구조를 하고 있으며 앞면 4칸은 각 실의 구분 없이 각각 43cm으로서 주칸과 협칸의 구분 없이 동일한 척도로 계획되었다. 각 칸의 앞면으로는 둘레 10.5-11cm의 둥근 목재 기둥을 한칸 앞으로 내어 총 다섯 개의 기둥을 세웠으며, 안쪽 기둥 앞쪽으로 21cm 앞에는 난간을 설치하여 마감하였다. 전면 4칸에는 모두 이분합 격자교살문(格子交箭門)이 설치되어 있다.","a":"온양민속박물관 소장 사당형감실","c":"시도민속문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2019052217295500.jpg"},{"q":"장동면 장항마을 옆으로 흐르는 강가의 동산에 자리잡고 있는 정자이다. 조선 숙종 41년(1715)경부터 마을 사람들이 참석한 대동계의 집회소로 이용하던 마을 정자이다. 처음 지은 것은 세조 4년(1458) 동촌 김린(1392∼1474)이 관직에서 은퇴한 뒤, 은거하기 위해 지은 가정사(假亭舍)로부터 시작된다. 가정사는 선조 17년(1584) 후손인 김성장이 고쳐 지었고 김린이 심어 놓았던 동백나무가 울창하여 정자의 이름을 ‘○○○’이라 고쳤다. 지금 있는 건물은 1985년 후손들이 다시 고쳐 지은 것이다.","a":"동백정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662157.jpg"},{"q":"세조 1년(1455) 단종의 폐위와 세조의 왕위찬탈에 벼슬을 버리고 낙향한 ○○○ 이안(1414∼?)이 자신의 호를 따 지은 건물이다. 처음 세운 시기는 1450∼1460년대로 추정한다. 그 후 ○○○은 함풍 이씨 가문에서 관리해 온 것으로 보이는데 자세한 사실은 밝혀지지 않았다. 정유재란(1597) 중에 불에 타 없어진 후 영수정이란 이름으로 다시 지었으며, 1820∼1821년 사이에 군수 권복과 김상직이 현재와 같은 규모로 지었다. 그 뒤 고종 20년(1883) 크게 보수하고, 1966년 수리하여 오늘에 이르고 있다.","a":"영파정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662156.jpg"},{"q":"강진청자박물관에 소장된 ○○○○○은 뚜껑과 대접이 조합을 이루는 그릇으로 현존 예가 많지 않다. 특히, 그릇 내외면에 가득 시문된 상감문양 등은 고려 후기 청자의 대표적 특징을 잘 보여 주고 있으며, 강진 사당리에서 뚜껑과 같은 조각이 출토되어 학술적 가치가 있다.","a":"청자상감운학국화문개합","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101118235700.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배 안에 넣어서 보관하던 유물 가운데 하나이다. ○○○○○상의 배속에 있던 유물 가운데 특징적인 것으로 진언 ·의례불서와 ○○○○를 꼽을 수 있다. 진언(범어로 된 긴 절구를 번역하지 않고 그대로 읽거나 외는 일)과 예수재(살아 생전에 미리 수행과 공덕을 닦아 두는 재의식), 수륙재(물이나 육지에 있는 외로운 귀신이나 배고파 굶주리는 아귀에게 공양하는 법회) 등 사찰행사에 관련된 내용을 기록한 책은 모두 90종의 판본으로 가장 많은 수를 보이고 있다.","a":"보림사사천왕상복장선종불서","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814442500.jpg"},{"q":"안동시 목성동 대원사의 뒤쪽에 자리잡고 있는 이 ○○○는 원래 삼태사의 한분인 김선평공을 모시기 위한 사당으로 1770년에 후손들이 건립하였으나 여러 사정으로 용도가 바뀌어 문중의 대소사를 의논하기 위한 ○○○로 사용하게 되었다. 이 ○○○는 건립된 이후 김원행(金垣行)이 ○○○ 현판을 쓰고, 김양근(金養根)이 담장을 쌓고 보수하였다. 그 후 담장과 건물이 비바람에 훼손되어 1804년에 원래보다 조금 아래 위치에 중건하였다. 이 건물은 정면 3칸, 측면 2칸으로 낮은 기단 위에 둥글게 다듬은 초석을 놓고 그 위에 둥근 기둥을 세웠다.","a":"안동김씨종회소","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663298.jpg"},{"q":"조선 후기의 성리학자 전우(1841∼1922)선생이 학문을 연구하던 곳이다. 선생은 임헌회 문하에서 20년간 학문을 배웠으며, 고종 19년(1882) 벼슬에 올랐으나 곧 사임하고 학문에만 전념하였다. 1910년 국권이 일제에 강탈되자 선생은 통분해하며 스스로 귀향하여 도학으로 국권을 회복하고자 노력하였다. 그러나 의병을 일으키지 않고 도학만을 이야기한다고 하여 지탄을 받기도 하였다. 1922년까지 이곳에서 도학을 가르치며 항일정신을 고취하여 민족정기를 진작하는데 일생을 바쳤다.","a":"간재선생유지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653375.jpg"},{"q":"○○○○○는 조선조 한성부 ○○○에 위치했던 ○○○의 동지로, 1621년(광해군 13) 목판으로 간행되었으며, 17세기 ○○○의 사회상을 잘 알 수 있고, 현전사례가 매우 드물다.","a":"훈도방주자동지","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636526.jpg"},{"q":"○○○ 북쪽에 위치한 자미산의 남쪽 자락 끝에 만들어진 백제 때 만들어진 돌방무덤(석실묘)이다. 이 무덤은 하나의 벽을 사이에 두고 2개의 돌방(석실)이 나란히 만들어진 쌍실분으로, 두 돌방 모두 널길(연도)과 배수시설을 갖추고 있다. 유물은 동쪽 돌방에서만 출토되었는데, 토기 1점과 은으로 된 모자장식 1점, 관 못이 나왔으며, 몇 점의 관 못으로 시신을 목관에 안치했음을 알 수 있다. 석실의 구조와 출토 유물로 미루어 보아, 이 무덤은 6세기 후반의 것으로 추정된다.","a":"나주흥덕리석실분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051809541800.jpg"},{"q":"60여 년전에 지은 양씨 종가댁이다. 600여 평의 대지 한가운데 안채가 있으며 바깥채는 안채와 마주보게 배치되어 있다. 안채는 마루를 중심으로 왼쪽에 큰방이 있고 오른쪽에는 부엌이 있다. 툇마루는 큰방과 마루 앞에만 있어 부엌 공간이 넓으며, 바깥채는 가운데 마루를 중심으로 왼쪽 앞에 방과 뒤쪽에 곡물을 보관하는 고팡이 있다. 마루방의 앞쪽과 뒤쪽에는 툇마루가 배치되어 있다. 양씨 종가댁은 안채·바깥채를 통틀어 방이 넷이고 툇마루가 셋이며, 마루방 셋이 배치되어 있는 제주도 전통 초가 양식 중에서도 다양한 공간구성을 보이고 있어 주목된다.","a":"양금석가옥","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659214.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 ○○○○의 세워진 시기는 알 수 없으나『김해읍지』에 의하면 옛 김해부 동쪽 다전동에 있었던 것으로 보인다. 그 후 향교가 있던 산이 무너져 숙종 14년(1688)에 지금의 위치로 옮겼다. 전체적인 배치는 공부하는 곳인 명륜당이 앞에 있고 제사지내는 곳인 대성전과 동·서무가 뒤에 있는 전학후묘의 형태로, 일반 향교의 배치와 비슷하다. 정문인 풍화루는 누형식의 건물이 아닌 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 된 1층 건물로 지어져 특이하다.","a":"김해향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641896.jpg"},{"q":"하나의 돌에 광배(光背)·불신(佛身)·대좌(臺座)를 새긴 불상으로 발 아래 부분은 땅속에 묻혀있다. 현재 높이는 3.63m이지만 묻혀있는 부분을 감안하면 4m가 넘는 커다란 불상일 것으로 추정된다. 민머리 위에 상투 모양의 머리묶음이 높이 솟아 있으며, 귀가 어깨까지 길게 늘어져 있다. 양 어깨를 감싸고 입은 옷은 좌우대칭으로 곡선을 그리면서 아래로 내려오고 있다. 어깨는 1.15m로 넓으며, 양 팔에 걸쳐진 소매자락도 발 아래까지 길게 표현되었다. 부처의 몸에서 나오는 빛을 형상화한 광배에는 머리광배 표현만 보이는데 지름이 1.82m로 상당히 크다.","a":"지당리석불입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639432.jpg"},{"q":"○○○은 동토 윤순거(1596~1668년) 선생이 종중과 문중의 자녀들을 교육하기 위해 1625년(인조 3) 종학을 창설한 데서 시작되었다. 이후 1628년(인조 6)에는 7칸 전후퇴의 백록당(상급교육과정)과 7칸 2층 누각인 정수루를 건립하고 '오가백록'으로 현액하면서 구체적인 ○○○의 면모를 갖추게 되었다. 이후 1645년(인조 23)에는 윤순거와 윤원거가 함께 종약(宗約)을 창제하였다. 원래 건물은 유봉에 있었으나, 분암으로 옮겨졌고, 현재 ○○○ 건물은 윤선거의 5대손인 윤정규가 새로 건립한 건물이다.","a":"종학당(정수루,숙사)","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639254.jpg"},{"q":"○○○ 선생이 살았던 마을에 서 있는 비로, 선생의 효행을 기리고 있다. 삼우당 ○○○은 고려시대 후기의 학자이자 문신이다. 중국에서 목화씨를 가져온 것으로도 잘 알려진 그는 효성이 지극하여 모친이 돌아가시자 묘곁에서 움막을 짓고 살았다. 당시는 왜적의 침입이 잦아 그들이 지나가는 곳마다 노략질이 심하여 모두 피난을 가고 있었는데, 그 만이 홀로 평상시와 같이 곡을 하고 있었다. 왜적도 그의 이러한 효성에 감동하여 나무를 다듬어 ‘효자를 해치지 말라’라고 써서 세워 놓도록 하니, 그 때부터 이 지역이 평안하였다 한다.","a":"산청 문익점 효자비","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663915.jpg"},{"q":"이 가옥은 회인현감이 기거하던 ○○로 전해져 오는 건물로 동헌은 현재 교회 자리에 있었으나 1952년경에 교회에 매각되어 철거되었다고 전해진다. 회인지역은 조선 태종 13년(1413)에 현을 삼고 현감이 부임하였다는 기록으로 보아 이때부터 ○○가 있었을 것으로 추측되나 정확한 기록은 남아있지 않다. 東軒은 수령이 政務를 수행하는 공적인 공간이라면 內衙는 사적인 공간이다. 따라서 內衙는 일반적으로 관아 입구에서 가장 멀리 떨어진 곳에 위치하며 살림채이기 때문에 상류주택의 안채와 같은 평면구조를 이루게 된다.","a":"보은 회인동헌 내아","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020033117445100.jpg"},{"q":"윤보선 전 대통령 등 윤씨 일가의 옛 집들이 모여 있는 곳에 자리잡은 집으로 공동으로 이용하는 솟을대문을 통해서 들어가도록 되어있다. ㄱ자형의 안채와 ㄴ자형의 사랑채가 어우러져 튼 ㅁ자형의 평면구도를 갖고 있다. 안채는 ㄱ자로 꺾어지는 툇마루를 두어 각 방을 드나들 수 있게 하였다. 사랑채는 왼쪽 3칸에 퇴칸을 두어 마루를 깔았고 주변을 조망할 수 있도록 꾸몄다. 헛간채는 사랑채와 안채의 바깥에 있으며, 1990년경에 윤경선이 지은 것이다. 중부지방 주택의 특징을 잘 보여주고 있는 집이다.","a":"윤제형가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658262.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나이다. 이 책은 원나라의 승려인 ○○○○의 ‘○○○○’을 편찬한 것이다. ○○○○은 고려의 혜감국사, 보감국사와 깊은 교류가 있던 인물로, 고려 말 이후 한국 불교계에 커다란 영향을 끼쳤다. 육범사성으로 이루어진 십법계(十法界)를 설명하면서, 범부의 자리를 벗어나 성인의 지위에 들어갈 것을 중심내용으로 하고 있다.","a":"보림사사천왕상복장몽산화상육도보설","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022813531800.jpg"},{"q":"강원특별자치도 원주시 소초면 ○○○ 탑고개의 커다란 암벽에 얕게 선으로 새겼다. 얼굴과 상체, 팔목 등은 총탄 자국으로 훼손되었으나 전체적으로 상태가 양호한 편이다. 정면에서 오른쪽으로 45도 정도 돌려 앉아 있는 옆모습을 새긴 ○○○이다. 신체 각 부분의 비례가 비교적 잘 맞고 통통한 편이다. 얼굴은 비교적 원만하고, 목 뒤로 내려진 머리카락은 어깨에 닿을 듯하다. 상체에 걸친 옷은 3∼4가닥의 선으로 왼쪽 어깨에서 오른쪽 허리로 흐르고 있고, 하체의 옷도 몇 가닥의 선으로만 간략히 표현하고 있다.","a":"원주평장리마애공양보살상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638163.jpg"},{"q":"○○○○○는 바둑판식 1기로서 ○○○ 신답마을의 경작지에 있다. 덮개돌은 화강암으로 땅 위에 반듯하게 놓여 있는데, 크기는 길이 210㎝, 너비 170㎝, 두께 100㎝정도이며, 덮개돌 상부 모서리에는 작은 돌로 문질러서 둥글게 판 알[卵] 모양의 성혈(性穴)이 10여 개가 있다. 이 성혈은 풍요(豊饒)와 다산(多産)을 의미하거나 태양을 상징한다고 본다. 덮개돌 아래의 양쪽에는 받침돌이 보이는데 내부 구조는 학술 조사를 실시하지 않아 자세히 알 수 없다. ○○○ 주변 일대는 언덕 같은 능선이 펼쳐져 있어 ○○○와 연관있는 유적이 분포할 가능성이 있다.","a":"상안동지석묘","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645902.jpg"},{"q":"이 비는 ○○○가 살던 집터를 기념하기 위하여 1914년에 후손들이 세웠다. ○○○는 조선 인조 때의 문신으로서 본관은 은진이며 자는 원유元裕호는 수옹遁翁이고 우암 송시열의 아버지이다 그는 1617년(광해군 9)에 사마시t에 합격하여 성균관 유생으로 있을 때 인목 대비의 유폐를 반대 하다가 유생의 명단에서 삭제되어 벼슬길이 막히었다. 그 후 1623년 인조반정仁祖反正때 강릉 참봉을 지냈으며 다음 해 이괄의 난 때 공주公州로 임금이 탄 수레를 호위 하였고, 1627년 정묘호란 때 조선과 후금 사이에 화의가 성립 되자 분개하여 벼슬을 버렸다.","a":"옥천 송갑조 유기비","c":"문화유산자료","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660816.jpg"},{"q":"두정(頭頂) 갑옷은 조선후기에 발달한 방호복으로 현재 몇 벌의 유물이 전해 내려오고 있다. ○○○ 갑옷과 투구는 송공단(宋公壇) 제향 때 입었던 제복(祭服)으로 전해지고 있다. 육군박물관에 소장되어 있는 연대가 정확한 ○○와 비교해 본다면, ○○○○○는 전문 장인에 의하여 조선후기 갑옷의 형식을 충실히 지키면서 제작된 것으로 추정된다. 우리고장 순국선열의 충절이 담긴 유물일 뿐 아니라, 조선후기 갑옷과 투구의 모습을 보여주는 귀중한 자료로서, 우리나라 무관복(武官服) 연구에 많은 도움을 주는 중요한 자료로 평가된다.","a":"동래영 갑주","c":"시도민속문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658094.jpg"},{"q":"조선 후기에 세운 것으로 추정하는 집이다. 원래는 초가지붕이었으나, 지붕개량사업 당시 기와지붕으로 바꾸었다. 지붕에는 통풍을 위한 까치구멍을 뚫어 놓았었지만 기와지붕으로 바뀌면서 현재는 그 모습이 남아 있지 않다. 앞면 3칸·옆면 2칸 규모이며 중앙의 마루와 봉당을 중심으로 좌우에 각각 방 2칸과 부엌 1칸·방 1칸을 배열하였다. 일반적인 까치구멍집 평면에서 마구간이 있어야 할 자리에 방을 둔 것이 평면상 특징이다. 이러한 평면은 6칸 까치구멍집의 초기형태를 보이고 있어 겹집의 발달 과정을 볼 수 있는 좋은 자료이다.","a":"영주수도리김규진가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663212.jpg"},{"q":"‘포천 ○○○○’은 조선 후기의 유학자인 이항복(李恒福, 1556년-1618년)의 학문과 덕행을 기리기 위해 그의 위폐를 모신 곳이다. 그는 ‘청백리’(淸白吏])에 뽑히기도 하였다. 1631년에 사당을 지었을 때의 이름은 ‘백사서원(白沙書院)’이었다. 이후 서원은 1635년에 화봉산 아래로 옮겨졌으며, 1720년에 이곳 지명을 딴 ‘화산(花山)’이라는 이름으로 사액(賜額; 조선 시대에 임금이 사당이나 서원 등에 이름을 지어 새긴 편액(扁額)을 내리던 일) 되었다.","a":"화산서원","c":"시도기념물","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646075.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○시 사등면 국도변에 약 50m의 간격을 두고 바둑판식 고인돌 3기가 있다. 국도변 언덕에 있는 1호는 현무암으로 된 덮개돌을 2개의 작은 받침돌이 받치고 있는 모습이다.","a":"거제 청곡리 지석묘","c":"문화유산자료","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664023.jpg"},{"q":"1910년도에 초창된 다포팔작식 목조건물인데 망우당 곽재우 장군과 17장령의 증직명과 관향 등이 적힌 명판을 부착한 ○○○으로서 어느 한 곳에도 쇠못을 사용하지 않은 우리나라 전통 목조건물의 건축양식으로 지어졌으며, 조선후기 건립된 다포팔작양식으로 극락세계를 염원하는 상여모양을 본뜬 건물이다.","a":"의령 충의각","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666725.jpg"},{"q":"○○○는 산왕(山王)으로 신앙되던 호랑이가 의인화(擬人化)된 산신(山神)을 표현한 불화이다. 호랑이는 예로부터 산의 신령으로 믿어져 왔는데 차츰 신앙의 대상으로까지 신격화되었으며, 이를 불교에서도 받아들여 신앙의 대상으로 삼았다. 우리나라에서는 고려시대까지는 산신에 대한 신앙이 없었던 것으로 보인다. 조선시대에 들어와 불교가 민간신앙과 결합하면서 토착화하는 과정에서 산신에 대한 신앙이 유행하게 되었고, 조선시대의 사찰에는 대개 산신각(山神閣)을 세워 상과 불화를 봉안하고 있다.","a":"수원 청련암 산신도","c":"문화유산자료","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660287.jpg"},{"q":"이곳은 고려말의 충신이며 원나라로부터 목화씨를 가져와 우리나라 의복문화에 혁신을 가져온 문익점의 18세손인 문경호가 1840년을 전후하여 터를 잡아 ○○○○ 일족이 모여 살던 곳이다. 원래 인흥사의 절터였던 곳을 구획하여 집터와 도로를 반듯하게 정리하고 집을 지었다. 현재 아홉 가구의 살림집과 수봉정사, 광거당, 인수문고 등이 한울속에 정연하게 자리잡고 있는데, 풍치 있는 토담으로 둘러싸인 부지 안에 총 70여 채의 전통와가가 들어서 있다. 수봉정사는 ○○○의 입구에 있는 정자로 정원을 매우 아름답게 꾸민 곳이다.","a":"남평문씨본리세거지","c":"시도민속문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658103.jpg"},{"q":"○○○은 고려의 무신으로 ○○ 출신이며 본관은 ○○고, 시호는 충숙(忠肅)이다. 향공진사(鄕貢進士)로 ○○별초(原州別抄)에 있으면서 1291년(충렬왕 17) 합단적(哈丹賊)이 치악성(雉岳城)을 포위하자, 전후 10차에 걸쳐 적을 크게 무찔렀다. ○○○의 이러한 공로로 ○○는 익흥도호부(益興都護府)로, 다시 1308년 ○○목(原州牧)으로 승격되었고, ○○에 부과되던 각종 부역과 잡공이 3년 동안 면제되었다. ○○○ 또한 여섯 번 전임(傳任)하여 삼사(三司)우윤(右尹)에 올랐다.","a":"원주 원충갑묘역","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660637.jpg"},{"q":"숲이 울창한 야산을 뒤로 하고있는 집으로 1894년에 안채를 짓고 1915년에 사랑채를 지었다. 영동지방의 전형적인 ㅁ자형 주택으로, 대문을 중심으로 오른쪽에는 사랑채·왼쪽에는 부속채 그리고 맞은편에는 안채가 배치되어 있다. 안채는 앞면 6칸·옆면 2칸의 一자형 집으로, 왼쪽부터 부엌 2칸·안방 2칸·대청·건넌방의 순서로 되어있다. 방과 대청 앞쪽에는 비교적 넓은 툇마루가 안뜰을 향하여 있다. 안채와 마주 보도록 되어있는 사랑채는 ㄱ자형 겹집으로, 대청과 방으로 구성되어 있다.","a":"강릉 만성 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638095.jpg"},{"q":"구석찬씨 댁에 소장된 『勝聰明錄』은 月峯 仇相德(1706-1761)이 쓴 일기로서, 그가 20세가 되던 1725년부터 56세로 별세한 1761년까지 37년간 하루도 빠짐없이 기록하였다. ○○○○의 가치는 18세기 농촌사회의 구체적인 삶과 그 변화과정을 여실하게 파악해 볼 수 있다는 점이다. 자신이 살던 고성지역을 중심으로 벼농사와 보리농사의 파종과 이앙시기, 춘궁기의 생활문제, 물가의 등귀, 도둑, 전염병, 기근, 자녀교육, 마을의 관혼상제, 官家와의 관계, 여러 가지 奇言怪語 등 일상생활에서 부딪히는 온갖 사건들이 여과 없이 기술되어 있다.","a":"구상덕 승총명록","c":"시도유형문화유산","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642674.jpg"},{"q":"금새 마을에 자리하고 있는 석탑으로, 집터를 다지던 중 탑의 부분석재가 발견되어 복원해 놓은 것이다. 마을 이름은 ‘금사(金寺)’라는 절이름에서 따온 것이라 하며, 공사 당시 금동으로 만든 불상의 일부분이 함께 발견되어 이 일대가 절터였음을 뒷받침해준다. 탑은 동그란 판돌 위로 탑의 몸돌이 하나 놓여 있고, 그 위로 5개의 지붕돌을 차례로 쌓아 올린 모습이다. 둥근 판돌이 이 탑의 기단(基壇)역할을 하는 듯 하나, 원래의 것은 아닌 것으로 보인다. 하나만 남아있는 탑신의 몸돌은 네 모서리에 기둥 모양을 새겨 놓았다. 지붕돌은 각층에 3단의 받침이 있다.","a":"금암리오층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661031.jpg"},{"q":"○○○는 백제 무왕 41년(640)에 자장율사가 세웠다고 전한다. 절 경내에는 ○○○을 비롯하여 대웅전, 영산전, 대광보전, 홍성루 등 많은 건물들이 남아 있다. ○○○은 조선 후기에 세웠으며, 건물에 남아 있는 기록으로 보아 1910년에 고쳐 지었다고 한다. 절 입구에서 두번째 있는 문인 ○○○은 앞면 3칸·옆면 2칸 규모이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 되어 있다. 천장은 지붕의 뼈대가 그대로 드러나 있는 연등천장으로 꾸몄고, 안쪽에는 동서남북 4지역을 지키는 ○○○상과 그림이 있다.","a":"마곡사천왕문","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660972.jpg"},{"q":"○○○ 마을에 흩어져 있는 비와 부도들로, 모두 11기에 이른다. 비는 낮은 사각받침돌 위로 길쭉한 비몸을 세운 모습이며, 비의 윗변이 둥글게 다듬어져 있다. 승려의 사리를 모시고 있는 부도는 낮은 받침 위로 종모양의 탑몸돌을 올리고 있는데, 꼭대기에 꽃봉오리 모양의 머리장식을 얹은 것도 있고, 지붕돌을 올려 놓은 것들도 있다. 이 곳에는 봉암대사의 ○○도 함께 자리하고 있는데, 이 비만이 원래의 자리를 그대로 지키고 있었고, 나머지 유물들은 이 일대의 부도밭을 허물어 논밭으로 만들 때 곳곳에 흩어져 있던 것을 이곳에 옮겨놓은 것이라 한다.","a":"합천 중촌리 승탑 및 탑비","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663994.jpg"},{"q":"이 족보는 하증이 편찬한 것을 저본으로 내용을 추가한 것으로 판단되며, 현재 단지종택에 소장되어 있는 족보 중 가장 오래된 것이다. 외손은 3대까지 기록하고 있다. 후대로 오면서는 중요 계보의 인물이나 특정 인물에 대해서만 간단한 기록을 하고 있고 나머지는 이름만 적고 있는 점이 특이하다. 원래 ○○○○ 초간보는 1621년 창주 하증의 주도로 편찬되었다고 하지만 전해지지 않고 있으며, 1719년에는 하형에 의해 기해보가 중간되고, 그 후 1770년 경인보, 1820년 경진보, 1898년 무술보 등이 간행되었다.","a":"진주단목리단지하협종택소장진양하씨무인보","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666259.jpg"},{"q":"파평 윤씨가 지은 집으로 지은 시기를 정확하게 알 수 없으나 광산 김씨 집안에서 5대에 걸쳐 살다가 고 임수택 씨가 소유하였다. ㄷ자형 안채와 ㅡ자형 문간채가 어우러져 ㅁ자형을 이루고 있었으나 한국전쟁으로 문간채는 불타고 현재 안채만 남아 있다.","a":"임수택가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661359.jpg"},{"q":"○○○○는 신라 제54대 경명왕(景明王)의 제8왕자인 월성대군(月城大君)의 자손으로 고려 후기에 두각을 나타내기 시작하여 조선 전기와 중기에 크게 융성하였다. 중시조인 박구(朴龜,1337∼1404)는 고려 중군사정부령(中軍司正副令)을 역임하였는데, 고려가 망하자 이 곳에 칩거하면서 자신을 감춘다하여 호를 ‘장아(藏我)’라 하고 뒷산을 장아산이라 하였다. 장아산(해발 73.6m)서쪽 구릉에 위치한 ○○○○○에는 현재 박구와 그의 후손인 박간(朴幹), 박휘(朴徽), 박신겸(朴信謙),박호겸(朴好謙), 박홍중(朴弘中) 등 11기의 묘가 남아 있다.","a":"월성박씨 종중 묘역","c":"시도기념물","nc":"","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016030809514300.JPG"},{"q":"조선 중기의 문학자였던 지봉(芝峰) ○○○ 선생의 묘이다. 1614년(광해군 6)에는 『지봉유설』을 간행하여 우리나라 최초로 천주교와 서양문물을 소개함으로써 실학 발전의 선구자가 되었다. 묘역은 부인 안동김씨(安東金氏)와 합장된 단분(單墳 ; 하나의 봉분)의 형태이다. 동자석인은 두 손을 공손히 모아 서 있는 모습으로 미소를 띠고 있다. 머리는 쌍계형(雙髻形 ; 두 개의 상투머리가 위로 솟은 형태)으로 묶고 어깨장식을 둘렀으며, 허리띠를 묶어 내린 17세기의 전형적인 동자석인이다.","a":"이수광선생묘","c":"시도기념물","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646092.jpg"},{"q":"이 보살상은 낙동강살리기사업 제32공구 현장의 낙단보 통합관리센터부지 조성공사 중에 발견된, 전체높이 213㎝, 像 높이 164㎝ 크기의 ○○○○○이다. 좌우로 약간 벌어진 三山形의 보관을 쓰고 한 손에는 연꽃가지를 쥐고 있다. 평면적으로 線刻된 佛身 위의 着衣상태는 알 수 없으나, 등 뒤쪽에는 원형의 頭光과 身光이 얕게 새겨져 있고, 臺座도 이중선으로 새겨진 複葉의 연화대좌이다. 이 보살상의 제작기법은 신체를 線刻에 가깝게 평면적으로 새긴 반면에 얼굴부분은 사실적으로 정교하게 低浮彫하였다.","a":"의성 생송리 마애보살좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641238.jpg"},{"q":"지방마다 설치하여 토지의 신과 곡식의 신에게 제사하던 ○○○○○은 신증동국여지승람, 여지승람, 호서승람 등 다수의 지리지 단묘(檀廟)조에 “○○○은 고을 서쪽에 있다.”고 기록되어 있으며, 충청도 읍지, 광여지도 등 고지도에 위치가 표시되어 있다. 이웃한 ○○향교, ○○ 인산객사 등과 함께 지역 문화와 역사의 자료로 문화유산으로 지정 보호할 가치가 있다.","a":"보은 회인 사직단","c":"시도기념물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020033117425100.JPG"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 지어진 연대는 확실히 알 수 없으나 정유재란(1597)으로 불타 없어진 것을 선조 32년(1599)에 초가집으로 다시 지었으나 위치가 좋지 않다고 해서 인조 3년(1625)에 현 위치로 옮겼다. 지금의 건물들은 근래에까지 여러 차례 수리한 건물이다. 현재 남아있는 건물은 대성전·명륜당·동재·서재·내삼문 등이 있다.","a":"함평향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639971.jpg"},{"q":"○○○의 부속암자인 ○○○에 놓여 있는 석등이다. 등불을 밝혀두는 화사석(火舍石)을 중심으로 아래에는 세 받침돌로 구성된 받침을 두고, 위로는 지붕돌과 머리장식을 얹었다. 8각의 아래받침돌은 각 면에 안상(眼像)을 조각하고, 윗면에 연꽃무늬를 둘렀다.4각의 가운데기둥은 길고 가늘어 보인다. 윗받침돌은 8잎의 연꽃을 둘러 놓았고, 밑면에 1단의 받침을 두었다. 8각을 이루는 화사석은 4곳에 창을 마련해 놓았다. 지붕돌은 여덟 처마가 곡선을 이루고 있으며, 각 귀퉁이가 위로 들려있다. 꼭대기에는 머리장식으로 보이는 둥근 석재가 놓여있다.","a":"화엄사구층암석등","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639997.jpg"},{"q":"○○○○○은 1955∼1958년에 지어진 ○○○ 사택들이 있는 곳으로, 이 중 최초(1955년)에 지어진 북측의 3동이다. 1990년대 초 ○○○들이 한국을 떠난 후 사택의 일부에 한남대 설립자인 인돈(印敦. Ｗilliam Ａlderman Linton, 1891∼1960)을 기념하는 인돈학술원을 개원하고, 유물을 보관·전시하고 있다. 1950년대 국내 시대상이 반영된 건물들로 붉은 벽돌에 한식지붕을 올린 점이나 주진입이 현관으로 모이는 점 등에서 서양식 건축에 한국 건축양식을 도입한 모습을 볼 수 있다.","a":"오정동선교사촌","c":"문화유산자료","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659756.jpg"},{"q":"○○○○○은 여강이씨 문중의 16대조 덕삼(德三 1654-1712)공을 사대봉사하기 위한 별묘로부터 비롯되었다 하나, 정확한 건립 시기는 불명확하다. 채집 가능한 자료를 분석·추정해보면 현재와 같은 모습을 갖춘 것이 늦어도 19세기 중반 이전이라는 것 정도만 확인이 된다. 현존하는 전통건축 중 서당이 흔치 않음을 고려해 볼 때 ○○○○의 역사적인 가치는 가볍다 할 수 없다.","a":"포항 오덕리 덕계서당","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017122211182400.JPG"},{"q":"고려산(해발 436m)의 서쪽 능선을 따라 해발 350∼250m 지점에 18기의 고인돌무덤이 흩어져 있다. 우리나라 고인돌무덤이 분포하는 평균 고도보다 훨씬 높은 곳에 위치하고 있다. 대부분의 고인돌 무덤들은 무너져 원형이 많이 훼손된 상태이다. 그 중 비교적 잘 보존되어 있는 북방식 고인돌무덤은 덮개돌의 크기가 가로 3.35m, 세로 2.47m, 두께 0.65m이다. 가까운 거리에 있는 암석에는 고인돌무덤을 만들기 위하여 돌을 떼낸 흔적이 남아 있다.","a":"강화 고천리 고인돌군","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645664.jpg"},{"q":"조선 후기 성리학자인 유중교(1821∼1893)가 후진을 양성했던 곳으로 고종 26년(1889)에 창주정사로 세웠는데 1906년 유림에서 ○○○○으로 새롭게 세웠다. 고종 32년(1895)에는 의병장 유인석(1842∼1915)이 팔도 유림들을 모아 비밀회의를 하던 곳이기도 하다. 유중교는 이항로와 김평묵의 제자였으며 그들의 영향을 받아 위정척사론을 주장한 인물이다. 유인석 역시 이항로의 문하에 있었으며 위청척사론자이자 의병장으로 적극적인 항일 운동을 전개시켰다. 이곳에는 주자·송시열·이화서·유중교·유인석·이직신의 영정을 모시고 있으며 해마다 봄·가을에 제사를 지낸다.","a":"제천 자양영당","c":"시도기념물","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649668.jpg"},{"q":"○○○○은 추담 윤선(1559∼1640) 선생의 공적과 학덕을 기리고 충효정신을 선양하기 위하여 무오년(1918)에 건립되었다. 윤선 선생은 선조에서 광해군의 양대에 걸쳐 대사간, 대사성, 도승지, 의정부 우참찬 등을 역임하였으며, 청백리에 녹선되었다. 선생의 위패는 ○○ 임란창의사에 봉안되어 매년 5월 10일 향사를 지내고 있다. 뒤쪽 경사지형에 대문채와 서당을 일직선상에 배치하고 강당의 좌·우에 동·서재를 앉힌 ‘口’자형 배치형식이며 정면과 측면의 일부에 담장을 둘렀다.","a":"합천 회계서당","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664881.jpg"},{"q":"고종 6년(1869)을 12월에 작성한 필사본으로 당시 서귀포 ○○○의 군병 현황이 수록되어 있다. 세부적으로는 ○○○과 ○○○ 관내 각 현에 소속된 군병(軍兵)들의 편오 명단, 각 군병(軍兵)의 부친 명단, 각 군병(軍兵)이 배치된 지역 명단 등이 자세하게 기록되어 있다. 1869년에 작성했지만 이듬해인 1870년을 기준으로 했다.","a":"대정군 군병도안","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643349.jpg"},{"q":"조선 태종(재위 1400∼1418)의 열 번째 아들인 희령군 타를 모시고 제사지내던 사당이다. 원래는 서울 동대문 밖에 있었으나, 병자호란 때 불에 타 없어진 후 150년이 지난 정조 16년(1792)에 왕의 명으로 사당을 세웠다. 희령군의 시호를 따서 ○○○라고 하였다. 사당은 앞면 3칸·옆면 3칸 규모의 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 특이한 평면구조와 조각수법을 보이고 있는 이 사당은 종묘의 건축 양식과 비슷한 구조·양식을 띄고 있어 일반 사대부 가정집의 사당과는 격식을 달리하고 있다.","a":"이정사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640956.jpg"},{"q":"조선 고종 때의 학자이자, 성리학의 6대가 가운데 한 사람인 노사 기정진(1798∼1876)의 문집과 그의 저서『○○○○』을 고종 39년(1902)에 ○○에 새긴 것으로, 문집은 653매,『○○○○』은 209매이다. 기정진은 어려서부터 성리학의 깊은 이치를 깨우쳤으며, 경서·사서 등을 읽었다. 1831년 사마시에 장원으로 급제한 후 강릉참봉을 지냈으며, 그후 여러 벼슬이 내려졌으나 모두 나아가지 않았다. 그의 학문은 스승으로부터 전수받거나 어느 학파에 근거를 둔 것이 아니라 성리학에 대한 독자적인 사색에 의해 높은 경지에 이르렀다.","a":"장성 고산서원 노사선생 전집 및 답문류편 목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018112114465100.jpg"},{"q":"이 곳은 『삼국유사』에 나오는 연오랑세오녀 전설이 있는 곳이다. 신라 제8대 아달라왕 4년(157)에 신라 동쪽 일월동 바닷가에 어부인 연오랑과 베를 짜던 세오녀 부부가 살고 있었다. 어느날 연오랑이 고기를 잡고 바위에 앉아 해초를 따던 중 갑자기 바위가 움직여 동쪽으로 흘러가 일본의 섬나라에 도착하였는데, 그곳 사람들은 이를 신비하게 여겨 왕으로 모셨다. 한편 세오녀는 연오랑을 찾아 헤매다가 그의 신발을 발견하고 바위에 서니 바위가 다시 움직여 연오랑이 있는 섬에 도착하여 왕비가 되었다고 한다.","a":"영일 일월지","c":"시도기념물","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654601.jpg"},{"q":"○○ 도천리 ○○○는 철종 6년(1855) 4월 하문도·하락도 형제가 ○○○를 짓고 같은 해 ○○○판 호정집(浩亭集)을 다시 간행한 곳이다. 철종 12년(1861년) 이후부터 최근까지 후학을 양성하는 기관인 위양서원으로 이용하다가 학생이 줄어 문을 닫았다. 문충공 하륜의 사당인 문충사, 위양서원, 선장각, 동·서재 등은 없어졌지만 2009년 11월 경상남도 문화유산으로 지정되어 ○○○를 해체·보수한 상태로 관리되고 있다. 1976년에 문충공(文忠公) 하륜(河崙)의 제19세손 종손 하경식(河景植)이 ○○○ 기와를 보수한 이력이 있다.","a":"함양 경충재","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2642989.jpg"},{"q":"우물이 자리한 지역은 부여 두리라는 자연마을로서, 부여 왕씨의 하나인 부여서씨가 거주한 지역으로 전해지며 오래전부터 이 지역은 만가대(萬家垈)라 불리어져 왔다. 우물 깊이는 5.2m이며, 지상부는 정자형(井字形)으로 결구되어 있는데 석재가구 한변의 길이는 180cm이고 높이는 45cm이다.","a":"부여용당리우물","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661566.jpg"},{"q":"조선 명종 15년(1560) 9월 19일 왕이 문과와 무과의 여러 신하들을 불러 창덕궁 ○○○에서 연회를 즐기는 광경을 묘사한 그림이다. 화면을 3등분하여 나누어 맨 윗부분에 ‘총○○○○○’라는 그림의 제목과 함께 연회 장면을 사실적으로 그려 놓고, 가운데에는 당시 의정부 좌찬성으로 있던 홍섬의 글을 실었으며, 아래에는 연회에 참석했던 문신과 무신 74인의 이름을 적어 놓았다.","a":"서총대친림연회도","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640767.jpg"},{"q":"경사진 대지에 자리잡고 있는 집으로 앞쪽에 사랑채를 배치하고 뒷쪽에 안채를 두었다. 안채는 조선 후기에 짓고 1924년 경에 고친 것으로 추정한다. 안채는 큰방·작은방·부엌 이외에는 모두 마루를 꾸며 특이한 평면을 이루고 있으며, 평면에 따라 지붕의 형태가 다르다. 사랑채 지붕은 원래 초가지붕이었다고 하며 매우 간소하게 꾸몄다.","a":"나주김효병가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658361.jpg"},{"q":"제주도에는 역사가 오래된 마을마다 ○○○○가 존재하는데, 이 ○○○○는 화북 포구 근처에 자리잡고 있다. 화북지방은 옛부터 제주와 육지를 잇는 첫 관문으로 많은 관리들이 이곳을 거쳐갔었는데, 이러한 제주목사나 판관 등 지방관리들의 부임 또는 이임시 이들의 공적과 석별의 뜻을 기리는 의미에서 비를 세워놓았다 한다. 모두 13기의 비석이 남아 있는데, 양 기둥을 세운 채 그 안에 비몸을 세우고 머릿돌을 올린 형태와 단순한 직사각형 비몸돌로만 이루어진 형태, 모서리 양끝을 둥글게 처리한 형태 등의 모습을 하고 있다.","a":"화북비석거리","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657867.jpg"},{"q":"○○는 ‘담비’라는 족제비과 짐승의 가죽으로 만든 옷을 이른다. 이 옷은 조선 효종이 입던 겉저고리를 ○○○○○에게 하사한 것이다. 노란털의 빛깔이 곱고 따뜻해 보이는 이 옷은 양팔을 벌린 너비가 184㎝이며, 등솔기의 세로 길이는 95㎝이다. 안쪽면에는 ○○의 친필로 옷에 얽힌 내력을 상세하게 적어 놓았다. 원래 비단천으로 된 안감이 있었는데, ○○이 죽어 저 세상으로 갈 때 임금이 하사한 옷을 전부 입고 갈 수는 없다 하여 안감만 뜯어 입고 가서 모피만 남은 것이라 전한다.","a":"우암 송시열 초구 일령","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658070.jpg"},{"q":"이 불상은 현재 ○○○ 독성각에 봉안된 ○○○으로 소조불이다. 독성은 나반존자라고도 하는데 남인도의 천태산에 거주하며 부처님의 수기를 받고 열심히 정진하는 나한 중의 한 분으로서 우리나라에서는 조선 후기에 산신 및 칠성과 함께 삼성각에 봉안하거나 따로 독성각에 봉안하여 신앙하였다. ○○○은 현재 소조의 불상에 채색을 하여 봉안하고 있는데 신체에 비하여 얼굴이 크고 두 손을 무릎 위에 댄 모습 등 칠성각의 석불좌상과 닮았다.","a":"진관사 소 독성상","c":"문화유산자료","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659303.jpg"},{"q":"하마비란 조선시대 종묘 및 대궐 문 앞에 세워놓던 비로, 누구든지 그 앞을 지날 때에는 말에서 내리라는 뜻의 글을 비에 새겨 두었다. 민간신앙에 기초를 둔 것으로, 이 비의 주변에는 10여기의 고인돌이 흩어져 있다. 자연석을 그대로 이용한 비는 앞면에 보살상을 새겨두고, 그 아래 ‘하마비’라는 글자는 시멘트로 만든 하단에 새겼다. 불상의 머리위에 보관(寶冠)이 표현된 것으로 미루어 보살상으로 짐작되며, 고려말·조선초 세운 것으로 보인다.","a":"완도 청산도 석조보살좌상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662045.jpg"},{"q":"○○○는 서울특별시 서초구 예술의 전당 위쪽에 있는 사찰로, 한국전쟁 때 소실된 것을 1954년에 다시 지었다. ○○○에 모셔진 이 불상은 3.1운동 당시 민족대표 33인 중 한사람인 백용성 스님이 만들었다고 전해진다. 백제 제15대 침류왕 1년(384) 인도의 마라난타 대사가 설법하러 백제에 오는 동안 병이 들었는데 우면산 생수로 병을 고쳤다고 한다. 그리하여 우면산 기슭에 대성초당을 창건함으로써 이 우면산 ○○○는 백제 불교의 성지가 되었다. 조선 명종 때 보우대사는 이 절에 머물면서 불교 중흥을 구상했다고 한다.","a":"대성사목불좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636273.jpg"},{"q":"충청북도 ○○군 도안면 ○○○에 있는 전체 높이 4.8m, 불상 높이 4m나 되는 거대한 불상이다. 긴 얼굴에 눈은 반쯤 뜨고 정면을 바라보며, 목에는 3개의 줄 삼도(三道)가 있고, 귀는 긴 편이다. 위엄이 있으면서 자비로운 인상을 풍기고 있는 고려 초기의 작품이다.","a":"증평 광덕사 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638502.jpg"},{"q":"이맹산이라고도 부르는 ○○○의 서쪽 산정 가까운 곳에 있는 절터이다. 원래는 석굴사원인데 현재는 천장이 무너져 내려 원래의 모습을 알 수 없다. 통일신라시대에 만들어진 듯한 마애석불이 높은 절벽에 조각되어 있어 석굴과 밀접한 관련이 있을 것으로 여겨진다. 석굴은 벽체와 천장이 모두 무너져 원형을 잃었으나, 자연석을 돌담 쌓듯 포개어 쌓아 올린 형태의 다솔사의 보안암 석굴과 비슷한 형태였을 것으로 추정된다. 바위에 조각되어 있는 마애석불은 앉아있는 모습으로 대략 6m 규모이다.","a":"하동 이명산 석불사지","c":"시도기념물","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654843.jpg"},{"q":"○○○은 조선시대에 설강 유사(1502∼1571)가 지은 정자로, ○○○이라는 이름은 중국 송나라 소강절이 말한 ‘호가지의’에서 따온 것이다. 명종 13년(1558)에 처음 세웠으나, 임진왜란과 정유재란 때 불타 없어지고 고종 8년(1871)에 다시 지었다. 그 뒤 1932년과 1956년에 고쳐 지었다. 설강은 중종·명종대의 인물로 여러 관직을 지냈으나, 다른 관료의 모함으로 벼슬을 물러나 고향으로 돌아왔다. 그는 당시 이름 높은 유학자들과 교우하였으며, 후대 사람들이 그의 시를 즐겨 읊었다.","a":"호가정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659609.jpg"},{"q":"1930년대 후반 경성부(京城府)의 인구 급증에 따라 새로이 개발된 주거단지 중 하나인 ○○○〔일제강점기 때는 봉래정 4정목(蓬萊町 4丁目)〕지역에 1936년 신축된 상류층 도시형 한옥이다. 이 한옥을 최초로 건립한 ○○○씨는 흥국생명을 창립하고 동명고무(활표 고무신)와 삼정광업을 운영한 신흥자본가이다. 구(舊) ○○대장에 의하면 건립 당시의 규모는 지하 1층(4평)·지상 1층(38평)이었고, 구조는 목조와즙(木造瓦葺)이었다.","a":"만리동 정영국 가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658083.jpg"},{"q":"앵산鶯山 중턱 광청사 뒤에 위치한 이 곳 북사 터에는 산의 계곡부 경사에 축대를 짜서 평탄하게 만든 대지가 세 군데 있는데 초석건물지 2동, 사이에 계단, 담장, 석축, 중정*등이 남아 있다. 북사에 대한 기록은 현재 일본 사가현佐賀県 혜일사惠日寺에 보관된 북사 동종*이 유일하다. 동종에 1026년에 종을 달았다고 새겨져 있기 때문에 북사의 창건 시기는 그보다 앞설 것이다.","a":"거제하청북사지","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656650.jpg"},{"q":"척화비란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양 사람들을 배척하고 그들의 침략을 더욱 강력히 국민에게 경고하기 위해 서울 및 전국의 중요 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 비는 반듯한 사각받침돌 위로 비몸을 세운 모습이며, 비몸의 네 모서리와 윗변의 양끝을 단정히 다듬어 놓았다. 앞면에는 비문을 새겨 두었는데 내용에는 “서양오랑캐가 침입하는데 싸우지 않으면 화해할 수 밖에 없고 화해를 주장하면 나라를 파는 것이 된다”는 강한 어투의 경고를 적고 있다.","a":"장기척화비","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662863.jpg"},{"q":"대한불교조계종 제6교구 본사인 ○○○의 대광보전 후불탱화로 걸려있는 불화이다. ○○○○○는 석가모니가 영취산(靈鷲山)에서 제자들에게 『법화경(法華經)』을 설법한 모임을 도상으로 옮긴 불화(佛畵)이다. 화기에 따르면, ○○○○○는 정조 12년(1788) 동홍 등 15명의 화승이 함께 조성하였다. 대형의 화면에 석가모니불이 영취산에서 법화경을 설하던 장면인 설법회를 짜임새 있게 그렸으며 비교적 탁한 색감과 도식적인 음영표현 등 18세기 후반기 불화의 특징을 잘 보여주고 있다.","a":"공주 마곡사 영산회상도","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639314.jpg"},{"q":"구한말 독립운동가이며, 이 지역의 대표적인 유학자인 정산 김동진(1867∼1952)선생이 후진 양성을 위해 세운 서당이다. 김동진 선생은 구한말 영남지역의 대표적 유림 중 한 사람이다. 일제시대에는 독립운동에도 활발히 참여하여 몇 차례 투옥되기도 하였으며, 끝까지 상투와 한복을 고수하였다. ○○○○을 세운 시기는 구체적으로 알 수 없으며 규모는 앞면 3칸·옆면 2칸으로 담장이 없다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 가운데 칸은 마루로 하고 양쪽 칸에는 온돌방을 두었는데 사방에 쪽마루를 둘러 놓았다.","a":"도강서당","c":"시도기념물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654626.jpg"},{"q":"고려 후기의 무신인 경렬공 정지(1347∼1391) 장군의 묘소이다. 공민왕 14년(1365)에 사마시에 장원급제하고 이듬해 문과에 급제하여 벼슬길에 올랐다. 공민왕 23년(1374)에 우리나라 최초로 수군 창설 계획을 올려 전라도 안무사로 발탁되었으며, 우왕 3년(1377)에는 순천 도병마사가 되어 순천·낙안 등지에 침입한 왜군을 격퇴하였다. 우왕 14년(1388)에 이성계의 위화도회군에 종군하여 그 공로로 공양왕 2년(1390)에 2등공신에 봉해지면서 판개성부사로 임명되었으나 부임하지 못하고 병으로 세상을 떠났다.","a":"정지장군예장석묘","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645733.jpg"},{"q":"○○○○○은 오래전부터 秘佛로 ○○○에 보존하고 있던 불상으로 복장기를 살펴볼 때 숭정 구년(1636년, 인조 14년)에 조성되었다. 아울러 朱記에 大韓光武 11年(1907년)에 改金을 추측할 수 있는 기록이 있다. 좌고가 30㎝인 소형 불상으로 머리에 두건을 쓰고 상호는 원만하며 兩眉間, 鼻粱, 口脣 등 각부도 정제되어 있다. 양미간에는 백호가 있으며 목에는 삼도가 남아 있다. 양쪽 귀는 긴 편이 아니나 목에는 삼도가 있어 원만하고 자비로운 상호이다. 법의는 양쪽 어깨에 걸친 通肩衣로 유려하게 흘러내려 양쪽 무릎을 덮고 있다.","a":"제천 경은사 목조문수보살좌상 및 복장유물","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101620181500.JPG"},{"q":"지방의 수령(守令)이 공무(公務)를 처리하던 곳을 관아(官衙)라 하는데, 『밀주구지(密州舊誌)』에 ○○의 관아에 대하여 “아사내외 동서헌별실백여간임진왜란탕진무여 만력신해부사원유남중창(衙舍內外 東西軒別室百餘間壬辰倭亂蕩盡無餘 萬曆辛亥府使元裕男重創)이라는 기록이 있는 것으로 봐서 ○○읍성이 축조될 당시에 관아도 백여칸으로 지어진 것으로 보인다.","a":"밀양 관아지","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657529.jpg"},{"q":"한말의 우국지사 이주환과 그의 스승인 송병선, 송병순의 제사를 모시는 사당이다. 송병선(1836∼1905)은 송시열의 9세손이며 송병순의 형이다. 조선 후기 문인이었으나 벼슬길에 오르지 않았고 일제에 의해 강제로 을사조약이 체결되자 반대 운동을 전개하였다. 1905년 12월 국권을 빼앗긴 것을 통분하며 자결하였다. 송병순(1839∼1912)은 송병선의 동생으로 학행이 뛰어났으며 문인들을 지도하여 민족의식을 고취하는데 온 힘을 기울였다. 1905년 불법적인 을사조약 체결로 독립운동을 강행하다가 1912년에는 순국할 것을 결심하고 음독 자결하였다.","a":"거창 성암사","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664404.jpg"},{"q":"부북면 ○○○에 거주하는 여주 이씨의 종가로 안채와 사랑채, 별채로 구성되어 있다. 조선 후기 고종 27년(1890) 이익구가 지은 이래 100여년 동안 5대에 걸쳐 집을 옛 그대로 잘 보존하고 있는 전통 가옥이다.","a":"밀양퇴로리이씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664075.jpg"},{"q":"○○군 이원면 현(縣) 마을 옛 ○○○○ 자리에 서 있는 이 ○○○는 1682년 숙종(肅宗) 8년 ○○○○ 이라는 사액(賜額)을 받고 세운 비로서 우암(右菴) 송시열(宋時烈) 선생이 글을 짓고 곡운(谷雲) 김수증 (金壽增)이 글을 썼다. 이 비는 장방형(長方形)의 기초석(基礎石) 위에 비신 (碑身)을 세웠으며 비신 위에는 기와지붕 모양의 비 갓을 사실적으로 표현하여 올려 놓아 조선시대의 전형적인 모습을 잘 나타내고 있다.","a":"옥천 창주서원 묘정비","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650457.jpg"},{"q":"○○○○이 채색하여 그린 8폭의 병풍그림으로, 각 폭마다 각기 다른 풀과 벌레를 그려 놓아 ‘○○○’라고 부르고 있다. 병풍은 율곡 이이 선생을 모시는 송담서원에 있었는데, 순조 4년(1804) 강릉에 산불이 나면서 이 서원까지 불이 번지게 되어 분실되었다. 후에 강릉의 민가에 보관되어 오던 것을 후손인 이장희가 입수하여 율곡 기념관이 건립되자 1965년 기념관에 기증한 것이다. 그림은 자연의 풀과 벌레를 소재로 하여 각 폭마다 꽃과 관련된 풀벌레를 중점으로 그렸으며, 그 종류가 20여 가지나 된다.","a":"신사임당초충도병","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637868.jpg"},{"q":"풍수원성당과 원주성당에 이어 세번 째로 지은 천주교 성당이다. 고종 광무 2년(1898)에는 원주 본당에 소속되어 있었는데, 광무 8년(1904)에 프와오신부가 본당 신부가 되면서 독립된 성당이 되었다. 처음에 성당건물은 초가집이었는데 시잘레신부에 의해 벽돌건물로 지어지게 되었다. 한국전쟁 때 일부 파손된 것을 후에 수리하여 오늘에 이르고 있다. 앞면 중앙에 종탑이 튀어나와 있고 건물은 네모난 모양이며, 붉은 벽돌로 쌓았다. 건물을 받쳐주는 버팀벽은 회색벽돌을 사용하였다.","a":"원주용소막성당","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638126.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상북도 청도군 화양읍 ○○○에 있는 바둑판식 고인돌로 받침돌이 없는 개석식 고인돌이 무리를 이루고 있다. 이곳의 고인돌은 ○○○ 청도천 주변에 50m 정도의 간격을 두고 동쪽에 22기, 서쪽에 12기가 밀집 분포하고 있다.","a":"청도범곡리지석묘군","c":"시도기념물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654563.jpg"}]);